36:     /**
37:      * Interpolates swing time using partialTicks. Makes sure to account for possible negative values
38:      * If there is no swing override, use the default swing
39:      */
40:     public float getSwingProgress(float partialTickTime) {
41:         float currentProgress = this.swingProgress - this.prevSwingProgress;
42: 
43:         if (!isSwingInProgress) {
44:             return mc.thePlayer.getSwingProgress(partialTickTime);
45:         }
46: 
47:         if (currentProgress < 0.0F) {
48:             ++currentProgress;
49:         }
50: 
51:         return this.prevSwingProgress + currentProgress * partialTickTime;
52:     }
