54:     /**
55:      * Gets the number of ticks to play the swing animation for
56:      */
57:     private int getArmSwingAnimationEnd(EntityPlayerSP player) {
58:         return player.isPotionActive(Potion.digSpeed) ? 5 - player.getActivePotionEffect(Potion.digSpeed).getAmplifier() :
59:             (player.isPotionActive(Potion.digSlowdown) ? 8 + player.getActivePotionEffect(Potion.digSlowdown).getAmplifier() * 2 : 6);
60:     }
