66:         final EntityPlayerSP player = mc.thePlayer;
67:         if (player == null) {
68:             return;
69:         }
70: 
71:         prevSwingProgress = swingProgress;
72: 
73:         int max = getArmSwingAnimationEnd(player);
74: 
75:         if (OldAnimationsSettings.punching && mc.gameSettings.keyBindAttack.isKeyDown() &&
76:             mc.objectMouseOver != null &&
77:             mc.objectMouseOver.typeOfHit == MovingObjectPosition.MovingObjectType.BLOCK) {
78:             if (!this.isSwingInProgress || this.swingProgressInt >= max >> 1 || this.swingProgressInt < 0) {
79:                 isSwingInProgress = true;
80:                 swingProgressInt = -1;
81:             }
82:         }
83: 
84:         if (this.isSwingInProgress) {
85:             ++this.swingProgressInt;
86: 
87:             if (this.swingProgressInt >= max) {
88:                 this.swingProgressInt = 0;
89:                 this.isSwingInProgress = false;
90:             }
91:         } else {
92:             this.swingProgressInt = 0;
93:         }
94: 
95:         this.swingProgress = (float) this.swingProgressInt / (float) max;
96:     }
