package net.minecraft.oldanimations;

/**
 * Feature toggles for the 1.7 animation overhaul.
 *
 * <p>These are plain static booleans rather than a Forge/Essential config object. Toggle them
 * in-game with {@code /oldanimations <name> [on|off]} or {@code /oldanimations list}.</p>
 */
public class OldAnimationsSettings
{
    /** Position: all item models use the 1.7 first person placement. */
    public static boolean oldModel = true;

    /** Position: 1.7 bow pullback. */
    public static boolean oldBow = true;

    /** Position: 1.7 sword blocking animation (first person). */
    public static boolean oldSwordBlock = true;

    /** Position: 1.7 fishing rod placement. */
    public static boolean oldRod = true;

    /** Position: 1.7 third person blocking animation. */
    public static boolean oldSwordBlock3 = true;

    /** Interaction: 1.7 eating / drinking animation. */
    public static boolean oldEating = true;

    /** Interaction: 1.7 block hitting animation (swinging at blocks). */
    public static boolean oldBlockhitting = true;

    /** Interaction: smooth transition between sneaking and not sneaking. */
    public static boolean smoothSneaking = true;

    /** Interaction: takes longer to stand up than to crouch. Pairs with {@link #smoothSneaking}. */
    public static boolean longSneaking = true;

    /** Interaction: armour renders red while the wearer is hurt, like 1.7. */
    public static boolean redArmor = true;

    /** Interaction: allows punching blocks while using an item. Visual only. */
    public static boolean punching = true;

    /** Interaction: freezes the item switching animation when right clicking a block. */
    public static boolean itemSwitch = true;

    /** HUD: stops the health bar flashing when taking damage. */
    public static boolean oldHealth = true;

    /** HUD: removes the background boxes and text shadow from the F3 debug screen. */
    public static boolean oldDebugScreen = true;

    /** HUD: removes the player head icons in the tab list. */
    public static boolean oldTab = false;

    /** World: removes the eye line and bounding box from F3+B hitboxes. */
    public static boolean oldDebugHitbox = true;
}

package net.minecraft.oldanimations;

import net.minecraft.client.Minecraft;
import net.minecraft.client.entity.EntityPlayerSP;
import net.minecraft.client.renderer.GlStateManager;
import net.minecraft.client.renderer.ItemRenderer;
import net.minecraft.potion.Potion;
import net.minecraft.util.MovingObjectPosition;

public class AnimationHandler
{
    private static final AnimationHandler INSTANCE = new AnimationHandler();
    private final Minecraft mc = Minecraft.getMinecraft();

    public static AnimationHandler getInstance()
    {
        return INSTANCE;
    }

    public float prevSwingProgress;
    public float swingProgress;
    private int swingProgressInt;
    private boolean isSwingInProgress;

    /**
     * Interpolates swing time using partialTicks. Makes sure to account for possible negative
     * values. If there is no swing override in progress, the vanilla swing is used.
     */
    public float getSwingProgress(float partialTickTime)
    {
        EntityPlayerSP player = this.mc.thePlayer;

        if (player == null)
        {
            return 0.0F;
        }

        if (!this.isSwingInProgress)
        {
            return player.getSwingProgress(partialTickTime);
        }

        float currentProgress = this.swingProgress - this.prevSwingProgress;

        if (currentProgress < 0.0F)
        {
            ++currentProgress;
        }

        return this.prevSwingProgress + currentProgress * partialTickTime;
    }

    /** Number of ticks the swing animation should play for, accounting for mining speed potions. */
    private int getArmSwingAnimationEnd(EntityPlayerSP player)
    {
        if (player.isPotionActive(Potion.digSpeed))
        {
            return 5 - player.getActivePotionEffect(Potion.digSpeed).getAmplifier();
        }

        if (player.isPotionActive(Potion.digSlowdown))
        {
            return 8 + player.getActivePotionEffect(Potion.digSlowdown).getAmplifier() * 2;
        }

        return 6;
    }

    /**
     * Advances the swing progress. Also keeps the swing running while the player is punching a
     * block, which vanilla only does when not actively using an item.
     */
    public void updateSwingProgress()
    {
        EntityPlayerSP player = this.mc.thePlayer;

        if (player == null)
        {
            return;
        }

        this.prevSwingProgress = this.swingProgress;

        int max = getArmSwingAnimationEnd(player);

        if (OldAnimationsSettings.punching && this.mc.gameSettings.keyBindAttack.isKeyDown()
            && this.mc.objectMouseOver != null
            && this.mc.objectMouseOver.typeOfHit == MovingObjectPosition.MovingObjectType.BLOCK)
        {
            if (!this.isSwingInProgress || this.swingProgressInt >= max >> 1 || this.swingProgressInt < 0)
            {
                this.isSwingInProgress = true;
                this.swingProgressInt = -1;
            }
        }

        if (this.isSwingInProgress)
        {
            ++this.swingProgressInt;

            if (this.swingProgressInt >= max)
            {
                this.swingProgressInt = 0;
                this.isSwingInProgress = false;
            }
        }
        else
        {
            this.swingProgressInt = 0;
        }

        this.swingProgress = (float)this.swingProgressInt / (float)max;
    }

    /** Transforms a blocking item to sit in the hand the way it did in 1.7 (third person). */
    public void doSwordBlock3rdPersonTransform()
    {
        if (OldAnimationsSettings.oldSwordBlock3)
        {
            GlStateManager.translate(-0.15F, -0.2F, 0.0F);
            GlStateManager.rotate(70.0F, 1.0F, 0.0F, 0.0F);
            GlStateManager.translate(0.119F, 0.2F, -0.024F);
        }
    }

    /**
     * Applies the 1.7 first person item placement. Ports the vanilla {@code transformFirstPersonItem}
     * matrix so the resulting transform is identical, then optionally hides the vanilla one.
     *
     * @return {@code true} if the vanilla {@code FIRST_PERSON} transform should still be applied
     */
    public boolean doFirstPersonTransform()
    {
        boolean vanillaTransform = false;

        if (!this.mc.gameSettings.isThirdPerson && !this.mc.gameSettings.isHideGUI)
        {
            float equipProgress = 1.0F - (this.mc.getRenderItem().equippedProgress);
            float swingProgress = getSwingProgress(0.0F);

            GlStateManager.translate(0.56F, -0.52F, -0.71999997F);
            GlStateManager.translate(0.0F, equipProgress * -0.6F, 0.0F);
            GlStateManager.rotate(45.0F, 0.0F, 1.0F, 0.0F);

            float f = net.minecraft.util.MathHelper.sin(swingProgress * swingProgress * (float)Math.PI);
            float f1 = net.minecraft.util.MathHelper.sin(
                net.minecraft.util.MathHelper.sqrt_float(swingProgress) * (float)Math.PI);

            GlStateManager.rotate(f * -20.0F, 0.0F, 1.0F, 0.0F);
            GlStateManager.rotate(f1 * -20.0F, 0.0F, 0.0F, 1.0F);
            GlStateManager.rotate(f1 * -80.0F, 1.0F, 0.0F, 0.0F);
            GlStateManager.scale(0.4F, 0.4F, 0.4F);
            vanillaTransform = !OldAnimationsSettings.oldModel;
        }

        return vanillaTransform;
    }

    /**
     * The 1.7 item placement, expressed relative to the vanilla transform so it composes with the
     * vanilla {@code transformFirstPersonItem} matrix. Vanilla is then applied in 3D and negated in
     * 2D to cancel it out.
     */
    public void applyFirstPersonItemTransform()
    {
        if (this.mc.getRenderItem().itemToRender.getItem().shouldRotateAroundWhenRendering()
            && (OldAnimationsSettings.oldModel || OldAnimationsSettings.oldRod))
        {
            GlStateManager.rotate(180.0F, 0.0F, 1.0F, 0.0F);
        }

        GlStateManager.translate(0.02800083F, 0.14999986F, -0.05000016F);
        GlStateManager.scale(1.5F, 1.5F, 1.5F);
        GlStateManager.rotate(5.0F, 0.0F, 1.0F, 0.0F);
        GlStateManager.rotate(335.0F, 0.0F, 0.0F, 1.0F);
        GlStateManager.translate(-0.9375F, -0.0625F, 0.0F);

        if (this.mc.getRenderItem().shouldRenderItemIn3D(this.mc.getRenderItem().itemToRender))
        {
            GlStateManager.scale(0.58823526F, 0.58823526F, 0.58823526F);
            GlStateManager.rotate(-25.0F, 0.0F, 0.0F, 1.0F);
            GlStateManager.rotate(0.0F, 1.0F, 0.0F, 0.0F);
            GlStateManager.rotate(135.0F, 0.0F, 1.0F, 0.0F);
            GlStateManager.translate(0.0F, -0.25F, -0.125F);
            GlStateManager.scale(0.5F, 0.5F, 0.5F);
        }
        else
        {
            GlStateManager.scale(0.5F, 0.5F, 0.5F);
        }
    }

    /** Unused hook kept for parity with the original mod; see {@code MixinItemRenderer}. */
    public static boolean isThirdPerson()
    {
        return ItemRenderer.class != null;
    }
}

package net.minecraft.oldanimations;

import net.minecraft.client.Minecraft;
import net.minecraft.client.entity.EntityPlayerSP;
import net.minecraft.client.renderer.GlStateManager;
import net.minecraft.potion.Potion;
import net.minecraft.util.MovingObjectPosition;

/**
 * Keeps a 1.7 style swing animation running so that punching blocks still animates, even while the
 * player is using an item. Vanilla suspends the swing for the whole duration of item use.
 */
public class AnimationHandler
{
    private static final AnimationHandler INSTANCE = new AnimationHandler();
    private final Minecraft mc = Minecraft.getMinecraft();

    public static AnimationHandler getInstance()
    {
        return INSTANCE;
    }

    public float prevSwingProgress;
    public float swingProgress;
    private int swingProgressInt;
    private boolean isSwingInProgress;

    /**
     * Interpolates swing time using partialTicks, accounting for the wrap-around when the progress
     * counter resets. Falls back to the vanilla swing whenever no override is active.
     */
    public float getSwingProgress(float partialTickTime)
    {
        EntityPlayerSP player = this.mc.thePlayer;

        if (player == null)
        {
            return 0.0F;
        }

        if (!this.isSwingInProgress)
        {
            return player.getSwingProgress(partialTickTime);
        }

        float currentProgress = this.swingProgress - this.prevSwingProgress;

        if (currentProgress < 0.0F)
        {
            ++currentProgress;
        }

        return this.prevSwingProgress + currentProgress * partialTickTime;
    }

    /** Number of ticks the swing animation plays for, accounting for mining speed potions. */
    private int getArmSwingAnimationEnd(EntityPlayerSP player)
    {
        if (player.isPotionActive(Potion.digSpeed))
        {
            return 5 - player.getActivePotionEffect(Potion.digSpeed).getAmplifier();
        }

        if (player.isPotionActive(Potion.digSlowdown))
        {
            return 8 + player.getActivePotionEffect(Potion.digSlowdown).getAmplifier() * 2;
        }

        return 6;
    }

    /** Advances the swing progress. Called once per client tick. */
    public void updateSwingProgress()
    {
        EntityPlayerSP player = this.mc.thePlayer;

        if (player == null)
        {
            return;
        }

        this.prevSwingProgress = this.swingProgress;

        int max = getArmSwingAnimationEnd(player);

        if (OldAnimationsSettings.punching && this.mc.gameSettings.keyBindAttack.isKeyDown()
            && this.mc.objectMouseOver != null
            && this.mc.objectMouseOver.typeOfHit == MovingObjectPosition.MovingObjectType.BLOCK)
        {
            if (!this.isSwingInProgress || this.swingProgressInt >= max >> 1 || this.swingProgressInt < 0)
            {
                this.isSwingInProgress = true;
                this.swingProgressInt = -1;
            }
        }

        if (this.isSwingInProgress)
        {
            ++this.swingProgressInt;

            if (this.swingProgressInt >= max)
            {
                this.swingProgressInt = 0;
                this.isSwingInProgress = false;
            }
        }
        else
        {
            this.swingProgressInt = 0;
        }

        this.swingProgress = (float)this.swingProgressInt / (float)max;
    }

    /** Places a blocking item in the hand the way 1.7 did, for third person rendering. */
    public void doSwordBlock3rdPersonTransform()
    {
        if (OldAnimationsSettings.oldSwordBlock3)
        {
            GlStateManager.translate(-0.15F, -0.2F, 0.0F);
            GlStateManager.rotate(70.0F, 1.0F, 0.0F, 0.0F);
            GlStateManager.translate(0.119F, 0.2F, -0.024F);
        }
    }
}

package net.minecraft.oldanimations;

import net.minecraft.client.Minecraft;
import net.minecraft.client.entity.EntityPlayerSP;

/**
 * 1.7 style sneaking. Vanilla snaps the eye height instantly; this eases it in and can also make
 * standing up take longer than crouching, matching how 1.7 handled the transition.
 */
public class SneakHandler
{
    private static final float START_HEIGHT = 1.62F;
    private static final float END_HEIGHT = 1.54F;

    private static final SneakHandler INSTANCE = new SneakHandler();

    private float eyeHeight = START_HEIGHT;
    private float lastEyeHeight = START_HEIGHT;

    public static SneakHandler getInstance()
    {
        return INSTANCE;
    }

    /** Eye height interpolated by {@code partialTicks} when smooth sneaking is enabled. */
    public float getEyeHeight(float partialTicks)
    {
        if (!OldAnimationsSettings.smoothSneaking)
        {
            return this.eyeHeight;
        }

        return this.lastEyeHeight + (this.eyeHeight - this.lastEyeHeight) * partialTicks;
    }

    /** Advances the sneak interpolation. Called once per client tick. */
    public void onTick()
    {
        this.lastEyeHeight = this.eyeHeight;

        EntityPlayerSP player = Minecraft.getMinecraft().thePlayer;

        if (player == null)
        {
            this.eyeHeight = START_HEIGHT;
            return;
        }

        if (player.isSneaking())
        {
            this.eyeHeight = END_HEIGHT;
        }
        else if (!OldAnimationsSettings.longSneaking)
        {
            this.eyeHeight = START_HEIGHT;
        }
        else if (this.eyeHeight < START_HEIGHT)
        {
            float delta = START_HEIGHT - this.eyeHeight;
            delta *= 0.4F;
            this.eyeHeight = START_HEIGHT - delta;
        }
    }
}

package net.minecraft.oldanimations;

import net.minecraft.client.Minecraft;
import net.minecraft.util.Vec3;

/**
 * 1.7 fishing line offset. Vanilla places the line at a fixed point, 1.7 pulled it in slightly and
 * scaled that offset with the field of view.
 */
public class FishingLineHandler
{
    private static final FishingLineHandler INSTANCE = new FishingLineHandler();

    public static FishingLineHandler getInstance()
    {
        return INSTANCE;
    }

    public Vec3 getOffset()
    {
        if (!OldAnimationsSettings.oldRod)
        {
            return new Vec3(-0.36D, 0.03D, 0.35D);
        }

        double fov = Minecraft.getMinecraft().gameSettings.fovSetting;
        double decimalFov = fov / 110.0D;

        return new Vec3(((-decimalFov + (decimalFov / 2.5D)) - (decimalFov / 8.0D)) + 0.16D, 0.0D, 0.4D);
    }
}

package net.minecraft.oldanimations;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Handles {@code /oldanimations} chat commands. Each setting in {@link OldAnimationsSettings} can be
 * toggled at runtime without a config GUI.
 *
 * <ul>
 *   <li>{@code /oldanimations} - list every setting with its current state</li>
 *   <li>{@code /oldanimations list} - same as above</li>
 *   <li>{@code /oldanimations all on|off} - set every setting</li>
 *   <li>{@code /oldanimations <name> on|off} - toggle one setting</li>
 * </ul>
 */
public class OldAnimationsCommand
{
    private static final String[] NAMES =
    {
        "oldModel",
        "oldBow",
        "oldSwordBlock",
        "oldRod",
        "oldSwordBlock3",
        "oldEating",
        "oldBlockhitting",
        "smoothSneaking",
        "longSneaking",
        "redArmor",
        "punching",
        "itemSwitch",
        "oldHealth",
        "oldDebugScreen",
        "oldTab",
        "oldDebugHitbox"
    };

    private static final String[] DESCRIPTIONS =
    {
        "1.7 item positions",
        "1.7 bow pullback",
        "1.7 block animation",
        "1.7 rod position",
        "1.7 3rd person block animation",
        "1.7 consume animation",
        "1.7 block-hitting animation",
        "Smooth sneaking",
        "Longer unsneak",
        "Red armor",
        "Punching during usage",
        "Item switching animation",
        "Remove health bar flashing",
        "1.7 debug screen",
        "Tab overlay (no player heads)",
        "1.7 debug hitbox"
    };

    /** @return true if the message was a command and has been handled */
    public static boolean handle(String message)
    {
        String trimmed = message.trim();

        if (trimmed.length() == 0 || trimmed.charAt(0) != '/')
        {
            return false;
        }

        String body = trimmed.substring(1);

        if (!body.regionMatches(true, 0, "oldanimations", 0, "oldanimations".length()))
        {
            return false;
        }

        String rest = body.substring("oldanimations".length()).trim();

        if (rest.length() == 0 || rest.regionMatches(true, 0, "list", 0, 4) && rest.length() == 4)
        {
            printList();
            return true;
        }

        String[] parts = rest.split("\\s+");

        if (parts.length == 1)
        {
            OldAnimations.chat("Usage: /oldanimations <name|all|list> [on|off]");
            return true;
        }

        if (parts[0].equalsIgnoreCase("all"))
        {
            Boolean value = parseState(parts);

            if (value == null)
            {
                return true;
            }

            for (String name : NAMES)
            {
                set(name, value);
            }

            OldAnimations.chat("Set all Old Animations settings to " + (value ? "on" : "off") + ".");
            return true;
        }

        Boolean value = parseState(parts);

        if (value == null)
        {
            return true;
        }

        if (!set(parts[0], value))
        {
            OldAnimations.chat("Unknown setting '" + parts[0] + "'. Try /oldanimations list");
            return true;
        }

        OldAnimations.chat(parts[0] + " -> " + (value ? "on" : "off"));
        return true;
    }

    private static Boolean parseState(String[] parts)
    {
        if (parts.length < 2)
        {
            return null;
        }

        String state = parts[1].toLowerCase();

        if (state.equals("on") || state.equals("true") || state.equals("1"))
        {
            return Boolean.TRUE;
        }

        if (state.equals("off") || state.equals("false") || state.equals("0"))
