package net.minecraft.oldanimations;

import net.minecraft.util.ChatComponentText;
import net.minecraft.util.EnumChatFormatting;

/**
 * Entry point for the 1.7 animation overhaul. Ticked from {@code Minecraft.runTick()} and hooked
 * into outgoing chat from {@code ChatComponentText.getUnformattedTextForChat()}.
 */
public class OldAnimations
{
    /** Called once per client tick from {@code Minecraft.runTick()}. */
    public static void onClientTick()
    {
        AnimationHandler.getInstance().updateSwingProgress();
        SneakHandler.getInstance().onTick();
    }

    /**
     * Called when the player sends a chat message.
     *
     * @return true if the message was consumed by Old Animations and must not be sent to the server
     */
    public static boolean onChatMessage(String message)
    {
        return OldAnimationsCommand.handle(message);
    }

    /** Prints a message to chat without a prefix from the server. */
    public static void chat(String message)
    {
        MinecraftHelper.addChatMessage(
            new ChatComponentText(EnumChatFormatting.AQUA + "[OldAnimations] " + EnumChatFormatting.GRAY + message));
    }
}

