/**
     * Whether the held item should be rendered with the "in use" transforms this frame. Vanilla keys
     * this off {@code getItemInUseCount()}; the Old Animations punching tweak also forces it on
     * while right clicking is held, so blocks can be punched whilst eating / blocking / placing.
     */
    private boolean isItemInUseTransformActive()
    {
        AbstractClientPlayer player = this.mc.thePlayer;
        int useCount = player.getItemInUseCount();

        if (useCount > 0)
        {
            return true;
        }

        if (!OldAnimationsSettings.punching || !this.mc.gameSettings.keyBindUseItem.isKeyDown())
        {
            return false;
        }

        EnumAction action = this.itemToRender.getItemUseAction();
        Item item = this.itemToRender.getItem();
        boolean block = action == EnumAction.BLOCK;
        boolean consume = false;

        if (item instanceof ItemFood)
        {
            boolean alwaysEdible = ((ItemFood)item).getAlwaysEdible();

            if (player.canEat(alwaysEdible))
            {
                consume = action == EnumAction.EAT || action == EnumAction.DRINK;
            }
        }

        return (block || consume) && player.isUsingItem();
    }

    /** The swing progress used for the first person swing, honouring the 1.7 block-hitting tweak. */
    private float getFirstPersonSwingProgress(float swingProgress, float partialTicks)
    {
        return OldAnimationsSettings.oldBlockhitting
            ? AnimationHandler.getInstance().getSwingProgress(partialTicks)
            : swingProgress;
    }

    /**
     * Applies the 1.7 item placement.
     *
     * @return the transform type to render the item with; {@code NONE} for flat 2D items, which the
     *         1.7 matrix is already tuned for
     */
    private ItemCameraTransforms.TransformType applyOldFirstPersonTransform()
    {
        GlStateManager.translate(0.02800083F, 0.14999986F, -0.05000016F);
        GlStateManager.scale(1.5F, 1.5F, 1.5F);
        GlStateManager.rotate(5.0F, 0.0F, 1.0F, 0.0F);
        GlStateManager.rotate(335.0F, 0.0F, 0.0F, 1.0F);
        GlStateManager.translate(-0.9375F, -0.0625F, 0.0F);

        if (this.itemRenderer.shouldRenderItemIn3D(this.itemToRender))
        {
            GlStateManager.scale(0.58823526F, 0.58823526F, 0.58823526F);
            GlStateManager.rotate(-25.0F, 0.0F, 0.0F, 1.0F);
            GlStateManager.rotate(0.0F, 1.0F, 0.0F, 0.0F);
            GlStateManager.rotate(135.0F, 0.0F, 1.0F, 0.0F);
            GlStateManager.translate(0.0F, -0.25F, -0.125F);
            GlStateManager.scale(0.5F, 0.5F, 0.5F);
            return ItemCameraTransforms.TransformType.FIRST_PERSON;
        }

        GlStateManager.scale(0.5F, 0.5F, 0.5F);
        return ItemCameraTransforms.TransformType.NONE;
    }

    public void renderItemInFirstPerson(float partialTicks)
    {
        if (!Config.isShaders() || !Shaders.isSkipRenderHand())
        {
            float f = 1.0F - (this.prevEquippedProgress + (this.equippedProgress - this.prevEquippedProgress) * partialTicks);
            AbstractClientPlayer abstractclientplayer = this.mc.thePlayer;
            float f1 = abstractclientplayer.getSwingProgress(partialTicks);
            float f2 = abstractclientplayer.prevRotationPitch + (abstractclientplayer.rotationPitch - abstractclientplayer.prevRotationPitch) * partialTicks;
