     */
    private ItemCameraTransforms.TransformType applyFirstPersonTransformOverride()
    {
        boolean enabled;

        switch (this.itemToRender.getItemUseAction())
        {
            case BOW:
                enabled = OldAnimationsSettings.oldBow;
                break;

            case EAT:
            case DRINK:
                enabled = OldAnimationsSettings.oldEating;
                break;

            case BLOCK:
                enabled = OldAnimationsSettings.oldSwordBlock;
                break;

            case NONE:
            default:
                enabled = this.itemToRender.getItem() instanceof ItemFishingRod
                    ? OldAnimationsSettings.oldRod
                    : OldAnimationsSettings.oldModel;
                break;
        }

        if (!enabled)
        {
            return ItemCameraTransforms.TransformType.FIRST_PERSON;
        }

        return this.applyOldFirstPersonTransform();
    }

