input.newString:
public void printChatMessageWithOptionalDeletion(IChatComponent chatComponent, int chatLineId)
    {
        // Routes the F3 debug overlay text through here, so it must not be logged or styled
        // like an incoming server message.
        if (chatComponent instanceof ChatComponentText
            && ((ChatComponentText)chatComponent).isDebugScreenText())
        {
            this.setChatLine(chatComponent, chatLineId, this.mc.ingameGUI.getUpdateCounter(), true);
            return;
        }

        this.setChatLine(chatComponent, chatLineId, this.mc.ingameGUI.getUpdateCounter(), false);
        logger.info("[CHAT] " + chatComponent.getUnformattedText());
    }

