public class ChatComponentText extends ChatComponentStyle
{
    private final String text;
    private boolean debugScreenText;

    public ChatComponentText(String msg)
    {
        this.text = msg;
    }

    /**
     * Marks this component as part of the F3 debug overlay. Such lines are drawn without the
     * background box or drop shadow, matching how 1.7 rendered the debug screen.
     */
    public ChatComponentText setDebugScreenText()
    {
        this.debugScreenText = true;
        return this;
    }

    public boolean isDebugScreenText()
    {
        return this.debugScreenText;
    }

    public String getChatComponentText_TextValue()
    {
        return this.text;
    }

    public String getUnformattedTextForChat()
    {
        return this.text;
    }

    public ChatComponentText createCopy()
    {
        ChatComponentText chatcomponenttext = new ChatComponentText(this.text);
        chatcomponenttext.setChatStyle(this.getChatStyle().createShallowCopy());
        chatcomponenttext.debugScreenText = this.debugScreenText;

        for (IChatComponent ichatcomponent : this.getSiblings())
        {
            chatcomponenttext.appendSibling(ichatcomponent.createCopy());
        }

        return chatcomponenttext;
    }

