package net.minecraft.oldanimations;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.minecraft.util.EnumChatFormatting;

/**
 * Handles {@code /oldanimations} chat commands so every setting in {@link OldAnimationsSettings} can
 * be toggled at runtime without a config GUI. Fields are discovered reflectively, so adding a new
 * setting only requires adding the boolean to {@link OldAnimationsSettings}.
 *
 * <ul>
 *   <li>{@code /oldanimations} or {@code /oldanimations list} - list every setting</li>
 *   <li>{@code /oldanimations all on|off} - set every setting</li>
 *   <li>{@code /oldanimations <name> on|off} - set one setting</li>
 *   <li>{@code /oldanimations <name>} - toggle one setting</li>
 * </ul>
 */
public class OldAnimationsCommand
{
    private static final String COMMAND = "oldanimations";

    /**
     * @return true if the message was a command and has been handled, meaning it must not be sent on
     *         to the server
     */
    public static boolean handle(String message)
    {
        String trimmed = message.trim();

        if (trimmed.length() < COMMAND.length() + 1 || trimmed.charAt(0) != '/')
        {
            return false;
        }

        String body = trimmed.substring(1);

        if (!body.regionMatches(true, 0, COMMAND, 0, COMMAND.length()))
        {
            return false;
        }

        String rest = body.substring(COMMAND.length()).trim();
        String[] parts = rest.isEmpty() ? new String[0] : rest.split("\\s+");

        if (parts.length == 0 || parts[0].equalsIgnoreCase("list"))
        {
            printList();
            return true;
        }

        if (parts[0].equalsIgnoreCase("all"))
        {
            Boolean value = parseState(parts);

            if (value == null)
            {
                return true;
            }

            int changed = 0;

            for (Field field : getSettings())
            {
                write(field, value);
                ++changed;
            }

            OldAnimations.chat("Set " + changed + " settings to " + (value ? "on" : "off") + ".");
            return true;
        }

        Field field = findSetting(parts[0]);

        if (field == null)
        {
            OldAnimations.chat("Unknown setting '" + parts[0] + "'. Try /" + COMMAND + " list");
            return true;
        }

        Boolean value = parts.length > 1 ? parseState(parts) : !read(field);
        boolean result = value == null ? read(field) : write(field, value);
        OldAnimations.chat(field.getName() + " -> " + (result ? "on" : "off"));
        return true;
    }

    private static Boolean parseState(String[] parts)
    {
        String state = parts[1].toLowerCase();

        if (state.equals("on") || state.equals("true") || state.equals("1"))
        {
            return Boolean.TRUE;
        }

        if (state.equals("off") || state.equals("false") || state.equals("0"))
        {
            return Boolean.FALSE;
        }

        OldAnimations.chat("Expected 'on' or 'off', got '" + parts[1] + "'.");
        return null;
    }

    private static void printList()
    {
        List<String> lines = new ArrayList<String>();

        for (Field field : getSettings())
        {
            boolean value = read(field);
            lines.add((value ? "[" + EnumChatFormatting.GREEN + "on" + EnumChatFormatting.RESET + "]"
                : "[" + EnumChatFormatting.RED + "off" + EnumChatFormatting.RESET + "]")
                + " " + field.getName());
        }

        Collections.sort(lines);
        OldAnimations.chat("Old Animations settings:");

        for (String line : lines)
        {
            OldAnimations.chat(line);
        }

        OldAnimations.chat("Use /" + COMMAND + " <name> [on|off] to change one.");
    }

    /** All public static boolean fields on {@link OldAnimationsSettings}, sorted by name. */
    private static List<Field> getSettings()
    {
        List<Field> fields = new ArrayList<Field>();

        for (Field field : OldAnimationsSettings.class.getDeclaredFields())
        {
            if (Modifier.isStatic(field.getModifiers())
                && Modifier.isPublic(field.getModifiers())
                && field.getType() == Boolean.TYPE)
            {
                field.setAccessible(true);
                fields.add(field);
            }
        }

        Collections.sort(fields, new java.util.Comparator<Field>()
        {
            public int compare(Field a, Field b)
            {
                return a.getName().compareTo(b.getName());
            }
        });
        return fields;
    }

    private static Field findSetting(String name)
    {
        for (Field field : getSettings())
        {
            if (field.getName().equalsIgnoreCase(name))
            {
                return field;
            }
        }

        return null;
    }

    private static boolean read(Field field)
    {
        try
        {
            return field.getBoolean(null);
        }
        catch (IllegalAccessException e)
        {
            throw new RuntimeException(e);
        }
    }

    private static boolean write(Field field, boolean value)
    {
        try
        {
            field.setBoolean(null, value);
            return value;
        }
        catch (IllegalAccessException e)
        {
            throw new RuntimeException(e);
        }
    }
}

package net.minecraft.oldanimations;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.minecraft.util.EnumChatFormatting;

/**
 * Handles {@code /oldanimations} chat commands so every setting in {@link OldAnimationsSettings} can
 * be toggled at runtime without a config GUI. Settings are discovered reflectively, so adding a new
 * toggle only requires adding the boolean to {@link OldAnimationsSettings}.
 *
 * <ul>
 *   <li>{@code /oldanimations} or {@code /oldanimations list} - list every setting</li>
 *   <li>{@code /oldanimations all on|off} - set every setting</li>
 *   <li>{@code /oldanimations <name> on|off} - set one setting</li>
 *   <li>{@code /oldanimations <name>} - toggle one setting</li>
 * </ul>
 */
public class OldAnimationsCommand
{
    private static final String COMMAND = "oldanimations";

    private static final Map<String, String> DESCRIPTIONS = new HashMap<String, String>();

    static
    {
        DESCRIPTIONS.put("oldModel", "1.7 item positions");
        DESCRIPTIONS.put("oldBow", "1.7 bow pullback");
        DESCRIPTIONS.put("oldSwordBlock", "1.7 block animation");
        DESCRIPTIONS.put("oldRod", "1.7 rod position");
        DESCRIPTIONS.put("oldSwordBlock3", "1.7 3rd person block animation");
        DESCRIPTIONS.put("oldEating", "1.7 consume animation");
        DESCRIPTIONS.put("oldBlockhitting", "1.7 block-hitting animation");
        DESCRIPTIONS.put("smoothSneaking", "Smooth sneaking");
        DESCRIPTIONS.put("longSneaking", "Longer unsneak");
        DESCRIPTIONS.put("redArmor", "Red armour when hurt");
        DESCRIPTIONS.put("punching", "Punching while using an item");
        DESCRIPTIONS.put("itemSwitch", "Freeze item switch animation");
        DESCRIPTIONS.put("oldHealth", "Remove health bar flashing");
        DESCRIPTIONS.put("oldDebugScreen", "1.7 debug screen");
        DESCRIPTIONS.put("oldTab", "Tab overlay without player heads");
        DESCRIPTIONS.put("oldDebugHitbox", "1.7 debug hitbox");
    }

    /**
     * @return true if the message was a command and has been handled, meaning it must not be sent on
     *         to the server
     */
    public static boolean handle(String message)
    {
        String[] args = parse(message);

        if (args == null)
        {
            return false;
        }

        if (args.length == 0 || args[0].equalsIgnoreCase("list"))
        {
            printList();
            return true;
        }

        if (args[0].equalsIgnoreCase("all"))
        {
            Boolean value = args.length > 1 ? parseState(args[1]) : Boolean.valueOf(!allEnabled());

            if (value == null)
            {
                return true;
            }

            for (Field field : getSettings())
            {
                write(field, value);
            }

            OldAnimations.chat("Set all " + getSettings().size() + " settings to "
                + (value ? "on" : "off") + ".");
            return true;
        }

        Field field = findSetting(args[0]);

        if (field == null)
        {
            OldAnimations.chat(EnumChatFormatting.RED + "Unknown setting '" + args[0] + "'.");
            OldAnimations.chat("Try /" + COMMAND + " list");
            return true;
        }

        boolean value;

        if (args.length > 1)
        {
            Boolean parsed = parseState(args[1]);

            if (parsed == null)
            {
                return true;
            }

            value = parsed;
        }
        else
        {
            value = !read(field);
        }

        write(field, value);
        OldAnimations.chat(field.getName() + " -> " + (value ? "on" : "off"));
        return true;
    }

    /**
     * Splits a chat message into command arguments, or returns null if it is not an Old Animations
     * command.
     */
    private static String[] parse(String message)
    {
        String trimmed = message.trim();

        if (trimmed.length() < COMMAND.length() + 2 || trimmed.charAt(0) != '/')
        {
            return null;
        }

        String body = trimmed.substring(1);

        if (!body.regionMatches(true, 0, COMMAND, 0, COMMAND.length())
            || body.length() != COMMAND.length()
                && !Character.isWhitespace(body.charAt(COMMAND.length())))
        {
            return null;
        }

        String rest = body.substring(COMMAND.length()).trim();
        return rest.isEmpty() ? new String[0] : rest.split("\\s+");
    }

    private static Boolean parseState(String state)
    {
        String lower = state.toLowerCase();

        if (lower.equals("on") || lower.equals("true") || lower.equals("1"))
        {
            return Boolean.TRUE;
        }

        if (lower.equals("off") || lower.equals("false") || lower.equals("0"))
        {
            return Boolean.FALSE;
        }

        OldAnimations.chat(EnumChatFormatting.RED + "Expected 'on' or 'off', got '" + state + "'.");
        return null;
    }

    private static void printList()
    {
        List<String> lines = new ArrayList<String>();

        for (Field field : getSettings())
        {
            boolean value = read(field);
            String description = DESCRIPTIONS.get(field.getName());
            lines.add((value ? "[" + EnumChatFormatting.GREEN + "on" + EnumChatFormatting.RESET + "]"
                : "[" + EnumChatFormatting.RED + "off" + EnumChatFormatting.RESET + "]")
                + " " + field.getName()
                + (description == null ? "" : EnumChatFormatting.GRAY + " - " + description));
        }

        OldAnimations.chat("Old Animations settings:");

        for (String line : lines)
        {
            OldAnimations.chat(line);
        }

        OldAnimations.chat("Use /" + COMMAND + " <name> [on|off] to change one.");
    }

    private static boolean allEnabled()
    {
        for (Field field : getSettings())
        {
            if (!read(field))
            {
                return false;
            }
        }

        return true;
    }

    /** All public static boolean fields on {@link OldAnimationsSettings}, sorted by name. */
    private static List<Field> getSettings()
    {
        List<Field> fields = new ArrayList<Field>();

        for (Field field : OldAnimationsSettings.class.getDeclaredFields())
        {
            if (Modifier.isStatic(field.getModifiers())
                && Modifier.isPublic(field.getModifiers())
                && field.getType() == Boolean.TYPE)
            {
                field.setAccessible(true);
                fields.add(field);
            }
        }

        Collections.sort(fields, new Comparator<Field>()
        {
            public int compare(Field a, Field b)
            {
                return a.getName().compareTo(b.getName());
            }
        });
        return fields;
    }

    private static Field findSetting(String name)
    {
        for (Field field : getSettings())
        {
            if (field.getName().equalsIgnoreCase(name))
            {
                return field;
            }
        }

        return null;
    }

    private static boolean read(Field field)
    {
        try
        {
            return field.getBoolean(null);
        }
        catch (IllegalAccessException e)
        {
            throw new RuntimeException(e);
        }
    }

    private static boolean write(Field field, boolean value)
    {
        try
        {
            field.setBoolean(null, value);
            return value;
        }
        catch (IllegalAccessException e)
        {
            throw new RuntimeException(e);
        }
    }
}

