/**
     * Applies the 1.7 item placement. This is the transform vanilla applied in 1.7, reproduced
     * verbatim so held items sit exactly where they used to.
     *
     * @return the transform type to render the item with; 3D items keep the vanilla
     *         {@code FIRST_PERSON} transform on top, flat items use {@code NONE}
     */
    private ItemCameraTransforms.TransformType applyOldFirstPersonTransform()
    {
        GlStateManager.translate(0.58800083F, 0.36999986F, -0.77000016F);
        GlStateManager.translate(0.0F, -0.3F, 0.0F);
        GlStateManager.scale(1.5F, 1.5F, 1.5F);
        GlStateManager.rotate(50.0F, 0.0F, 1.0F, 0.0F);
        GlStateManager.rotate(335.0F, 0.0F, 0.0F, 1.0F);
        GlStateManager.translate(-0.9375F, -0.0625F, 0.0F);
        GlStateManager.scale(-2.0F, 2.0F, -2.0F);

        if (this.shouldRenderItemIn3D(this.itemToRender))
        {
            GlStateManager.scale(0.58823526F, 0.58823526F, 0.58823526F);
            GlStateManager.rotate(-25.0F, 0.0F, 0.0F, 1.0F);
            GlStateManager.rotate(0.0F, 1.0F, 0.0F, 0.0F);
            GlStateManager.rotate(135.0F, 0.0F, 1.0F, 0.0F);
            GlStateManager.translate(0.0F, -0.25F, -0.125F);
            GlStateManager.scale(0.5F, 0.5F, 0.5F);
            return ItemCameraTransforms.TransformType.FIRST_PERSON;
        }

        GlStateManager.scale(0.5F, 0.5F, 0.5F);
        return ItemCameraTransforms.TransformType.NONE;
    }

    /**
     * Applies the 1.7 item placement when the matching setting is enabled for the held item's use
     * action.
     *
     * @return the transform type to render the item with
     */
    private ItemCameraTransforms.TransformType applyFirstPersonTransformOverride()
    {
        switch (this.itemToRender.getItemUseAction())
        {
            case BOW:
                if (!OldAnimationsSettings.oldBow)
                {
                    return ItemCameraTransforms.TransformType.FIRST_PERSON;
                }

                break;

            case EAT:
            case DRINK:
                if (!OldAnimationsSettings.oldEating)
                {
                    return ItemCameraTransforms.TransformType.FIRST_PERSON;
                }

                break;

            case BLOCK:
                if (!OldAnimationsSettings.oldSwordBlock)
                {
                    return ItemCameraTransforms.TransformType.FIRST_PERSON;
                }

                break;

            case NONE:
            default:
                boolean rod = this.itemToRender.getItem() instanceof ItemFishingRod;

                if (!rod && !OldAnimationsSettings.oldModel)
                {
                    return ItemCameraTransforms.TransformType.FIRST_PERSON;
                }

                break;
        }

        return this.applyOldFirstPersonTransform();
    }

