private static String[] parse(String message)
    {
        String trimmed = message.trim();

        if (trimmed.length() < 2 || trimmed.charAt(0) != '/')
        {
            return null;
        }

        String body = trimmed.substring(1);

        if (!matchesName(body, COMMAND))
        {
            return matchesName(body, ALIAS) ? splitArgs(body, ALIAS.length()) : null;
        }

        return splitArgs(body, COMMAND.length());
    }

    /** Whether {@code body} starts with {@code name}, followed by end-of-input or whitespace. */
    private static boolean matchesName(String body, String name)
    {
        if (!body.regionMatches(true, 0, name, 0, name.length()))
        {
            return false;
        }

        return body.length() == name.length() || Character.isWhitespace(body.charAt(name.length()));
    }

    private static String[] splitArgs(String body, int nameLength)
    {
        String rest = body.substring(nameLength).trim();
        return rest.isEmpty() ? new String[0] : rest.split("\\s+");
    }

