import net.minecraft.oldanimations.OldAnimationsCommand;
import net.minecraft.oldanimations.OldAnimationsSettings;

public class OldAnimationsCommandTest
{
    private static int failures;

    public static void main(String[] args)
    {
        // Not commands: must be passed through untouched.
        expect(false, "hello", "plain chat");
        expect(false, "/help", "another command");
        expect(false, "/oldanimationsfoo", "prefix must be followed by whitespace");
        expect(false, "/o", "alias too short");

        // Commands: must be consumed.
        expect(true, "/oldanimations", "bare command");
        expect(true, "/oldanimations list", "list subcommand");
        expect(true, "/oam", "alias, bare");
        expect(true, "/oam list", "alias, list");

        // Case insensitivity.
        expect(true, "/OldAnimations", "case insensitive command");
        expect(true, "/oldanimations OLDMODEL off", "case insensitive setting name");

        // Toggling.
        check("oldModel starts on", OldAnimationsSettings.oldModel);
        expect(true, "/oldanimations oldModel off", "turn off");
        check("oldModel is now off", !OldAnimationsSettings.oldModel);
        expect(true, "/oldanimations oldModel", "bare toggle");
        check("oldModel is back on", OldAnimationsSettings.oldModel);

        expect(true, "/oldanimations oldModel off", "off again");
        expect(true, "/oldanimations all on", "all on");
        check("all on restored oldModel", OldAnimationsSettings.oldModel);
        check("all on left oldTab off", !OldAnimationsSettings.oldTab);

        // Bad input must be reported, not thrown, and must not change state.
        expect(true, "/oldanimations oldModel maybe", "bad state word");
        check("oldModel unchanged after bad state", OldAnimationsSettings.oldModel);
        expect(true, "/oldanimations nosuchsetting off", "unknown setting");
        expect(true, "/oldanimations all maybe", "bad state word for all");

        System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURE(S)");
        System.exit(failures == 0 ? 0 : 1);
    }

    private static void expect(boolean handled, String message, String label)
    {
        boolean actual = OldAnimationsCommand.handle(message);

        if (actual != handled)
        {
            System.out.println("FAIL [" + label + "] \"" + message + "\" handled=" + actual
                + " expected=" + handled);
            ++failures;
        }
    }

    private static void check(String label, boolean condition)
    {
        if (!condition)
        {
            System.out.println("FAIL [" + label + "]");
            ++failures;
        }
    }
}

