import net.minecraft.oldanimations.OldAnimationsCommand;
import net.minecraft.oldanimations.OldAnimationsSettings;

public class OldAnimationsCommandTest
{
    private static int failures;

    public static void main(String[] args)
    {
        // ---- Defaults must match the original mod ----
        expectState("oldModel default", OldAnimationsSettings.oldModel, true);
        expectState("oldBow default", OldAnimationsSettings.oldBow, true);
        expectState("oldSwordBlock default", OldAnimationsSettings.oldSwordBlock, true);
        expectState("oldRod default", OldAnimationsSettings.oldRod, true);
        expectState("oldSwordBlock3 default", OldAnimationsSettings.oldSwordBlock3, true);
        expectState("oldEating default", OldAnimationsSettings.oldEating, true);
        expectState("oldBlockhitting default", OldAnimationsSettings.oldBlockhitting, true);
        expectState("smoothSneaking default", OldAnimationsSettings.smoothSneaking, true);
        expectState("longSneaking default", OldAnimationsSettings.longSneaking, true);
        expectState("redArmor default", OldAnimationsSettings.redArmor, true);
        expectState("punching default", OldAnimationsSettings.punching, true);
        expectState("itemSwitch default", OldAnimationsSettings.itemSwitch, true);
        expectState("oldHealth default", OldAnimationsSettings.oldHealth, true);
        expectState("oldDebugScreen default", OldAnimationsSettings.oldDebugScreen, true);
        expectState("oldTab default", OldAnimationsSettings.oldTab, false);
        expectState("oldDebugHitbox default", OldAnimationsSettings.oldDebugHitbox, true);

        // ---- Non-commands must pass through to the server ----
        expect(false, "hello", "plain chat");
        expect(false, "/help", "a different command");
        expect(false, "/oldanimationsfoo", "prefix must end at whitespace");
        expect(false, "/o", "alias must not match a prefix of a word");
        expect(false, "/", "bare slash");
        expect(false, "", "empty message");

        // ---- Commands must be consumed ----
        expect(true, "/oldanimations", "bare command");
        expect(true, "/oldanimations list", "list subcommand");
        expect(true, "/oam", "alias, bare");
        expect(true, "/oam list", "alias, list");
        expect(true, "/OldAnimations", "case insensitive command");

        // ---- Toggling ----
        expect(true, "/oldanimations oldModel off", "set off");
        expectState("oldModel off", OldAnimationsSettings.oldModel, false);

        expect(true, "/oldanimations oldModel", "bare toggle flips on");
        expectState("oldModel back on", OldAnimationsSettings.oldModel, true);

        expect(true, "/oldanimations oldModel off", "set off again");
        expect(true, "/oam oldModel on", "alias sets on");
        expectState("oldModel on via alias", OldAnimationsSettings.oldModel, true);

        expect(true, "/oldanimations OLDMODEL off", "case insensitive setting name");
        expectState("oldModel off via mixed case", OldAnimationsSettings.oldModel, false);
        expect(true, "/oldanimations oldModel on", "restore");

        // ---- all ----
        expect(true, "/oldanimations all off", "all off");
        expectState("all off cleared oldModel", OldAnimationsSettings.oldModel, false);
        expectState("all off cleared oldTab", OldAnimationsSettings.oldTab, false);

        expect(true, "/oldanimations all on", "all on");
        expectState("all on set oldModel", OldAnimationsSettings.oldModel, true);
        expectState("all on set oldTab", OldAnimationsSettings.oldTab, true);

        expect(true, "/oldanimations all off", "all off again");
        expect(true, "/oldanimations all", "bare all flips to on");
        expectState("bare all set everything on", OldAnimationsSettings.oldTab, true);

        // ---- Bad input is reported, never thrown, and never mutates state ----
        expectState("precondition", OldAnimationsSettings.oldModel, true);
        expect(true, "/oldanimations oldModel maybe", "bad state word");
        expectState("bad state word changed nothing", OldAnimationsSettings.oldModel, true);
        expect(true, "/oldanimations nosuchsetting off", "unknown setting");
        expectState("unknown setting changed nothing", OldAnimationsSettings.oldModel, true);
        expect(true, "/oldanimations all maybe", "bad state word for all");
        expectState("bad state word for all changed nothing", OldAnimationsSettings.oldModel, true);

        // ---- Leading / trailing whitespace is tolerated ----
        expect(true, "  /oldanimations list  ", "padded command");
        expect(true, "\t/oam list\t", "tab padded command");

        System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURE(S)");
        System.exit(failures == 0 ? 0 : 1);
    }

    private static void expect(boolean handled, String message, String label)
    {
        boolean actual;

        try
        {
            actual = OldAnimationsCommand.handle(message);
        }
        catch (RuntimeException e)
        {
            System.out.println("FAIL [" + label + "] threw " + e);
            ++failures;
            return;
        }

        if (actual != handled)
        {
            System.out.println("FAIL [" + label + "] \"" + message + "\" handled=" + actual
                + " expected=" + handled);
            ++failures;
        }
    }

    private static void expectState(String label, boolean actual, boolean expected)
    {
        if (actual != expected)
        {
            System.out.println("FAIL [" + label + "] got " + actual + " expected " + expected);
            ++failures;
        }
    }
}

