```java
import net.minecraft.client.main.Main;

import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Start {

    public static void main(String[] args)
    {
        System.setProperty("org.lwjgl.librarypath", new File("../natives/" + (System.getProperty("os.name").startsWith("Windows") ? "windows" : "linux")).getAbsolutePath());

        // Only supply the options Main marks as required if the launcher didn't
        // already pass them; jopt-simple rejects duplicates.
        List<String> extra = new ArrayList<String>();

        if (!hasOption(args, "--version")) {
            extra.addAll(Arrays.asList("--version", "GradleMCP"));
        }

        if (!hasOption(args, "--accessToken")) {
            extra.addAll(Arrays.asList("--accessToken", "0"));
        }

        extra.addAll(Arrays.asList(args));
        Main.main(extra.toArray(new String[0]));
    }

    private static boolean hasOption(String[] args, String option)
    {
        for (int i = 0; i < args.length; ++i)
        {
            if (option.equals(args[i])) return true;
        }
        return false;
    }
