    private static final float MIN_FOV = 1.0F;
    private static final float MAX_FOV = 179.0F;
    private static final float DEFAULT_FOV = 70.0F;

    public String getName() { return "fov"; }

    public String getUsage() { return "/fov <value>|reset"; }

    public boolean execute(Minecraft mc, String[] args)
    {
        if (args.length == 0)
        {
            send(mc, "Current FOV: " + format(mc.gameSettings.fovSetting), EnumChatFormatting.AQUA);
            return true;
        }

        String value = args[0];

        if (value.equalsIgnoreCase("reset"))
        {
            mc.gameSettings.fovSetting = DEFAULT_FOV;
            send(mc, "FOV reset to 70.", EnumChatFormatting.GREEN);
            return true;
        }

        float parsed;

        try { parsed = Float.parseFloat(value); }
        catch (NumberFormatException e)
        {
            send(mc, "Usage: " + getUsage(), EnumChatFormatting.RED);
            return true;
        }

        if (parsed != parsed || Float.isInfinite(parsed))  // NaN/Infinite guard
        {
            send(mc, "Not a valid number: " + value, EnumChatFormatting.RED);
            return true;
        }

        float clamped = Math.max(MIN_FOV, Math.min(MAX_FOV, parsed));
        mc.gameSettings.fovSetting = clamped;

        if (clamped != parsed)
        {
            send(mc, "FOV clamped to " + format(clamped) + " (must be between 1 and 179).", EnumChatFormatting.YELLOW);
        } else {
            send(mc, "FOV set to " + format(clamped) + ".", EnumChatFormatting.GREEN);
        }
        return true;
    }
}
