package net.minecraft.client.commands;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.FontRenderer;
import net.minecraft.client.gui.GuiIngame;
import net.minecraft.client.gui.ScaledResolution;
import net.minecraft.client.renderer.GlStateManager;
import net.minecraft.util.FrameTimer;

/**
 * Standalone FPS readout drawn over the game.
 *
 * <p>Kept separate from the F3 debug screen so it can be positioned and scaled freely.
 * Config lives here rather than in {@code GameSettings} because these are display
 * preferences with no bearing on gameplay.</p>
 */
public final class FpsOverlay
{
    public enum Mode
    {
        /** Vanilla behaviour: a whole-number count sampled once per second. */
        NORMAL,
        /** Exponential moving average, so the number moves instead of jumping. */
        SMOOTH
    }

    private static final double SMOOTHING = 0.1D;

    private static boolean enabled = false;
    private static Mode mode = Mode.NORMAL;

    /** Text scale factor; 1.0 is the normal GUI font size. */
    private static float size = 1.0F;

    /** Top-left corner in scaled GUI pixels. Negative values anchor to the far edge. */
    private static int posX = 4;
    private static int posY = 4;

    private static final double[] samples = new double[240];
    private static int sampleIndex;
    private static int sampleCount;

    private FpsOverlay() {}

    public static boolean isEnabled()
    {
        return enabled;
    }

    public static void setEnabled(boolean value)
    {
        enabled = value;
    }

    public static void toggle()
    {
        enabled = !enabled;
    }

    public static Mode getMode()
    {
        return mode;
    }

    /**
     * @return the name that was set, so the caller can echo what is now active
     */
    public static String setMode(String requested)
    {
        mode = Mode.valueOf(requested.toUpperCase());
        return mode.name().toLowerCase();
    }

    public static float getSize()
    {
        return size;
    }

    public static void setSize(float value)
    {
        size = value;
    }

    public static int getPosX()
    {
        return posX;
    }

    public static int getPosY()
    {
        return posY;
    }

    public static void setPos(int x, int y)
    {
        posX = x;
        posY = y;
    }

    /**
     * Mean frame time over the last {@code frames} frames, in milliseconds.
     *
     * <p>Read from {@link FrameTimer}, which Minecraft already fills every tick, so this
     * costs nothing. Returns 0 when no frames have been recorded yet.</p>
     */
    private static double averageFrameTime(Minecraft mc)
    {
        FrameTimer timer = mc.getFrameTimer();

        if (timer == null)
        {
            return 0.0D;
        }

        int count = Math.min(timer.getCounter(), samples.length);

        if (count <= 0)
        {
            return 0.0D;
        }

        return timer.getAverageFrameTime((long)count, 0) / 1000000.0D;
    }

    private static double currentFps(Minecraft mc, float partialTicks)
    {
        if (mode == Mode.NORMAL)
        {
            return mc.getDebugFPS();
        }

        double frameTime = averageFrameTime(mc);

        if (frameTime <= 0.0D)
        {
            return mc.getDebugFPS();
        }

        double instant = 1000.0D / frameTime;

        if (sampleCount == 0)
        {
            return instant;
        }

        samples[sampleIndex] = instant;
        sampleIndex = (sampleIndex + 1) % samples.length;

        if (sampleCount < samples.length)
        {
            ++sampleCount;
        }

        double total = 0.0D;

        for (int i = 0; i < sampleCount; ++i)
        {
            total += samples[i];
        }

        return total / sampleCount;
    }

    /**
     * Draws the readout. Called from the game overlay each frame while enabled.
     */
    public static void render(Minecraft mc, ScaledResolution resolution, float partialTicks)
    {
        if (!enabled)
        {
            return;
        }

        double fps = currentFps(mc, partialTicks);
        String text = mode == Mode.SMOOTH ? String.format("%.1f FPS", fps) : (int) fps + " FPS";

        GuiIngame ingame = mc.ingameGUI;

        if (ingame == null)
        {
            return;
        }

        FontRenderer font = ingame.getFontRenderer();
        int colour = fps >= 55.0D ? 0xFF55FF55 : (fps >= 25.0D ? 0xFFFFFF55 : 0xFFFF5555);

        // Negative coordinates anchor to the right/bottom edge so the readout stays
        // put when the window is resized.
        int anchorX = posX < 0 ? resolution.getScaledWidth() + posX : posX;
        int anchorY = posY < 0 ? resolution.getScaledHeight() + posY : posY;

        int textWidth = font.getStringWidth(text);
        int textHeight = font.FONT_HEIGHT;

        GlStateManager.pushMatrix();
        GlStateManager.enableBlend();
        GlStateManager.tryBlendFuncSeparate(770, 771, 1, 0);
        GlStateManager.translate((float)anchorX, (float)anchorY, 0.0F);
        GlStateManager.scale(size, size, size);
        font.drawStringWithShadow(text, 1.0F, 1.0F, 0xFF000000);
        font.drawString(text, 0.0F, 0.0F, colour);
        GlStateManager.disableBlend();
        GlStateManager.popMatrix();
    }

    /** Test seam: exposes the resolved draw size for the caller's diagnostics. */
    public static int[] getRenderedSize(Minecraft mc)
    {
        FontRenderer font = mc.ingameGUI.getFontRenderer();
        String text = mode == Mode.SMOOTH ? "000.0 FPS" : "000 FPS";
        int w = font.getStringWidth(text);
        int h = font.FONT_HEIGHT;
        return new int[] {(int)(w * size), (int)(h * size)};
    }
}

