/** Drops the smoothing history so a mode or size change starts from a clean slate. */
private static void resetSmoothing()
{
    lastFrameCounter = 0;
    lastFrameTimeNanos = 0L;
    smoothedFps = -1.0D;
}

private static float clampSize(float value)
{
    if (Float.isNaN(value) || Float.isInfinite(value))
    {
        return 1.0F;
    }

    return Math.max(MIN_SIZE, Math.min(MAX_SIZE, value));
}

/** The {@code fpsdisplay.cfg} inside the game directory, alongside {@code options.txt}. */
public static File getConfigFile()
{
    Minecraft mc = Minecraft.getMinecraft();
    File dir = mc == null ? new File(".") : mc.mcDataDir;
    return new File(dir, FILE_NAME);
}

/**
 * Restores every value to its default and rewrites the config file.
 *
 * <p>Public because {@code /fps reset} exposes it.</p>
 */
public static void reset()
{
    enabled = false;
    mode = Mode.NORMAL;
    size = 1.0F;
    posX = 4;
    posY = 4;
    alpha = 255;
    resetSmoothing();
    save();
}

/**
 * Reads the config file, if it exists. Never throws.
 *
 * <p>A missing file is normal on first run and is not an error. Values are validated
 * rather than trusted: a hand-edited file with an out-of-range size or an unknown mode
 * falls back to the default for that key instead of corrupting the overlay. Unknown
 * keys are ignored so a newer config can carry extras this build does not know about.</p>
 */
public static void load()
{
    File file = getConfigFile();

    if (!file.exists())
    {
        LOGGER.info("No {} found, using FPS display defaults.", FILE_NAME);
        return;
    }

    FileInputStream stream = null;

    try
    {
        BufferedReader reader = new BufferedReader(new InputStreamReader(stream = new FileInputStream(file), "UTF-8"));
        String line;

        while ((line = reader.readLine()) != null)
        {
            line = line.trim();

            if (line.isEmpty() || line.charAt(0) == '#')
            {
                continue;
            }

            int split = line.indexOf('=');

            if (split < 1)
            {
                continue;
            }

            String key = line.substring(0, split).trim();
            String value = line.substring(split + 1).trim();
            applySetting(key, value);
        }
    }
    catch (Exception exception)
    {
        // Never let a bad config stop the game from starting; fall back to defaults.
        LOGGER.error("Failed to read " + file.getAbsolutePath() + ", using FPS display defaults.", exception);
        enabled = false;
        mode = Mode.NORMAL;
        size = 1.0F;
        posX = 4;
        posY = 4;
        alpha = 255;
    }
    finally
    {
        closeQuietly(stream);
        resetSmoothing();
    }

    LOGGER.info("Loaded FPS display config from {} (enabled={}, mode={}, size={}, pos={},{}, alpha={})",
        file.getAbsolutePath(), enabled, mode, size, posX, posY, alpha);
}

/** Applies one {@code key=value} pair, validating as it goes. */
private static void applySetting(String key, String value)
{
    if (key.equals("enabled"))
    {
        enabled = value.equalsIgnoreCase("true");
    }
    else if (key.equals("mode"))
    {
        try
        {
            mode = Mode.valueOf(value.toUpperCase());
        }
        catch (IllegalArgumentException exception)
        {
            LOGGER.warn("Unknown FPS mode \"{}\" in {} , keeping {}", value, FILE_NAME, mode);
        }
    }
    else if (key.equals("size"))
    {
        try
        {
            size = clampSize(Float.parseFloat(value));
        }
        catch (NumberFormatException exception)
        {
            LOGGER.warn("Bad FPS size \"{}\" in {}, keeping {}", value, FILE_NAME, size);
        }
    }
    else if (key.equals("posX"))
    {
        size = size;
        posX = parseIntOr(value, posX);
    }
    else if (key.equals("posY"))
    {
        posY = parseIntOr(value, posY);
    }
    else if (key.equals("alpha"))
    {
        alpha = Math.max(0, Math.min(255, parseIntOr(value, alpha)));
    }
}

private static int parseIntOr(String value, int fallback)
{
    try
    {
        return Integer.parseInt(value);
    }
    catch (NumberFormatException exception)
    {
        LOGGER.warn("Bad whole number \"{}\" in {}, keeping {}", value, FILE_NAME, fallback);
        return fallback;
    }
}

/** Writes the config file. Never throws. */
public static void save()
{
    File file = getConfigFile();
    File parent = file.getParentFile();

    if (parent != null && !parent.exists() && !parent.mkdirs())
    {
        LOGGER.warn("Could not create {} to save FPS display config", parent.getAbsolutePath());
        return;
    }

    PrintWriter writer = null;

    try
    {
        writer = new PrintWriter(new OutputStreamWriter(new FileOutputStream(file), "UTF-8"));
        writer.println("# FPS display configuration - written by /fps");
        writer.println("enabled=" + enabled);
        writer.println("mode=" + mode.name().toLowerCase());
        writer.println("size=" + size);
        writer.println("posX=" + posX);
        writer.println("posY=" + posY);
        writer.println("alpha=" + alpha);
    }
    catch (Exception exception)
    {
        LOGGER.error("Failed to write " + file.getAbsolutePath(), exception);
    }
    finally
    {
        if (writer != null)
        {
            writer.close();
        }
    }
}

private static void closeQuietly(FileInputStream stream)
{
    if (stream != null)
    {
        try
        {
            stream.close();
        }
        catch (IOException ignored) {}
    }
}

