import java.io.File;
import java.lang.reflect.Method;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;

/**
 * Headless exercise of FpsOverlay's config persistence.
 *
 * <p>Runs against the real compiled class in the jar. FpsOverlay.getConfigFile() falls
 * back to new File(".") when Minecraft.getMinecraft() is null, so the test runs in a
 * scratch directory and reads back fpsdisplay.cfg from there.</p>
 */
public class FpsCfgTest
{
    static int failures = 0;

    public static void main(String[] args) throws Exception
    {
        Class<?> fps = Class.forName("net.minecraft.client.commands.FpsOverlay");

        Method setEnabled = fps.getMethod("setEnabled", boolean.class);
        Method setMode = fps.getMethod("setMode", String.class);
        Method setSize = fps.getMethod("setSize", float.class);
        Method setPos = fps.getMethod("setPos", int.class, int.class, int.class);
        Method load = fps.getMethod("load");
        Method save = fps.getMethod("save");
        Method reset = fps.getMethod("reset");
        Method getConfigFile = fps.getMethod("getConfigFile");
        Method isEnabled = fps.getMethod("isEnabled");
        Method getMode = fps.getMethod("getMode");
        Method getSize = fps.getMethod("getSize");
        Method getPosX = fps.getMethod("getPosX");
        Method getPosY = fps.getMethod("getPosY");
        Method getAlpha = fps.getMethod("getAlpha");

        File cfg = (File) getConfigFile.invoke(null);
        System.out.println("config file -> " + cfg.getAbsolutePath());

        // --- reset writes defaults ---------------------------------------------
        reset.invoke(null);
        check("cfg exists after reset", cfg.exists());
        String body = read(cfg);
        System.out.println("--- default file ---\n" + body + "---------------------");
        check("enabled=false written", body.contains("enabled=false"));
        check("mode=normal written", body.contains("mode=normal"));
        check("size written", body.contains("size=1.0"));
        check("posX written", body.contains("posX=4"));
        check("posY written", body.contains("posY=4"));
        check("alpha written", body.contains("alpha=255"));

        // --- round trip --------------------------------------------------------
        setEnabled.invoke(null, Boolean.TRUE);
        setMode.invoke(null, "smooth");
        setSize.invoke(null, Float.valueOf(2.5F));
        setPos.invoke(null, Integer.valueOf(-30), Integer.valueOf(-12), Integer.valueOf(128));

        // Wipe in-memory state back to defaults, then load from disk only.
        reset.invoke(null);
        check("enabled false before load", !((Boolean) isEnabled.invoke(null)).booleanValue());
        load.invoke(null);

        check("enabled round-trips", ((Boolean) isEnabled.invoke(null)).booleanValue());
        check("mode round-trips", getMode.invoke(null).toString().equals("SMOOTH"));
        check("size round-trips", Math.abs(((Float) getSize.invoke(null)).floatValue() - 2.5F) < 0.001F);
        check("posX round-trips", ((Integer) getPosX.invoke(null)).intValue() == -30);
        check("posY round-trips", ((Integer) getPosY.invoke(null)).intValue() == -12);
        check("alpha round-trips", ((Integer) getAlpha.invoke(null)).intValue() == 128);

        // --- reset clears persisted state too ----------------------------------
        reset.invoke(null);
        check("reset disabled it", !((Boolean) isEnabled.invoke(null)).booleanValue());
        check("reset alpha", ((Integer) getAlpha.invoke(null)).intValue() == 255);
        check("reset mode", getMode.invoke(null).toString().equals("NORMAL"));

        // --- clamping happens in setSize, not just in the command --------------
        setSize.invoke(null, Float.valueOf(999.0F));
        check("huge size clamped", ((Float) getSize.invoke(null)).floatValue() == 8.0F);
        setSize.invoke(null, Float.valueOf(0.01F));
        check("tiny size clamped", ((Float) getSize.invoke(null)).floatValue() == 0.5F);
        setSize.invoke(null, Float.valueOf(Float.NaN));
        check("NaN size falls back", ((Float) getSize.invoke(null)).floatValue() == 1.0F);
        setSize.invoke(null, Float.valueOf(Float.POSITIVE_INFINITY));
        check("Inf size falls back", ((Float) getSize.invoke(null)).floatValue() == 1.0F);

        setPos.invoke(null, Integer.valueOf(1), Integer.valueOf(2), Integer.valueOf(9999));
        check("alpha clamped high", ((Integer) getAlpha.invoke(null)).intValue() == 255);
        setPos.invoke(null, Integer.valueOf(1), Integer.valueOf(2), Integer.valueOf(-40));
        check("alpha clamped low", ((Integer) getAlpha.invoke(null)).intValue() == 0);

        // --- hostile / corrupt file must not throw and must land on defaults ---
        write(cfg, "# comment line\n\nthis is not a setting\n"
            + "enabled=true\n"
            + "mode=teleport\n"          // unknown enum
            + "size=abc\n"               // not a number
            + "posX=nope\n"              // not a whole number
            + "posY=-99\n"
            + "alpha=99999\n"            // out of range
            + "unknownKey=whatever\n");  // future-proofing
        load.invoke(null);
        check("corrupt: enabled still applied", ((Boolean) isEnabled.invoke(null)).booleanValue());
        check("corrupt: bad mode ignored", getMode.invoke(null).toString().equals("NORMAL"));
        check("corrupt: bad size ignored", ((Float) getSize.invoke(null)).floatValue() == 1.0F);
        check("corrupt: bad posX ignored", ((Integer) getPosX.invoke(null)).intValue() == 4);
        check("corrupt: good posY applied", ((Integer) getPosY.invoke(null)).intValue() == -99);
        check("corrupt: alpha clamped", ((Integer) getAlpha.invoke(null)).intValue() == 255);

        // --- binary garbage / missing file -------------------------------------
        write(cfg, "\u0000\u0001\u0002not a config at all\n===\n");
        load.invoke(null);
        check("garbage: landed on defaults",
            !((Boolean) isEnabled.invoke(null)).booleanValue()
                && ((Integer) getPosY.invoke(null)).intValue() == 4
                && ((Integer) getAlpha.invoke(null)).intValue() == 255);

        cfg.delete();
        load.invoke(null);
        check("missing file: no throw, defaults", ((Integer) getPosX.invoke(null)).intValue() == 4);
        check("missing file: not recreated by load", !cfg.exists());

        // --- save recreates it -------------------------------------------------
        save.invoke(null);
        check("save recreates file", cfg.exists());

        reset.invoke(null);
        cfg.delete();

        System.out.println();
        System.out.println(failures == 0 ? "ALL CHECKS PASSED" : failures + " CHECK(S) FAILED");
        System.exit(failures == 0 ? 0 : 1);
    }

    static String read(File f) throws Exception
    {
        List<String> lines = Files.readAllLines(Paths.get(f.getAbsolutePath()), Charset.forName("UTF-8"));
        StringBuilder sb = new StringBuilder();
        for (String l : lines) { sb.append(l).append('\n'); }
        return sb.toString();
    }

    static void write(File f, String body) throws Exception
    {
        Files.write(Paths.get(f.getAbsolutePath()), body.getBytes("UTF-8"));
    }

    static void check(String label, boolean ok)
    {
        if (!ok) { failures++; }
        System.out.println((ok ? "  ok   " : "  FAIL ") + label);
    }
}

import java.io.File;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Paths;

/**
 * Headless exercise of FpsOverlay's config persistence.
 *
 * <p>Runs against the real compiled class in the jar. FpsOverlay.getConfigFile() falls
 * back to new File(".") when Minecraft.getMinecraft() is null, so the test runs in a
 * scratch directory and reads back fpsdisplay.cfg from there.</p>
 *
 * <p>clearMemory() wipes the private static fields WITHOUT saving. That separation is
 * the whole point: reset() intentionally rewrites the file, so it cannot be used to set
 * up a round-trip fixture.</p>
 */
public class FpsCfgTest
{
    static int failures = 0;
    static Class<?> fps;

    public static void main(String[] args) throws Exception
    {
        fps = Class.forName("net.minecraft.client.commands.FpsOverlay");

        Method setEnabled = m("setEnabled", boolean.class);
        Method setMode = m("setMode", String.class);
        Method setSize = m("setSize", float.class);
        Method setPos = m("setPos", int.class, int.class, int.class);
        Method load = m("load");
        Method save = m("save");
        Method reset = m("reset");
        Method isEnabled = m("isEnabled");
        Method getMode = m("getMode");
        Method getSize = m("getSize");
        Method getPosX = m("getPosX");
        Method getPosY = m("getPosY");
        Method getAlpha = m("getAlpha");

        File cfg = (File) m("getConfigFile").invoke(null);
        System.out.println("config file -> " + cfg.getAbsolutePath() + "\n");

        // --- 1. reset writes a complete default file ----------------------------
        reset.invoke(null);
        String body = read(cfg);
        System.out.println("--- default file ---");
        System.out.print(body);
        System.out.println("-------------------");
        check("reset creates file", cfg.exists());
        check("enabled=false", body.contains("enabled=false"));
        check("mode=normal", body.contains("mode=normal"));
        check("size=1.0", body.contains("size=1.0"));
        check("posX=4", body.contains("posX=4"));
        check("posY=4", body.contains("posY=4"));
        check("alpha=255", body.contains("alpha=255"));

        // --- 2. round trip: set (auto-saves), wipe memory, load from disk only ---
        setEnabled.invoke(null, Boolean.TRUE);
        setMode.invoke(null, "smooth");
        setSize.invoke(null, Float.valueOf(2.5F));
        setPos.invoke(null, Integer.valueOf(-30), Integer.valueOf(-12), Integer.valueOf(128));
        check("memory holds set values", ((Integer) getPosX.invoke(null)).intValue() == -30);

        clearMemory();
        check("memory wiped", ((Integer) getPosX.invoke(null)).intValue() == 4);
        load.invoke(null);
        check("enabled round-trips", ((Boolean) isEnabled.invoke(null)).booleanValue());
        check("mode round-trips", "SMOOTH".equals(getMode.invoke(null).toString()));
        check("size round-trips", near(((Float) getSize.invoke(null)).floatValue(), 2.5F));
        check("posX round-trips", ((Integer) getPosX.invoke(null)).intValue() == -30);
        check("posY round-trips", ((Integer) getPosY.invoke(null)).intValue() == -12);
        check("alpha round-trips", ((Integer) getAlpha.invoke(null)).intValue() == 128);

        // --- 3. reset clears both memory and disk --------------------------------
        reset.invoke(null);
        check("reset disabled it", !((Boolean) isEnabled.invoke(null)).booleanValue());
        check("reset mode", "NORMAL".equals(getMode.invoke(null).toString()));
        check("reset size", near(((Float) getSize.invoke(null)).floatValue(), 1.0F));
        check("reset alpha", ((Integer) getAlpha.invoke(null)).intValue() == 255);
        clearMemory();
        load.invoke(null);
        check("reset persisted to disk", ((Integer) getPosX.invoke(null)).intValue() == 4);

        // --- 4. clamping lives in the setters, not just the command ---------------
        setSize.invoke(null, Float.valueOf(999.0F));
        check("huge size clamped to 8", near(((Float) getSize.invoke(null)).floatValue(), 8.0F));
        setSize.invoke(null, Float.valueOf(0.01F));
        check("tiny size clamped to 0.5", near(((Float) getSize.invoke(null)).floatValue(), 0.5F));
        setSize.invoke(null, Float.valueOf(Float.NaN));
        check("NaN size rejected", near(((Float) getSize.invoke(null)).floatValue(), 1.0F));
        setSize.invoke(null, Float.valueOf(Float.POSITIVE_INFINITY));
        check("Inf size rejected", near(((Float) getSize.invoke(null)).floatValue(), 1.0F));
        setPos.invoke(null, Integer.valueOf(7), Integer.valueOf(8), Integer.valueOf(9999));
        check("alpha clamped high", ((Integer) getAlpha.invoke(null)).intValue() == 255);
        setPos.invoke(null, Integer.valueOf(7), Integer.valueOf(8), Integer.valueOf(-40));
        check("alpha clamped low", ((Integer) getAlpha.invoke(null)).intValue() == 0);

        // --- 5. hostile file: bad keys ignored, good keys applied ----------------
        clearMemory();
        write(cfg, "# comment line\n\nthis line has no separator\n"
            + "enabled=true\n"
            + "mode=teleport\n"          // unknown enum -> keep default
            + "size=abc\n"               // not a number -> keep default
            + "posX=nope\n"              // not a whole number -> keep default
            + "posY=-99\n"               // valid -> apply
            + "alpha=99999\n"            // out of range -> clamp
            + "unknownKey=whatever\n");  // unknown key -> ignored
        load.invoke(null);
        check("corrupt: valid key applied", ((Boolean) isEnabled.invoke(null)).booleanValue());
        check("corrupt: bad mode ignored", "NORMAL".equals(getMode.invoke(null).toString()));
        check("corrupt: bad size ignored", near(((Float) getSize.invoke(null)).floatValue(), 1.0F));
        check("corrupt: bad posX ignored", ((Integer) getPosX.invoke(null)).intValue() == 4);
        check("corrupt: good posY applied", ((Integer) getPosY.invoke(null)).intValue() == -99);
        check("corrupt: alpha clamped", ((Integer) getAlpha.invoke(null)).intValue() == 255);

        // --- 6. binary garbage ---------------------------------------------------
        clearMemory();
        write(cfg, "\u0000\u0001\u0002not a config at all\n===\nsize\n=\n");
        load.invoke(null);
        check("garbage: no throw, defaults held", atDefaults(isEnabled, getMode, getSize, getPosX, getPosY, getAlpha));

        // --- 7. missing file -----------------------------------------------------
        clearMemory();
        check("file deleted", cfg.delete());
        load.invoke(null);
        check("missing: no throw, defaults held", atDefaults(isEnabled, getMode, getSize, getPosX, getPosY, getAlpha));
        check("missing: load does not recreate", !cfg.exists());

        // --- 8. save recreates, reset is idempotent ------------------------------
        save.invoke(null);
        check("save recreates file", cfg.exists());
        reset.invoke(null);
        reset.invoke(null);
        check("double reset is stable", atDefaults(isEnabled, getMode, getSize, getPosX, getPosY, getAlpha));
        check("double reset file still valid", read(cfg).contains("enabled=false"));
        cfg.delete();

        System.out.println();
        System.out.println(failures == 0 ? "ALL CHECKS PASSED" : failures + " CHECK(S) FAILED");
        System.exit(failures == 0 ? 0 : 1);
    }

    static boolean atDefaults(Method isEnabled, Method getMode, Method getSize,
                              Method getPosX, Method getPosY, Method getAlpha) throws Exception
    {
        return !((Boolean) isEnabled.invoke(null)).booleanValue()
            && "NORMAL".equals(getMode.invoke(null).toString())
