    /** Restores the shipped defaults in memory only. Never calls save(). */
    static void clearMemory() throws Exception
    {
        setF("enabled", Boolean.FALSE);
        setF("mode", Enum.valueOf((Class) fps.getDeclaredClasses()[0], "NORMAL"));
        setF("size", Float.valueOf(1.0F));
