    FileInputStream stream = null;
    Presence seen = new Presence();

    try
    {
        BufferedReader reader = new BufferedReader(new InputStreamReader(stream = new FileInputStream(file), "UTF-8"));
        String line;

        while ((line = reader.readLine()) != null)
        {
            line = line.trim();

            if (line.isEmpty() || line.charAt(0) == '#')
            {
                continue;
            }

            int split = line.indexOf('=');

            if (split < 1)
            {
                continue;
            }

            String key = line.substring(0, split).trim();
            String value = line.substring(split + 1).trim();
            applySetting(key, value, seen);
        }

        // Resolve the two appearance keys in a fixed order rather than in whatever
        // order the lines happened to appear. Otherwise a file containing both
        // "autoColour=true" and a leftover "colour=#..." would end up pinned to that
        // stale colour - which is exactly what save() writes after /fps color auto.
        if (seen.colour && !seen.autoColour)
        {
            autoColour = false;
        }
    }
    catch (Exception exception)
    {
        // Never let a bad config stop the game from starting; fall back to defaults.
        LOGGER.error("Failed to read " + file.getAbsolutePath() + ", using FPS display defaults.", exception);
        resetToDefaults();
    }
    finally
    {
        closeQuietly(stream);
        resetSmoothing();
    }

    LOGGER.info("Loaded FPS display config from {} (enabled={}, mode={}, size={}, pos={},{}, alpha={}, colour={}, shadow={})",
        file.getAbsolutePath(), enabled, mode, size, posX, posY, alpha,
        autoColour ? "auto" : String.format("#%06X", colour), shadow);
}

/** Tracks which appearance keys the file actually contained. */
private static final class Presence
{
    boolean colour;
    boolean autoColour;
}

