/**
 * Strict boolean parse.
 *
 * <p>Anything other than {@code true}/{@code false} keeps the current value, so a
 * typo cannot silently flip a setting. A lenient {@code value.equals("true")} would
 * turn a mistyped {@code shadow=yes} into a silent "off".</p>
 */
private static boolean parseBooleanOr(String value, boolean fallback)
{
    if (value.equalsIgnoreCase("true"))
    {
        return true;
    }

    if (value.equalsIgnoreCase("false"))
    {
        return false;
    }

    LOGGER.warn("Expected true or false but got \"{}\" in {}, keeping {}", value, FILE_NAME, fallback);
    return fallback;
}

