package net.minecraft.client.commands;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.ScaledResolution;
import net.minecraft.client.shader.Framebuffer;
import net.minecraft.client.shader.Shader;
import net.minecraft.client.shader.ShaderGroup;
import net.minecraft.client.shader.ShaderUniform;
import net.minecraft.util.ResourceLocation;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.lwjgl.opengl.GL11;

/**
 * Motion blur, exposed as command-driven settings.
 *
 * <p>Ported from the {@code MotionBlurMod} of the Glide client, which reached vanilla
 * through two event hooks. Both backends are provided:</p>
 *
 * <ul>
 *   <li>{@link Type#SHADER} - a post shader that blends the previous frame with the
 *       current one. Works everywhere, but needs the framebuffer pair from
 *       {@code shaders/post/motion_blur.json}.</li>
 *   <li>{@link Type#ACCUM} - the OpenGL accumulation buffer. Cheaper, but almost no
 *       modern driver provides one, so it detects {@code GL_INVALID_OPERATION} and
 *       switches itself off, exactly as the original did.</li>
 * </ul>
 */
public final class MotionBlur
{
    public enum Type
    {
        SHADER,
        ACCUM
    }

    private static final Logger LOGGER = LogManager.getLogger();
    private static final String FILE_NAME = "motionblur.cfg";

    /** GL_INVALID_OPERATION, which is what glAccum reports with no accum buffer. */
    private static final int GL_INVALID_OPERATION = 1282;

    private static final ResourceLocation SHADER_LOCATION = new ResourceLocation("minecraft:shaders/post/motion_blur.json");

    private static boolean enabled;
    private static Type type = Type.SHADER;
    private static float amount = 0.5F;

    private static ShaderGroup group;
    private static float appliedAmount = -1.0F;
    private static boolean uniformsLoaded;
    private static int prevWidth;
    private static int prevHeight;
    private static long lastErrorCheck;

    private MotionBlur() {}

    public static boolean isEnabled()
    {
        return enabled;
    }

    public static void setEnabled(boolean value)
    {
        enabled = value;

        if (!value)
        {
            // Drop the shader group so a later enable rebuilds it against the current size.
            group = null;
            uniformsLoaded = false;
        }

        save();
    }

    public static Type getType()
    {
        return type;
    }

    public static void setType(Type value)
    {
        type = value;
        group = null;
        uniformsLoaded = false;
        appliedAmount = -1.0F;
        save();
    }

    public static float getAmount()
    {
        return amount;
    }

    public static void setAmount(float value)
    {
        amount = clampAmount(value);
        save();
    }

    static float clampAmount(float value)
    {
        if (Float.isNaN(value) || Float.isInfinite(value))
        {
            return 0.5F;
        }

        return Math.max(0.1F, Math.min(0.9F, value));
    }

    // --- SHADER backend ---------------------------------------------------------

    /**
     * Runs after the world frame is composited. Draws the blur when the shader backend
     * is selected.
     */
    public static void render(Minecraft mc, float partialTicks)
    {
        if (!enabled || type != Type.SHADER)
        {
            return;
        }

        ScaledResolution resolution = new ScaledResolution(mc);

        if (group == null || prevWidth != resolution.getScaledWidth() || prevHeight != resolution.getScaledHeight())
        {
            prevWidth = resolution.getScaledWidth();
            prevHeight = resolution.getScaledHeight();
            buildGroup(mc);
        }

        if (group == null)
        {
            return;
        }

        if (!uniformsLoaded || appliedAmount != amount)
        {
            uniformsLoaded = true;
            appliedAmount = amount;

            for (Shader shader : group.getListShaders())
            {
                ShaderUniform factor = shader.getShaderManager().getShaderUniform("BlurFactor");

                if (factor != null)
                {
                    factor.set(amount);
                }
            }
        }

        net.minecraft.client.renderer.GlStateManager.matrixMode(5890);
        net.minecraft.client.renderer.GlStateManager.pushMatrix();
        net.minecraft.client.renderer.GlStateManager.loadIdentity();
        group.loadShaderGroup(partialTicks);
        net.minecraft.client.renderer.GlStateManager.popMatrix();
    }

    private static void buildGroup(Minecraft mc)
    {
        try
        {
            group = new ShaderGroup(mc.getTextureManager(), mc.getResourceManager(), mc.getFramebuffer(), SHADER_LOCATION);
            group.createBindFramebuffers(mc.displayWidth, mc.displayHeight);
            uniformsLoaded = false;
            appliedAmount = -1.0F;
        }
        catch (Exception exception)
        {
            group = null;
            uniformsLoaded = false;
            LOGGER.error("Could not build the motion blur shader group; staying off.", exception);
        }
    }

    // --- ACCUM backend ----------------------------------------------------------

    /**
     * Runs from {@code Minecraft.updateDisplay}. Blends this frame with the accumulation
     * buffer, and turns the feature off if the driver rejects it.
     */
    public static void updateDisplay(Minecraft mc)
    {
        if (!enabled || type != Type.ACCUM || mc.thePlayer == null)
        {
            return;
        }

        GL11.glAccum(GL11.GL_ACCUM, amount);
        GL11.glAccum(GL11.GL_LOAD, 1.0F - amount);
        GL11.glAccum(GL11.GL_RETURN, 1.0F);

        if (lastErrorCheck + 1000L >= System.currentTimeMillis())
        {
            return;
        }

        lastErrorCheck = System.currentTimeMillis();

        if (GL11.glGetError() == GL_INVALID_OPERATION)
        {
            LOGGER.warn("No accumulation buffer available; motion blur accum mode disabled.");
            setEnabled(false);
        }
    }

    // --- persistence ------------------------------------------------------------

    public static File getConfigFile()
    {
        Minecraft mc = Minecraft.getMinecraft();
        File dir = mc == null ? new File(".") : mc.mcDataDir;
        return new File(dir, FILE_NAME);
    }

    private static void resetToDefaults()
    {
        enabled = false;
        type = Type.SHADER;
        amount = 0.5F;
    }

    public static void reset()
    {
        group = null;
        uniformsLoaded = false;
        appliedAmount = -1.0F;
        resetToDefaults();
        save();
    }

    public static void load()
    {
        File file = getConfigFile();

        if (!file.exists())
        {
            LOGGER.info("No {} found, using motion blur defaults.", FILE_NAME);
            return;
        }

        FileInputStream stream = null;

        try
        {
            BufferedReader reader = new BufferedReader(new InputStreamReader(stream = new FileInputStream(file), "UTF-8"));
            String line;

            while ((line = reader.readLine()) != null)
            {
                line = line.trim();

                if (line.isEmpty() || line.charAt(0) == '#')
                {
                    continue;
                }

                int split = line.indexOf('=');

                if (split < 1)
                {
                    continue;
                }

                applySetting(line.substring(0, split).trim(), line.substring(split + 1).trim());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error("Failed to read " + file.getAbsolutePath() + ", using motion blur defaults.", exception);
            resetToDefaults();
        }
        finally
        {
            closeQuietly(stream);
        }

        LOGGER.info("Loaded motion blur config from {}", file.getAbsolutePath());
    }

    private static void applySetting(String key, String value)
    {
        if (key.equals("enabled"))
        {
            enabled = value.equalsIgnoreCase("true");
        }
        else if (key.equals("type"))
        {
            try
            {
                type = Type.valueOf(value.toUpperCase());
            }
            catch (IllegalArgumentException exception)
            {
                LOGGER.warn("Unknown motion blur type \"{}\" in {}, keeping {}", value, FILE_NAME, type);
            }
        }
        else if (key.equals("amount"))
        {
            try
            {
                amount = clampAmount(Float.parseFloat(value));
            }
            catch (NumberFormatException exception)
            {
                LOGGER.warn("Bad amount \"{}\" in {}, keeping {}", value, FILE_NAME, amount);
            }
        }
    }

    public static void save()
    {
        File file = getConfigFile();
        File parent = file.getParentFile();

        if (parent != null && !parent.exists() && !parent.mkdirs())
        {
            LOGGER.warn("Could not create {} to save motion blur config", parent.getAbsolutePath());
            return;
        }

        PrintWriter writer = null;

        try
        {
            writer = new PrintWriter(new OutputStreamWriter(new FileOutputStream(file), "UTF-8"));
            writer.println("# Motion blur - written by /mb");
            writer.println("enabled=" + enabled);
            writer.println("type=" + type.name().toLowerCase());
            writer.println("amount=" + amount);
        }
        catch (Exception exception)
        {
            LOGGER.error("Failed to write " + file.getAbsolutePath(), exception);
        }
        finally
        {
            if (writer != null)
            {
                writer.close();
            }
        }
    }

    private static void closeQuietly(FileInputStream stream)
    {
        if (stream != null)
        {
            try
            {
                stream.close();
            }
            catch (IOException ignored) {}
        }
    }
}

