private static float smooth(float target, double speed)
{
    long now = System.currentTimeMillis();
    long delta = now - smoothLastMs;
    smoothLastMs = now;
    if (speed > 28) speed = 28;
    double deltaValue = speed != 0.0 ? Math.abs(target - smoothValue) * 0.35F / (10.0 / speed) : 0.0;
    // calculateCompensation
    float diff = smoothValue - target;
    double add = delta * (deltaValue / 50);
    if (diff > deltaValue) { if (smoothValue - add > target) smoothValue -= add; else smoothValue = target; }
    else if (diff < -deltaValue) { if (smoothValue + add < target) smoothValue += add; else smoothValue = target; }
    else if (Math.abs(smoothValue - target) < 0.03F) smoothValue = target;
    return smoothValue;
}
