// Standard screen-space quad vertex shader, same as blit.vsh. The fragment stage
// samples the previous frame and the current one, so it only needs texCoord.

attribute vec4 Position;

uniform mat4 ProjMat;
uniform vec2 OutSize;

varying vec2 texCoord;

void main(){
    vec4 outPos = ProjMat * vec4(Position.xy, 0.0, 1.0);
    gl_Position = vec4(outPos.xy, 0.2, 1.0);

    texCoord = Position.xy / OutSize;
    texCoord.y = 1.0 - texCoord.y;
}

#version 120

// Blends the previous frame (PrevSampler) into the current one (DiffuseSampler).
// BlurFactor is pushed in from MotionBlur every time the amount changes.

uniform sampler2D DiffuseSampler;
uniform sampler2D PrevSampler;

varying vec2 texCoord;

uniform float BlurFactor;

void main() {
    gl_FragColor = mix(texture2D(DiffuseSampler, texCoord), texture2D(PrevSampler, texCoord), BlurFactor);
    gl_FragColor.w = 1.0;
}

