import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.minecraft.client.commands.Animations;
import net.minecraft.client.commands.MotionBlur;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

/**
 * Headless checks for Animations + MotionBlur config handling and for the motion blur
 * shader JSON. Runs with no Minecraft instance, so getConfigFile() falls back to the CWD.
 */
public class NewSettingsTest
{
    static int checks = 0;
    static int fails = 0;

    static void check(String name, boolean ok)
    {
        checks++;

        if (!ok)
        {
            fails++;
            System.out.println("  FAIL  " + name);
        }
    }

    static void eq(String name, Object expected, Object actual)
    {
        boolean ok = expected == null ? actual == null : expected.equals(actual);
        checks++;

        if (!ok)
        {
            fails++;
            System.out.println("  FAIL  " + name + ": expected <" + expected + "> got <" + actual + ">");
        }
    }

    static void clearMemory(Class<?> owner) throws Exception
    {
        // Null out every non-final static field so each test starts from defaults.
        for (Field field : owner.getDeclaredFields())
        {
            if (field.getModifiers() & java.lang.reflect.Modifier.STATIC == 0 || field.getModifiers() & java.lang.reflect.Modifier.FINAL != 0)
            {
                continue;
            }

            if (field.getType().isPrimitive())
            {
                continue;
            }

            field.setAccessible(true);
            field.set(null, null);
        }

        for (Field field : owner.getDeclaredFields())
        {
            if (field.getType() != boolean.class && field.getType() != int.class
                && field.getType() != float.class && field.getType() != long.class)
            {
                continue;
            }

            field.setAccessible(true);

            if (field.getType() == boolean.class) field.setBoolean(null, false);
            else if (field.getType() == int.class) field.setInt(null, 0);
            else if (field.getType() == float.class) field.setFloat(null, 0.0F);
            else field.setLong(null, 0L);
        }
    }

    static boolean raw(String key)
    {
        try
        {
            Method m = Animations.class.getDeclaredMethod("rawFlag", String.class);
            m.setAccessible(true);
            return (Boolean)m.invoke(null, key);
        }
        catch (Exception e)
        {
            throw new RuntimeException(e);
        }
    }

    static void write(String text) throws Exception
    {
        PrintWriter w = new PrintWriter(new OutputStreamWriter(new FileOutputStream("animations.cfg"), "UTF-8"));
        w.print(text);
        w.close();
    }

    static void writeBlur(String text) throws Exception
    {
        PrintWriter w = new PrintWriter(new OutputStreamWriter(new FileOutputStream("motionblur.cfg"), "UTF-8"));
        w.print(text);
        w.close();
    }

    static String read(String file) throws Exception
    {
        java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
        FileInputStream in = new FileInputStream(file);
        byte[] buf = new byte[4096];
        int n;

        while ((n = in.read(buf)) > 0)
        {
            out.write(buf, 0, n);
        }

        in.close();
        return new String(out.toByteArray(), "UTF-8");
    }

    public static void main(String[] args) throws Exception
    {
        new File("animations.cfg").delete();
        new File("motionblur.cfg").delete();

        System.out.println("== Animations defaults ==");
        clearMemory(Animations.class);
        Animations.load();  // no file -> defaults
        eq("default enabled", false, Animations.isEnabled());
        eq("default blockHit raw", true, raw("blockHit"));
        eq("default pushing raw", true, raw("pushing"));
        eq("default pushingParticle raw", true, raw("pushingParticle"));
        eq("default sneak raw", true, raw("sneak"));
        eq("default smoothSneak raw", false, raw("smoothSneak"));
        eq("default smoothSneakSpeed", 6.0F, Animations.getSmoothSneakSpeed());
        eq("default health raw", true, raw("health"));
        eq("default armorDamage raw", false, raw("armorDamage"));
        eq("default itemSwitch raw", false, raw("itemSwitch"));
        eq("default rod raw", false, raw("rod"));
        eq("master off masks blockHit", false, Animations.isBlockHit());
        eq("master off masks sneak", false, Animations.isSneak());
        eq("master off masks armorDamage", false, Animations.isArmorDamage());

        System.out.println("== Animations master gates every accessor ==");
        clearMemory(Animations.class);
        Animations.load();
        Animations.setEnabled(true);
        eq("gated blockHit on", true, Animations.isBlockHit());
        eq("gated pushing", true, Animations.isPushing());
        eq("gated pushingParticle", true, Animations.isPushingParticle());
        eq("gated sneak", true, Animations.isSneak());
        eq("gated health", true, Animations.isHealth());
        Animations.setEnabled(false);
        eq("gated blockHit off again", false, Animations.isBlockHit());
        eq("gated rod stays off", false, Animations.isRod());
        eq("gated itemSwitch stays off", false, Animations.isItemSwitch());
        eq("gated armorDamage stays off", false, Animations.isArmorDamage());
        eq("gated smoothSneak stays off", false, Animations.isSmoothSneak());

        System.out.println("== Animations round trip ==");
        clearMemory(Animations.class);
        Animations.load();
        Animations.setEnabled(true);
        setFlag("blockHit", false);
        setFlag("armorDamage", true);
        setFlag("rod", true);
        Animations.setSmoothSneakSpeed(13.5F);
        String saved = read("animations.cfg");
        check("save wrote blockHit=false", saved.contains("blockHit=false"));
        check("save wrote armorDamage=true", saved.contains("armorDamage=true"));
        check("save wrote rod=true", saved.contains("rod=true"));
        check("save wrote smoothSneakSpeed=13.5", saved.contains("smoothSneakSpeed=13.5"));
        check("save wrote enabled=true", saved.contains("enabled=true"));

        clearMemory(Animations.class);
        Animations.load();
        eq("round trip enabled", true, Animations.isEnabled());
        eq("round trip blockHit", false, raw("blockHit"));
        eq("round trip armorDamage", true, raw("armorDamage"));
        eq("round trip rod", true, raw("rod"));
        eq("round trip smoothSneakSpeed", 13.5F, Animations.getSmoothSneakSpeed());
        eq("round trip default sneak untouched", true, raw("sneak"));

        System.out.println("== Animations bad input ==");
        clearMemory(Animations.class);
        write("# comment\nenabled=true\nblockHit=yes\nsneak=FALSE\nunknownKey=1\narmorDamage=\n\nnot a setting\nsmoothSneakSpeed=abc\nrod=false\n");
        Animations.load();
        eq("enabled parsed", true, Animations.isEnabled());
        eq("lenient boolean keeps default", true, raw("blockHit"));
        eq("FALSE parsed case-insensitively", false, raw("sneak"));
        eq("unknown key ignored (armorDamage default)", false, raw("armorDamage"));
        eq("bad speed keeps default", 6.0F, Animations.getSmoothSneakSpeed());
        eq("trailing rod=false honoured", false, raw("rod"));

        System.out.println("== Animations speed clamping ==");
        clearMemory(Animations.class);
        write("smoothSneakSpeed=99\n");
        Animations.load();
        eq("high clamps to 20", 20.0F, Animations.getSmoothSneakSpeed());
        clearMemory(Animations.class);
        write("smoothSneakSpeed=-4\n");
        Animations.load();
        eq("low clamps to 0.5", 0.5F, Animations.getSmoothSneakSpeed());
        clearMemory(Animations.class);
        write("smoothSneakSpeed=NaN\n");
        Animations.load();
        eq("NaN falls back to 6", 6.0F, Animations.getSmoothSneakSpeed());
        clearMemory(Animations.class);
        write("smoothSneakSpeed=Infinity\n");
        Animations.load();
        eq("Infinity falls back to 6", 6.0F, Animations.getSmoothSneakSpeed());

        System.out.println("== Animations reset ==");
        clearMemory(Animations.class);
        write("enabled=true\nrod=true\nsmoothSneakSpeed=19\n");
        Animations.load();
        eq("pre-reset enabled", true, Animations.isEnabled());
        Animations.reset();
        eq("reset enabled", false, Animations.isEnabled());
        eq("reset rod", false, raw("rod"));
        eq("reset speed", 6.0F, Animations.getSmoothSneakSpeed());
        String afterReset = read("animations.cfg");
        check("reset rewrote file enabled=false", afterReset.contains("enabled=false"));
        check("reset rewrote file rod=false", afterReset.contains("rod=false"));
        check("reset rewrote file speed=6.0", afterReset.contains("smoothSneakSpeed=6.0"));

        System.out.println("== Animations unknown key to setFlag throws ==");
        boolean threw = false;
        try
        {
            setFlag("nope", true);
        }
        catch (IllegalArgumentException e)
        {
            threw = true;
        }
        check("setFlag rejects unknown key", threw);

        System.out.println("== MotionBlur defaults ==");
        clearMemory(MotionBlur.class);
        MotionBlur.load();
        eq("blur default enabled", false, MotionBlur.isEnabled());
        eq("blur default type", MotionBlur.Type.SHADER, MotionBlur.getType());
        eq("blur default amount", 0.5F, MotionBlur.getAmount());

        System.out.println("== MotionBlur round trip ==");
        clearMemory(MotionBlur.class);
        MotionBlur.load();
        MotionBlur.setEnabled(true);
        MotionBlur.setType(MotionBlur.Type.ACCUM);
        MotionBlur.setAmount(0.25F);
        String bsaved = read("motionblur.cfg");
        check("blur save enabled=true", bsaved.contains("enabled=true"));
        check("blur save type=accum", bsaved.contains("type=accum"));
        check("blur save amount=0.25", bsaved.contains("amount=0.25"));

        clearMemory(MotionBlur.class);
        MotionBlur.load();
        eq("blur round trip enabled", true, MotionBlur.isEnabled());
        eq("blur round trip type", MotionBlur.Type.ACCUM, MotionBlur.getType());
        eq("blur round trip amount", 0.25F, MotionBlur.getAmount());

        System.out.println("== MotionBlur bad input ==");
        clearMemory(MotionBlur.class);
        writeBlur("enabled=true\ntype=bogus\namount=NaN\n");
        MotionBlur.load();
        eq("blur enabled parsed", true, MotionBlur.isEnabled());
        eq("blur bad type keeps SHADER", MotionBlur.Type.SHADER, MotionBlur.getType());
        eq("blur NaN amount falls back", 0.5F, MotionBlur.getAmount());

        clearMemory(MotionBlur.class);
        writeBlur("type=SHA\n");
        MotionBlur.load();
        eq("blur type case-insensitive", MotionBlur.Type.SHADER, MotionBlur.getType());
        clearMemory(MotionBlur.class);
        writeBlur("type=Accum\n");
        MotionBlur.load();
        eq("blur type accum case-insensitive", MotionBlur.Type.ACCUM, MotionBlur.getType());

        System.out.println("== MotionBlur amount clamping ==");
        eq("clamp high", 0.9F, MotionBlur.clampAmount(5.0F));
        eq("clamp low", 0.1F, MotionBlur.clampAmount(-5.0F));
        eq("clamp NaN", 0.5F, MotionBlur.clampAmount(Float.NaN));
        eq("clamp Inf", 0.5F, MotionBlur.clampAmount(Float.POSITIVE_INFINITY));
        eq("clamp in range", 0.4F, MotionBlur.clampAmount(0.4F));

        System.out.println("== MotionBlur reset ==");
        clearMemory(MotionBlur.class);
        writeBlur("enabled=true\ntype=accum\namount=0.8\n");
        MotionBlur.load();
        MotionBlur.reset();
        eq("blur reset enabled", false, MotionBlur.isEnabled());
        eq("blur reset type", MotionBlur.Type.SHADER, MotionBlur.getType());
        eq("blur reset amount", 0.5F, MotionBlur.getAmount());
        String bAfter = read("motionblur.cfg");
        check("blur reset rewrote enabled=false", bAfter.contains("enabled=false"));
        check("blur reset rewrote type=shader", bAfter.contains("type=shader"));

        System.out.println("== shader JSON structure ==");
        JsonObject post = new JsonParser().parse(
            new java.io.InputStreamReader(new FileInputStream(
                "C:\\Users\\dinhv\\IdeaProjects\\GradleMCPBase\\src\\main\\resources\\assets\\minecraft\\shaders\\post\\motion_blur.json"), "UTF-8")).getAsJsonObject();
        check("post has targets", post.has("targets"));
        JsonArray targets = post.getAsJsonArray("targets");
        eq("targets count", 2, targets.size());
        eq("targets[0] is swap", "swap", targets.get(0).getAsString());
        eq("targets[1] is previous", "previous", targets.get(1).getAsString());
        JsonArray passes = post.getAsJsonArray("passes");
        eq("pass count", 3, passes.size());

        JsonObject p0 = passes.get(0).getAsJsonObject();
        eq("pass0 name", "motion_blur", p0.get("name").getAsString());
        eq("pass0 intarget", "minecraft:main", p0.get("intarget").getAsString());
        eq("pass0 outtarget", "swap", p0.get("outtarget").getAsString());
        JsonObject aux = p0.getAsJsonArray("auxtargets").get(0).getAsJsonObject();
        eq("pass0 aux name", "PrevSampler", aux.get("name").getAsString());
        eq("pass0 aux id", "previous", aux.get("id").getAsString());

        JsonObject p1 = passes.get(1).getAsJsonObject();
        eq("pass1 name", "blit", p1.get("name").getAsString());
        eq("pass1 outtarget", "previous", p1.get("outtarget").getAsString());
        JsonObject p2 = passes.get(2).getAsJsonObject();
        eq("pass2 outtarget", "minecraft:main", p2.get("outtarget").getAsString());

        System.out.println("== shader program files ==");
        String progDir = "C:\\Users\\dinhv\\IdeaProjects\\GradleMCPBase\\src\\main\\resources\\assets\\minecraft\\shaders\\program\\";
        String fsh = read(progDir + "motion_blur.fsh");
        check("fsh declares PrevSampler", fsh.contains("PrevSampler"));
        check("fsh declares BlurFactor", fsh.contains("BlurFactor"));
        check("fsh mixes the two samplers", fsh.contains("mix(texture2D(DiffuseSampler"));
        String vsh = read(progDir + "motion_blur.vsh");
        check("vsh declares texCoord", vsh.contains("varying vec2 texCoord"));
        check("vsh has no unmatched varying", !vsh.contains("oneTexel"));
        check("fsh has no unmatched varying", !fsh.contains("oneTexel"));

        new File("animations.cfg").delete();
        new File("motionblur.cfg").delete();

        System.out.println();
        System.out.println(fails == 0 ? ("ALL " + checks + " CHECKS PASSED") : (fails + " of " + checks + " CHECKS FAILED"));
        System.exit(fails == 0 ? 0 : 1);
    }

    static void setFlag(String key, boolean value)
    {
        try
        {
            Method m = Animations.class.getDeclaredMethod("setFlag", String.class, boolean.class);
            m.setAccessible(true);
            m.invoke(null, key, value);
        }
        catch (java.lang.reflect.InvocationTargetException e)
        {
            if (e.getCause() instanceof RuntimeException) throw (RuntimeException)e.getCause();
            throw new RuntimeException(e);
        }
        catch (Exception e)
        {
            throw new RuntimeException(e);
        }
    }
}

