/**
 * Captures every static field's value as the class left it after static init, so
 * each test can be restored to the real defaults rather than to zero. Zeroing would
 * destroy the initialisers (blockHit=true, smoothSneakSpeed=6.0) that are exactly
 * what the defaults test is asserting.
 */
static final java.util.Map<Class<?>, java.util.Map<Field, Object>> PRISTINE =
    new java.util.LinkedHashMap<Class<?>, java.util.Map<Field, Object>>();

static void snapshot(Class<?> owner) throws Exception
{
    java.util.Map<Field, Object> values = new java.util.LinkedHashMap<Field, Object>();

    for (Field field : owner.getDeclaredFields())
    {
        if ((field.getModifiers() & java.lang.reflect.Modifier.STATIC) == 0)
        {
            continue;
        }

        field.setAccessible(true);
        values.put(field, field.get(null));
    }

    PRISTINE.put(owner, values);
}

static void restore(Class<?> owner) throws Exception
{
    for (java.util.Map.Entry<Field, Object> entry : PRISTINE.get(owner).entrySet())
    {
        try
        {
            entry.getKey().set(null, entry.getValue());
        }
        catch (IllegalAccessException ignored)
        {
            // final constant, nothing to restore
        }
    }
}

