/**
 * Free look: the camera swings off the player's body rotation while the key is held, or
 * while a toggle is on, so you can aim sideways without turning your character.
 *
 * <p>Vanilla funnels every mouse-look update through
 * {@code EntityPlayerSP.setAngles(yaw, pitch)}, which adds to the body rotation. That single
 * call is where this class takes over: while free look is active the deltas accumulate into
 * private yaw/pitch offsets instead, and the body never turns. The offsets are added back in
 * {@code EntityRenderer.orientCamera}, and {@code EntityPlayerSP.getLook} adds them too so the
 * crosshair, block outline and block breaking follow the camera rather than the body.</p>
 *
 * <p>Persisted to {@value #FILE_NAME} in the game directory. The key itself is a normal
 * vanilla key bind, so it is listed under Options > Controls and stored in options.txt.</p>
 */
public final class FreeLook
{
    private static final Logger LOGGER = LogManager.getLogger();

    /** Package-private so the command's javadoc can inline it with {@code @value}. */
    static final String FILE_NAME = "freelook.cfg";

    /** How the bind turns free look on. */
    public enum Mode
    {
        HOLD,
        TOGGLE
    }

    /** Largest free-look pitch offset, in degrees. The camera can end up well past vertical. */
    private static final float MAX_PITCH = 90.0F;

    /** Time constant for easing the camera back to the body direction, in seconds. */
    private static final double RETURN_SECONDS = 0.09D;

    /** Below this the offsets snap to zero so they cannot drift forever. */
    private static final float EPSILON = 0.01F;

    private static Mode mode = Mode.HOLD;

    /** Master switch. Free look does nothing while this is false, whatever the bind says. */
    private static boolean enabled = true;

    /** Camera yaw offset from the body, in degrees. */
    private static float yaw;

    /** Camera pitch offset from the body, in degrees. */
    private static float pitch;

    /** True while the camera is held off the body. */
    private static boolean active;

    /** Toggle mode's latched state. */
    private static boolean latched;

    /** Previous key-down state, so toggle mode can spot the press edge. */
    private static boolean keyWasDown;

    /** Wall clock of the previous mouse-look update, so easing is frame-rate independent. */
    private static long lastMs;

