package net.minecraft.client.commands;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import net.minecraft.client.Minecraft;
import net.minecraft.client.settings.GameSettings;
import net.minecraft.client.settings.KeyBinding;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

/**
 * Free look: the camera swings off the player's body rotation while the bind is held, or
 * while a toggle is on, so you can aim sideways without turning your character.
 *
 * <p>Vanilla funnels every mouse-look update through {@code EntityPlayerSP.setAngles}, which
 * adds to the body rotation. That single call is where this class takes over: while free look
 * is active the deltas accumulate into private yaw/pitch offsets instead, and the body never
 * turns. {@code EntityRenderer.orientCamera} adds the offsets back onto the view, and
 * {@code EntityPlayerSP.getLook} adds them too so the crosshair, the block outline and block
 * breaking follow the camera rather than the body.</p>
 *
 * <p>The body rotation is deliberately never modified. That keeps walking direction, the
 * rendered player model, and the packets sent to the server all matching each other, which is
 * what makes this behave instead of just look different.</p>
 *
 * <p>Settings are persisted to {@value #FILE_NAME} in the game directory. The key itself is a
 * plain vanilla key bind, so it appears under Options &gt; Controls and is stored in
 * options.txt.</p>
 */
public final class FreeLook
{
    private static final Logger LOGGER = LogManager.getLogger();

    /** Package-private so the command's javadoc can inline it with {@code @value}. */
    static final String FILE_NAME = "freelook.cfg";

    /** How the bind turns free look on. */
    public enum Mode
    {
        /** Free look is on exactly while the key is down. */
        HOLD,
        /** Pressing the key flips free look until pressed again. */
        TOGGLE
    }

    /** Largest free-look pitch offset, in degrees. Past this the world would start to invert. */
    private static final float MAX_PITCH = 90.0F;

    /** Time constant for easing the camera back onto the body, in seconds. */
    private static final double RETURN_SECONDS = 0.09D;

    /** Below this an offset snaps to zero, so easing cannot leave a permanent sliver behind. */
    private static final float EPSILON = 0.01F;

    /** Multiplier vanilla's {@code Entity.setAngles} applies to raw mouse deltas. */
    private static final float VANILLA_GAIN = 0.15F;

    private static Mode mode = Mode.HOLD;

    /** Master switch. Nothing happens while this is false, whatever the bind says. */
    private static boolean enabled = true;

    /** Camera yaw offset from the body, in degrees. */
    private static float yaw;

    /** Camera pitch offset from the body, in degrees. */
    private static float pitch;

    /** True while the camera is being held off the body. */
    private static boolean active;

    /** Toggle mode's latched state. */
    private static boolean latched;

    /** Key state last frame, so toggle mode can spot the press edge. */
    private static boolean keyWasDown;

    /** Wall clock of the last mouse-look update, so easing is frame-rate independent. */
    private static long lastMs;

    private FreeLook() {}

    // --- accessors ---------------------------------------------------------------

    public static Mode getMode()
    {
        return mode;
    }

    public static void setMode(Mode value)
    {
        mode = value == null ? Mode.HOLD : value;
        latched = false;
        save();
    }

    public static boolean isEnabled()
    {
        return enabled;
    }

    public static void setEnabled(boolean value)
    {
        enabled = value;
        latched = false;
        clearOffsets();
        save();
    }

    /** True while the camera is currently off the body. */
    public static boolean isActive()
    {
        return active;
    }

    /**
     * Camera yaw offset in degrees. Zero unless free look is in use, so the camera hooks can
     * add it blindly. It stays non-zero for a moment after the bind is released while the
     * view eases back onto the body.
     */
    public static float getYaw()
    {
        return yaw;
    }

    /** Camera pitch offset in degrees. See {@link #getYaw()}. */
    public static float getPitch()
    {
        return pitch;
    }

    // --- mouse handling ----------------------------------------------------------

    /**
     * Called from {@code EntityPlayerSP.setAngles} with the raw per-frame mouse deltas.
     *
     * @return true if the deltas were consumed and the body must not be turned
     */
    public static boolean onMouseLook(float yawDelta, float pitchDelta)
    {
        long now = System.currentTimeMillis();
        float elapsed = lastMs == 0L ? 0.0F : (now - lastMs) / 1000.0F;
        lastMs = now;

        KeyBinding bind = bind();
        int keyCode = bind == null ? 0 : bind.getKeyCode();
        boolean down = keyCode != 0 && GameSettings.isKeyDown(bind);

        if (!enabled || keyCode == 0)
        {
            // An unbound or switched-off free look must not leave a stale toggle latched.
            latched = false;
            active = false;
        }
        else
        {
            if (mode == Mode.TOGGLE && down && !keyWasDown)
            {
                latched = !latched;
            }

            active = mode == Mode.HOLD ? down : latched;
        }

        keyWasDown = down;

        if (active)
        {
            // Same gain and pitch sign as Entity.setAngles, so releasing the bind hands the
            // mouse straight back to the body with no jump.
            yaw = wrapDegrees(yaw + yawDelta * VANILLA_GAIN);
            pitch = clampPitch(pitch - pitchDelta * VANILLA_GAIN);
            return true;
        }

        if (yaw != 0.0F || pitch != 0.0F)
        {
            easeBack(elapsed);
            return true;
        }

        return false;
    }

    /**
     * Exponential approach to zero. Both the offsets and the elapsed time are real, so this
     * looks the same at 30 fps and at 240 fps.
     */
    private static void easeBack(float elapsed)
    {
        if (elapsed <= 0.0F)
        {
            return;
        }

        float factor = (float)Math.exp(-elapsed / RETURN_SECONDS);
        yaw *= factor;
        pitch *= factor;

        if (Math.abs(yaw) < EPSILON)
        {
            yaw = 0.0F;
        }

        if (Math.abs(pitch) < EPSILON)
        {
            pitch = 0.0F;
        }
    }

    private static void clearOffsets()
    {
        yaw = 0.0F;
        pitch = 0.0F;
        active = false;
    }

    private static KeyBinding bind()
    {
        Minecraft mc = Minecraft.getMinecraft();
        return mc == null || mc.gameSettings == null ? null : mc.gameSettings.keyBindFreeLook;
    }

    /** Keeps the offset inside a single turn, so the trig in the camera stays well conditioned. */
    private static float wrapDegrees(float value)
    {
        value %= 360.0F;

        if (value >= 180.0F)
        {
            value -= 360.0F;
        }
        else if (value < -180.0F)
        {
            value += 360.0F;
        }

        return value;
    }

    private static float clampPitch(float value)
    {
        return Math.max(-MAX_PITCH, Math.min(MAX_PITCH, value));
    }

    // --- persistence -------------------------------------------------------------

    public static File getConfigFile()
    {
        Minecraft mc = Minecraft.getMinecraft();
        File dir = mc == null ? new File(".") : mc.mcDataDir;
        return new File(dir, FILE_NAME);
    }

    private static void resetToDefaults()
    {
        mode = Mode.HOLD;
        enabled = true;
        clearOffsets();
        latched = false;
        keyWasDown = false;
        lastMs = 0L;
    }

    /** Restores every default and rewrites the config file. */
    public static void reset()
    {
        resetToDefaults();
        save();
    }

    /** Reads the config file if present. Never throws. */
    public static void load()
    {
        clearOffsets();
        latched = false;
        keyWasDown = false;
        lastMs = 0L;

        File file = getConfigFile();

        if (!file.exists())
        {
            LOGGER.info("No {} found, using free look defaults.", FILE_NAME);
            return;
        }

        FileInputStream stream = null;

        try
        {
            BufferedReader reader = new BufferedReader(new InputStreamReader(stream = new FileInputStream(file), "UTF-8"));
            String line;

            while ((line = reader.readLine()) != null)
            {
                line = line.trim();

                if (line.isEmpty() || line.charAt(0) == '#')
                {
                    continue;
                }

                int split = line.indexOf('=');

                if (split < 1)
                {
                    continue;
                }

                applySetting(line.substring(0, split).trim(), line.substring(split + 1).trim());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error("Failed to read " + file.getAbsolutePath() + ", using free look defaults.", exception);
            resetToDefaults();
        }
        finally
        {
            closeQuietly(stream);
        }

        LOGGER.info("Loaded free look config from {}", file.getAbsolutePath());
    }

    private static void applySetting(String key, String value)
    {
        if (key.equals("mode"))
        {
            // Unknown modes keep the current one rather than silently falling back.
            if (value.equalsIgnoreCase("hold"))
            {
                mode = Mode.HOLD;
            }
            else if (value.equalsIgnoreCase("toggle"))
            {
                mode = Mode.TOGGLE;
            }
            else
            {
                LOGGER.warn("Unknown free look mode \"{}\" in {}, keeping {}", value, FILE_NAME, mode);
            }

            return;
        }

        if (key.equals("enabled"))
        {
            enabled = parseBooleanOr(value, enabled);
            return;
        }

        LOGGER.debug("Ignoring unknown {} key {}", FILE_NAME, key);
    }

    /**
     * Strict boolean parse. Anything other than true/false keeps the current value so a typo
     * cannot silently flip the setting.
     */
    private static boolean parseBooleanOr(String value, boolean fallback)
    {
        if (value.equalsIgnoreCase("true"))
        {
            return true;
        }

        if (value.equalsIgnoreCase("false"))
        {
            return false;
        }

        LOGGER.warn("Expected true or false but got \"{}\" in {}, keeping {}", value, FILE_NAME, fallback);
        return fallback;
    }

    /** Writes the config file. Never throws. */
    public static void save()
    {
        File file = getConfigFile();
        File parent = file.getParentFile();

        if (parent != null && !parent.exists() && !parent.mkdirs())
        {
            LOGGER.warn("Could not create {} to save free look config", parent.getAbsolutePath());
            return;
        }

        PrintWriter writer = null;

        try
        {
            writer = new PrintWriter(new OutputStreamWriter(new FileOutputStream(file), "UTF-8"));
            writer.println("# Free look - written by /freelook");
            writer.println("enabled=" + enabled);
            writer.println("mode=" + mode.name().toLowerCase());
        }
        catch (Exception exception)
        {
            LOGGER.error("Failed to write " + file.getAbsolutePath(), exception);
        }
        finally
        {
            if (writer != null)
            {
                writer.close();
            }
        }
    }

    private static void closeQuietly(FileInputStream stream)
    {
        if (stream != null)
        {
            try
            {
                stream.close();
            }
            catch (IOException ignored) {}
        }
    }
}

package net.minecraft.client.commands;

import net.minecraft.client.Minecraft;
import net.minecraft.client.settings.GameSettings;
import net.minecraft.util.ChatComponentText;
import net.minecraft.util.EnumChatFormatting;

/**
 * /freelook [on|off] [mode &lt;hold|toggle&gt;] [reset]
 *
 * <p>Free look, driven from chat. Unlike the animation settings there is no separate
 * behaviour to opt into, so it starts enabled: bind the key under Options &gt; Controls and
 * it works. The mode decides whether the bind has to be held or toggles free look instead.</p>
 *
 * <p>Settings are stored in {@value FreeLook#FILE_NAME} in the game directory and rewritten
 * on every change.</p>
 */
public class FreeLookCommand implements ClientCommand
{
    public String getName()
    {
        return "freelook";
    }

    public String getUsage()
    {
        return "/freelook | /freelook on|off | /freelook mode <hold|toggle> | /freelook reset";
    }

    public boolean execute(Minecraft mc, String[] args)
    {
        if (args.length == 0)
        {
            status(mc);
            return true;
        }

        String sub = args[0].toLowerCase();

        if (sub.equals("help"))
        {
            reply(mc, getUsage(), EnumChatFormatting.AQUA);
            return true;
        }

        if (sub.equals("reset"))
        {
            if (args.length > 1)
            {
                reply(mc, "Usage: /freelook reset", EnumChatFormatting.RED);
                return true;
            }

            FreeLook.reset();
            reply(mc, "Free look reset to defaults. " + FreeLook.getConfigFile().getName() + " rewritten.",
                EnumChatFormatting.GREEN);
            return true;
        }

        if (sub.equals("on") || sub.equals("off"))
        {
            if (args.length > 1)
            {
                reply(mc, "Usage: /freelook on|off", EnumChatFormatting.RED);
                return true;
            }

            FreeLook.setEnabled(sub.equals("on"));
            reply(mc, "Free look " + (FreeLook.isEnabled() ? "enabled" : "disabled") + ".",
                FreeLook.isEnabled() ? EnumChatFormatting.GREEN : EnumChatFormatting.YELLOW);
            replyBind(mc);
            return true;
        }

        if (sub.equals("mode"))
        {
            return mode(mc, args);
        }

        reply(mc, "Unknown option \"" + args[0] + "\". Usage: " + getUsage(), EnumChatFormatting.RED);
        return true;
    }

    private boolean mode(Minecraft mc, String[] args)
    {
        if (args.length == 1)
        {
            reply(mc, "Usage: /freelook mode <hold|toggle>", EnumChatFormatting.RED);
            reply(mc, "Current: " + FreeLook.getMode().name().toLowerCase(), EnumChatFormatting.AQUA);
            return true;
        }

        if (args.length > 2)
        {
            reply(mc, "Usage: /freelook mode <hold|toggle>", EnumChatFormatting.RED);
            return true;
        }

        FreeLook.Mode parsed;

        if (args[1].equalsIgnoreCase("hold"))
        {
            parsed = FreeLook.Mode.HOLD;
        }
        else if (args[1].equalsIgnoreCase("toggle"))
        {
            parsed = FreeLook.Mode.TOGGLE;
        }
        else
        {
            reply(mc, "\"" + args[1] + "\" is not a mode. Use hold or toggle.", EnumChatFormatting.RED);
            return true;
        }

        FreeLook.setMode(parsed);
        reply(mc, "Free look mode set to " + parsed.name().toLowerCase()
            + (parsed == FreeLook.Mode.HOLD ? " (on while the key is down)." : " (press the key to toggle)."),
            EnumChatFormatting.GREEN);
        replyBind(mc);
        return true;
    }

    private void status(Minecraft mc)
    {
        boolean on = FreeLook.isEnabled();
        reply(mc, "Free look " + (on ? "enabled" : "disabled")
            + "  mode: " + FreeLook.getMode().name().toLowerCase()
            + (on && FreeLook.isActive() ? "  active" : "")
            + "  (" + FreeLook.getConfigFile().getName() + ")",
            on ? EnumChatFormatting.GREEN : EnumChatFormatting.YELLOW);

        replyBind(mc);

        if (on)
        {
            reply(mc, "  hold while aiming; the camera eases back on release.",
                EnumChatFormatting.GRAY);
        }
    }

    /** Reports the bind, and nags when there is none, since that is the one way to get nothing. */
    private void replyBind(Minecraft mc)
    {
        GameSettings settings = mc.gameSettings;
        int code = settings == null ? 0 : settings.keyBindFreeLook.getKeyCode();

        if (code == 0)
        {
            reply(mc, "  No key bound. Pick one in Options > Controls > Miscellaneous.", EnumChatFormatting.RED);
        }
        else
        {
            reply(mc, "  Key: " + GameSettings.getKeyDisplayString(code), EnumChatFormatting.GRAY);
        }
    }

    private void reply(Minecraft mc, String text, EnumChatFormatting colour)
    {
        mc.ingameGUI.getChatGUI().printChatMessage(new ChatComponentText(colour + text));
    }
}

