package net.minecraft.client.settings;

import java.lang.reflect.Field;
import java.util.Arrays;

/**
 * Confirms the free look bind actually lands in the vanilla keyBindings array, which is what
 * makes it show up as a row in Options > Controls. GuiKeyBindingList just iterates that array,
 * so membership is the whole requirement.
 */
public final class KeyBindTest
{
    private static int checks;
    private static int failures;

    public static void main(String[] args) throws Exception
    {
        GameSettings settings = new GameSettings();
        Field f = GameSettings.class.getDeclaredField("keyBindings");
        f.setAccessible(true);
        KeyBinding[] binds = (KeyBinding[])f.get(settings);

        System.out.println("keyBindings length: " + binds.length);

        boolean found = false;

        for (KeyBinding bind : binds)
        {
            if (bind == settings.keyBindFreeLook)
            {
                found = true;
                break;
            }
        }

        check("free look is in the keyBindings array", found);
        check("no null entries", !Arrays.asList(binds).contains(null));
        check("category is the misc list",
            "key.categories.misc".equals(settings.keyBindFreeLook.getKeyCategory()));
        check("lang key is key.freeLook", "key.freeLook".equals(settings.keyBindFreeLook.getKeyDescription()));
        check("default is V (47)", settings.keyBindFreeLook.getKeyCodeDefault() == 47);
        check("bound to the default for now", settings.keyBindFreeLook.getKeyCode() == 47);

        // Duplicates would make the Controls list show the same key twice.
        int matches = 0;

        for (KeyBinding bind : binds)
        {
            if (bind.getKeyDescription().equals("key.freeLook"))
            {
                ++matches;
            }
        }

        check("appears exactly once (got " + matches + ")", matches == 1);

        // And it must not collide with a vanilla default.
        check("no duplicate key code among defaults", noDefaultCollision(settings, binds));

        System.out.println(failures == 0
            ? "PASS  " + checks + " checks"
            : "FAIL  " + failures + " of " + checks + " checks");

        if (failures != 0)
        {
            System.exit(1);
        }
    }

    private static boolean noDefaultCollision(GameSettings settings, KeyBinding[] binds)
    {
        int mine = settings.keyBindFreeLook.getKeyCodeDefault();

        if (mine == 0)
        {
            return true;
        }

        for (KeyBinding bind : binds)
        {
            if (bind != settings.keyBindFreeLook && bind.getKeyCodeDefault() == mine)
            {
                System.out.println("  collides with " + bind.getKeyDescription());
                return false;
            }
        }

        return true;
    }

    private static void check(String what, boolean ok)
    {
        ++checks;

        if (!ok)
        {
            ++failures;
            System.out.println("  FAIL  " + what);
        }
    }

    private KeyBindTest() {}
}

