package net.minecraft.client.commands;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.lang.reflect.Field;

/**
 * Headless checks for {@link FreeLook}. Lives in the same package so it can reach the
 * package-private {@code step} and drive the state machine without a running game.
 *
 * <p>Statics are snapshotted and restored around every scenario: zeroing them would destroy
 * the initialisers under test, which is exactly the bug this harness exists to catch.</p>
 */
public final class FreeLookTest
{
    private static int checks;
    private static int failures;

    public static void main(String[] args) throws Exception
    {
        File file = FreeLook.getConfigFile();
        boolean hadFile = file.exists();
        String before = hadFile ? read(file) : null;

        try
        {
            holdMode();
            toggleMode();
            disabledGate();
            pitchClamp();
            yawWrap();
            easeBackToZero();
            unknownModeKeepsCurrent();
            badBooleanKeepsCurrent();
            persistenceRoundTrip();
        }
        finally
        {
            restore(file, hadFile, before);
        }

        System.out.println(failures == 0
            ? "PASS  " + checks + " checks"
            : "FAIL  " + failures + " of " + checks + " checks");

        if (failures != 0)
        {
            System.exit(1);
        }
    }

    // --- scenarios ---------------------------------------------------------------

    /** In HOLD mode the camera only follows the mouse while the key is down. */
    private static void holdMode() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.setMode(FreeLook.Mode.HOLD);

            check("hold: key up lets the body turn", !FreeLook.step(10.0F, 0.0F, false));
            check("hold: idle consumed nothing", FreeLook.getYaw() == 0.0F);

            check("hold: key down captures the camera", FreeLook.step(10.0F, 0.0F, true));
            near("hold: yaw gain matches Entity.setAngles", FreeLook.getYaw(), 10.0F * 0.15F, 1.0E-5F);
            check("hold: offset recorded", FreeLook.getYaw() != 0.0F);

            // Holding the key across many frames must keep accumulating.
            for (int i = 0; i < 20; ++i)
            {
                FreeLook.step(10.0F, 0.0F, true);
            }

            // 21 frames of a 10 delta at vanilla's 0.15 gain.
            near("hold: accumulates over frames", FreeLook.getYaw(), 21.0F * 0.15F * 10.0F, 1.0E-4F);

            // Releasing must hand the body back, but not before the view has eased home.
            check("hold: release still consumes while easing", FreeLook.step(10.0F, 0.0F, false));
            check("hold: offsets shrinking on release", Math.abs(FreeLook.getYaw()) > 0.0F);
        }
        finally
        {
            saved.restore();
        }
    }

    /** In TOGGLE mode the key flips free look and it stays on after release. */
    private static void toggleMode() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.setMode(FreeLook.Mode.TOGGLE);

            check("toggle: idle hands over to the body", !FreeLook.step(10.0F, 0.0F, false));

            FreeLook.step(10.0F, 0.0F, true);
            check("toggle: press engaged free look", FreeLook.isActive());

            // Key stays down: must not re-trigger on every frame.
            FreeLook.step(10.0F, 0.0F, true);
            check("toggle: holding does not re-toggle", FreeLook.isActive());

            FreeLook.step(0.0F, 0.0F, false);
            check("toggle: survives release", FreeLook.isActive());
            check("toggle: still consumes while latched", FreeLook.step(10.0F, 0.0F, false));

            FreeLook.step(0.0F, 0.0F, true);
            check("toggle: second press turns it off", !FreeLook.isActive());
        }
        finally
        {
            saved.restore();
        }
    }

    /** The master switch must beat the bind in both modes. */
    private static void disabledGate() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.setMode(FreeLook.Mode.HOLD);
            FreeLook.setEnabled(false);

            check("off: key down cannot force it on", !FreeLook.step(10.0F, 0.0F, true));
            check("off: no offset recorded", FreeLook.getYaw() == 0.0F);
            check("off: not active", !FreeLook.isActive());

            // Switching the feature off has to drop any offset already banked.
            FreeLook.setEnabled(true);
            FreeLook.step(10.0F, 0.0F, true);
            check("on: banked an offset", FreeLook.getYaw() != 0.0F);
            FreeLook.setEnabled(false);
            check("off: switching off clears the offset", FreeLook.getYaw() == 0.0F && FreeLook.getPitch() == 0.0F);

            // And a toggle latched before the switch must not resurrect. The key has to
            // be released first, exactly as it would be in game before the next press.
            FreeLook.setEnabled(true);
            FreeLook.setMode(FreeLook.Mode.TOGGLE);
            FreeLook.step(0.0F, 0.0F, false);
            FreeLook.step(0.0F, 0.0F, true);
            check("toggle: latched on", FreeLook.isActive());
            FreeLook.setEnabled(false);
            check("off: latched toggle dropped", !FreeLook.isActive());
        }
        finally
        {
            saved.restore();
        }
    }

    /** Pitch cannot run away past vertical, however long the mouse is held. */
    private static void pitchClamp() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.setMode(FreeLook.Mode.HOLD);
            FreeLook.setEnabled(true);

            // Vanilla moves pitch the opposite way to yaw: look up on negative delta.
            for (int i = 0; i < 5000; ++i)
            {
                FreeLook.step(0.0F, 10.0F, true);
            }

            near("pitch: clamped looking down", FreeLook.getPitch(), -90.0F, 1.0E-4F);

            begin();
            FreeLook.setMode(FreeLook.Mode.HOLD);
            FreeLook.setEnabled(true);

            for (int i = 0; i < 5000; ++i)
            {
                FreeLook.step(0.0F, -10.0F, true);
            }

            near("pitch: clamped looking up", FreeLook.getPitch(), 90.0F, 1.0E-4F);
        }
        finally
        {
            saved.restore();
        }
    }

    /** Yaw stays inside one turn so the camera trig stays well conditioned. */
    private static void yawWrap() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.setMode(FreeLook.Mode.HOLD);
            FreeLook.setEnabled(true);

            for (int i = 0; i < 20000; ++i)
            {
                FreeLook.step(10.0F, 0.0F, true);
            }

            check("yaw: wrapped into one turn", FreeLook.getYaw() >= -180.0F && FreeLook.getYaw() < 180.0F);
            check("yaw: not NaN", !Float.isNaN(FreeLook.getYaw()));
        }
        finally
        {
            saved.restore();
        }
    }

    /** The view has to come all the way home, or free look would eat the mouse forever. */
    private static void easeBackToZero() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.setMode(FreeLook.Mode.HOLD);
            FreeLook.setEnabled(true);

            FreeLook.step(100.0F, 0.0F, true);
            check("ease: banked", Math.abs(FreeLook.getYaw()) > 1.0F);

            // The easing is time based, so the loop has to spend real time in each frame. A
            // tight loop would measure a zero delta and never decay at all.
            int frames = 0;

            for (; frames < 120 && FreeLook.step(1.0F, 0.0F, false); ++frames)
            {
                Thread.sleep(16L);
            }

            check("ease: reached exactly zero", FreeLook.getYaw() == 0.0F);
            check("ease: converged inside a second (" + frames + " frames)", frames < 75);
            check("ease: body gets the mouse back", !FreeLook.step(10.0F, 0.0F, false));
            check("ease: body delta was not applied to the camera", FreeLook.getYaw() == 0.0F);

            // And the decay must depend on elapsed time, not on the number of frames.
            // One 60 ms step: exp(-0.06 / 0.09) is about 0.51, so it should roughly halve.
            begin();
            FreeLook.step(100.0F, 0.0F, true);
            float banked = Math.abs(FreeLook.getYaw());
            Thread.sleep(60L);
            FreeLook.step(1.0F, 0.0F, false);
            near("ease: one 60 ms step halves the offset", FreeLook.getYaw(), banked * 0.513F, banked * 0.05F);

            // A burst of short frames spanning the same time must land in the same place.
            begin();
            FreeLook.step(100.0F, 0.0F, true);
            banked = Math.abs(FreeLook.getYaw());

            for (int i = 0; i < 4; ++i)
            {
                Thread.sleep(15L);
                FreeLook.step(1.0F, 0.0F, false);
            }

            near("ease: framerate independent", FreeLook.getYaw(), banked * 0.513F, banked * 0.06F);
        }
        finally
        {
            saved.restore();
        }
    }

    /** A mode written by a newer build must not silently flip the behaviour. */
    private static void unknownModeKeepsCurrent() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            write("mode=TOGGLE\nenabled=true\n");
            FreeLook.load();
            check("config: reads mode", FreeLook.getMode() == FreeLook.Mode.TOGGLE);

            write("mode=wobble\nenabled=true\n");
            FreeLook.load();
            check("config: keeps known mode on unknown value", FreeLook.getMode() == FreeLook.Mode.TOGGLE);
        }
        finally
        {
            saved.restore();
        }
    }

    /** Same for a malformed boolean. */
    private static void badBooleanKeepsCurrent() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            write("mode=hold\nenabled=yes please\n");
            FreeLook.load();
            check("config: keeps enabled=true on garbage", FreeLook.isEnabled());

            write("mode=hold\nenabled=false\n");
            FreeLook.load();
            check("config: reads a valid false", !FreeLook.isEnabled());
        }
        finally
        {
            saved.restore();
        }
    }

    /** A full write/read cycle has to come back identical. */
    private static void persistenceRoundTrip() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.setEnabled(true);
            FreeLook.setMode(FreeLook.Mode.TOGGLE);

            String written = read(FreeLook.getConfigFile());
            check("config: writes enabled", written.contains("enabled=true"));
            check("config: writes mode", written.contains("mode=toggle"));

            // Every setter saves, so going back through one would rewrite the file and prove
            // nothing. Poke the statics directly instead, standing in for a session that never
            // touched them.
            field("enabled").set(null, Boolean.FALSE);
            modeField().set(null, FreeLook.Mode.HOLD);
            check("config: memory moved off the file", !FreeLook.isEnabled() && FreeLook.getMode() == FreeLook.Mode.HOLD);

            FreeLook.load();
            check("config: round trip restored enabled", FreeLook.isEnabled());
            check("config: round trip restored mode", FreeLook.getMode() == FreeLook.Mode.TOGGLE);

            // A missing file must leave the current state alone rather than throw.
            File file = FreeLook.getConfigFile();
            check("config: file exists for the delete test", file.exists() && file.delete());
            FreeLook.load();
            check("config: missing file keeps enabled", FreeLook.isEnabled());
            check("config: missing file keeps mode", FreeLook.getMode() == FreeLook.Mode.TOGGLE);

            // reset() has to put both back to the defaults and rewrite the file.
            FreeLook.reset();
            check("config: reset restores the default mode", FreeLook.getMode() == FreeLook.Mode.HOLD);
            check("config: reset restores the default switch", FreeLook.isEnabled());
            check("config: reset rewrites the file", read(file).contains("mode=hold"));
        }
        finally
        {
            saved.restore();
        }
    }

    // --- statics -----------------------------------------------------------------

    private static final String[] FIELDS = {"enabled", "yaw", "pitch", "active", "latched", "keyWasDown", "lastMs"};

    /** Restores the private statics so scenarios cannot leak into each other. */
    private static final class State
    {
        private final Object[] values = new Object[FIELDS.length + 1];
        private final Field mode;

        private State() throws Exception
        {
            this.mode = modeField();
        }

        static State capture() throws Exception
        {
            State state = new State();

            for (int i = 0; i < FIELDS.length; ++i)
            {
                state.values[i] = field(FIELDS[i]).get(null);
            }

            state.values[FIELDS.length] = state.mode.get(null);
            return state;
        }

        void restore() throws Exception
        {
            for (int i = 0; i < FIELDS.length; ++i)
            {
                field(FIELDS[i]).set(null, this.values[i]);
            }

            this.mode.set(null, this.values[FIELDS.length]);
        }
    }

    /**
     * Puts the feature in a known idle state. Deliberately goes through reflection rather than
     * setEnabled/setMode, which would rewrite the config file on every scenario.
     */
    private static void begin() throws Exception
    {
        modeField().set(null, FreeLook.Mode.HOLD);
        field("enabled").set(null, Boolean.TRUE);
        field("yaw").set(null, 0.0F);
        field("pitch").set(null, 0.0F);
        field("active").set(null, Boolean.FALSE);
        field("latched").set(null, Boolean.FALSE);
        field("keyWasDown").set(null, Boolean.FALSE);
        field("lastMs").set(null, 0L);
    }

    private static Field modeField() throws Exception
    {
        return field("mode");
    }

    private static Field field(String name) throws Exception
    {
        Field f = FreeLook.class.getDeclaredField(name);
        f.setAccessible(true);
        return f;
    }

    // --- helpers -----------------------------------------------------------------

    private static void write(String contents) throws Exception
    {
        PrintWriter writer = new PrintWriter(FreeLook.getConfigFile(), "UTF-8");
        writer.print(contents);
        writer.close();
    }

    private static String read(File file) throws Exception
    {
        if (!file.exists())
        {
            return "";
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), "UTF-8"));
        StringBuilder builder = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null)
        {
            builder.append(line).append('\n');
        }

        reader.close();
        return builder.toString();
    }

    private static void restore(File file, boolean hadFile, String contents)
    {
        if (hadFile)
        {
            try
            {
                write(contents);
                return;
            }
            catch (Exception ignored)
            {
                // fall through
            }
        }

        file.delete();
    }

    private static void check(String what, boolean ok)
    {
        ++checks;

        if (!ok)
        {
            ++failures;
            System.out.println("  FAIL  " + what);
        }
    }

    private static void near(String what, float actual, float expected, float tolerance)
    {
        ++checks;

        if (Float.isNaN(actual) || Math.abs(actual - expected) > tolerance)
        {
            ++failures;
            System.out.println("  FAIL  " + what + " (expected " + expected + ", got " + actual + ")");
        }
    }

    private FreeLookTest() {}
}

