package net.minecraft.client.settings;

import java.lang.reflect.Field;

/**
 * Headless checks that the free look bind is actually wired into vanilla's key bind handling.
 *
 * <p>{@code GuiKeyBindingList} groups binds by {@code KeyBinding.getKeybinds()} category and
 * iterates {@code gameSettings.keyBindings}, so being in that array is all it takes for the bind
 * to show up under Options &gt; Controls. This asserts that, plus that the default does not
 * collide with anything vanilla already uses.</p>
 */
public final class KeyBindTest
{
    /** LWJGL key code for V, the default free look bind. */
    private static final int KEY_V = 47;

    private static int checks;
    private static int failures;

    public static void main(String[] args) throws Exception
    {
        GameSettings settings = new GameSettings(new net.minecraft.client.Minecraft());

        KeyBinding freeLook = settings.keyBindFreeLook;

        check("field is initialised", freeLook != null);

        if (freeLook == null)
        {
            report();
            return;
        }

        check("named for the user", "Free Look".equals(freeLook.getKeyDescription()));

        int index = indexOf(settings, freeLook);

        check("present in keyBindings (index " + index + ")", index >= 0);
        check("array holds " + settings.keyBindings.length + " binds", settings.keyBindings.length == 34);
        check("default bind is V", freeLook.getKeyCode() == KEY_V);
        check("in the Misc category", "key.categories.misc".equals(freeLook.getKeyCategory()));
        check("not already bound elsewhere", collisions(settings, freeLook) == 0);

        report();
    }

    // --- helpers -----------------------------------------------------------------

    private static int indexOf(GameSettings settings, KeyBinding bind)
    {
        KeyBinding[] binds = settings.keyBindings;

        for (int i = 0; i < binds.length; ++i)
        {
            if (binds[i] == bind)
            {
                return i;
            }
        }

        return -1;
    }

    /** How many other binds share this key code. Vanilla leaves most of them at 0, so only real clashes count. */
    private static int collisions(GameSettings settings, KeyBinding bind)
    {
        int code = bind.getKeyCode();
        int count = 0;
        KeyBinding[] binds = settings.keyBindings;

        for (int i = 0; i < binds.length; ++i)
        {
            if (binds[i] != null && binds[i] != bind && binds[i].getKeyCode() == code && code != 0)
            {
                ++count;
            }
        }

        return count;
    }

    private static void check(String what, boolean ok)
    {
        ++checks;

        if (!ok)
        {
            ++failures;
            System.out.println("  FAIL  " + what);
        }
        else
        {
            System.out.println("  ok    " + what);
        }
    }

    private static void report()
    {
        System.out.println(failures == 0
            ? "PASS  " + checks + " checks"
            : "FAIL  " + failures + " of " + checks + " checks");

        if (failures != 0)
        {
            System.exit(1);
        }
    }

    private KeyBindTest() {}
}

