/** Reads the shipped lang file straight off disk, the same one the game loads. */
private static String langValue(String key) throws Exception
{
    File lang = new File("C:/Users/dinhv/IdeaProjects/GradleMCPBase/build/resources/main/assets/minecraft/lang/en_US.lang");

    if (!lang.exists())
    {
        return null;
    }

    BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(lang), "UTF-8"));
    String line;

    try
    {
        while ((line = reader.readLine()) != null)
        {
            if (line.startsWith(key + "="))
            {
                return line.substring(key.length() + 1);
            }
        }
    }
    finally
    {
        reader.close();
    }

    return null;
}

