    // --- persistence ------------------------------------------------------------

    public static File getConfigFile()
    {
        Minecraft mc = Minecraft.getMinecraft();
        File dir = mc == null ? new File(".") : mc.mcDataDir;
        return new File(dir, FILE_NAME);
    }

    private static void resetToDefaults()
    {
        enabled = false;
        blockHit = true;
        pushing = true;
        pushingParticle = true;
        sneak = true;
        smoothSneak = false;
        smoothSneakSpeed = 6.0F;
        health = true;
        armorDamage = false;
        itemSwitch = false;
        rod = false;
    }

    /** Restores every default and rewrites the config file. */
    public static void reset()
    {
        resetToDefaults();
        save();
    }

    /** Reads the config file if present. Never throws. */
    public static void load()
    {
        File file = getConfigFile();

        if (!file.exists())
        {
            LOGGER.info("No {} found, using animation defaults.", FILE_NAME);
            return;
        }

        FileInputStream stream = null;

        try
        {
            BufferedReader reader = new BufferedReader(new InputStreamReader(stream = new FileInputStream(file), "UTF-8"));
            String line;

            while ((line = reader.readLine()) != null)
            {
                line = line.trim();

                if (line.isEmpty() || line.charAt(0) == '#')
                {
                    continue;
                }

                int split = line.indexOf('=');

                if (split < 1)
                {
                    continue;
                }

                applySetting(line.substring(0, split).trim(), line.substring(split + 1).trim());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error("Failed to read " + file.getAbsolutePath() + ", using animation defaults.", exception);
            resetToDefaults();
        }
        finally
        {
            closeQuietly(stream);
        }

        LOGGER.info("Loaded animation config from {}", file.getAbsolutePath());
    }

    private static void applySetting(String key, String value)
    {
        if (key.equals("enabled"))
        {
            enabled = parseBooleanOr(value, enabled);
            return;
        }

        if (key.equals("smoothSneakSpeed"))
        {
            try
            {
                smoothSneakSpeed = clampSpeed(Float.parseFloat(value));
            }
            catch (NumberFormatException exception)
            {
                LOGGER.warn("Bad smoothSneakSpeed \"{}\" in {}, keeping {}", value, FILE_NAME, smoothSneakSpeed);
            }

            return;
        }

        try
        {
            // Fall back to the value already stored, so an unreadable line cannot flip a
            // setting that defaults to on.
            assign(key, parseBooleanOr(value, rawFlag(key)));
        }
        catch (IllegalArgumentException ignored)
        {
            // Unknown key, most likely written by a newer build. Ignore it.
        }
    }

    private static float clampSpeed(float value)
    {
        if (Float.isNaN(value) || Float.isInfinite(value))
        {
            return 6.0F;
        }

        return Math.max(0.5F, Math.min(20.0F, value));
    }

    /**
     * Strict boolean parse. Anything other than true/false keeps the current value so a
     * typo cannot silently flip a setting.
     */
    private static boolean parseBooleanOr(String value, boolean fallback)
    {
        if (value.equalsIgnoreCase("true"))
        {
            return true;
        }

        if (value.equalsIgnoreCase("false"))
        {
            return false;
        }

        LOGGER.warn("Expected true or false but got \"{}\" in {}, keeping {}", value, FILE_NAME, fallback);
        return fallback;
    }

    /** Writes the config file. Never throws. */
    public static void save()
    {
        File file = getConfigFile();
        File parent = file.getParentFile();

        if (parent != null && !parent.exists() && !parent.mkdirs())
        {
            LOGGER.warn("Could not create {} to save animation config", parent.getAbsolutePath());
            return;
        }

        PrintWriter writer = null;

        try
        {
            writer = new PrintWriter(new OutputStreamWriter(new FileOutputStream(file), "UTF-8"));
            writer.println("# Old animations - written by /anim");
            writer.println("enabled=" + enabled);
            writer.println("blockHit=" + blockHit);
            writer.println("pushing=" + pushing);
            writer.println("pushingParticle=" + pushingParticle);
            writer.println("sneak=" + sneak);
            writer.println("smoothSneak=" + smoothSneak);
            writer.println("smoothSneakSpeed=" + smoothSneakSpeed);
            writer.println("health=" + health);
            writer.println("armorDamage=" + armorDamage);
            writer.println("itemSwitch=" + itemSwitch);
            writer.println("rod=" + rod);
        }
        catch (Exception exception)
        {
            LOGGER.error("Failed to write " + file.getAbsolutePath(), exception);
        }
        finally
        {
            if (writer != null)
            {
                writer.close();
            }
        }
    }

    private static void closeQuietly(FileInputStream stream)
    {
        if (stream != null)
        {
            try
            {
                stream.close();
            }
            catch (IOException ignored) {}
        }
    }
}

