package net.minecraft.client.commands;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiClientSettings;

/**
 * /config - opens the screen that holds every mod setting.
 *
 * <p>Also reachable as {@code /settings}. The same screen opens from the pause menu and from
 * the key bind under Options &gt; Controls, so nobody has to remember the command.</p>
 *
 * <p>{@code /config reset} puts every setting back to its default, and {@code /config file}
 * names the single file they all live in, for when someone wants to edit it by hand.</p>
 */
public class ConfigCommand implements ClientCommand
{
    public String getName()
    {
        return "config";
    }

    public String getUsage()
    {
        return "/config | /config reset | /config file";
    }

    public boolean execute(Minecraft mc, String[] args)
    {
        if (args.length == 0)
        {
            mc.displayGuiScreen(new GuiClientSettings(mc));
            return true;
        }

        if (args.length > 1)
        {
            reply(mc, "Usage: " + getUsage(), net.minecraft.util.EnumChatFormatting.RED);
            return true;
        }

        if (args[0].equalsIgnoreCase("reset"))
        {
            ClientConfig.resetAll();
            reply(mc, "Every setting reset to its default. " + ClientConfig.getConfigFile().getName()
                + " rewritten.", net.minecraft.util.EnumChatFormatting.GREEN);
            return true;
        }

        if (args[0].equalsIgnoreCase("file"))
        {
            reply(mc, "Settings live in " + ClientConfig.getConfigFile().getAbsolutePath()
                + ". Delete it to start over next launch.", net.minecraft.util.EnumChatFormatting.AQUA);
            return true;
        }

        reply(mc, "Usage: " + getUsage(), net.minecraft.util.EnumChatFormatting.RED);
        return true;
    }

    private static void reply(Minecraft mc, String message, net.minecraft.util.EnumChatFormatting colour)
    {
        mc.thePlayer.addChatMessage(new net.minecraft.util.ChatComponentText(colour + message));
    }
}

