package net.minecraft.client.commands;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.minecraft.client.Minecraft;
import net.minecraft.client.commands.ClientConfig.Setting;
import net.minecraft.client.settings.GameSettings;

/**
 * Headless checks for the single config file.
 *
 * <p>Runs with a blank Minecraft installed through Unsafe, a real GameSettings and an mcDataDir
 * pointed at a scratch folder, so the file handling is exercised for real rather than mocked.</p>
 *
 * <p>Covered: the settings table is well formed; a write before the first load is suppressed so
 * the legacy import cannot be pre-empted; load writes a complete file; every value survives a
 * save/load round trip; unusable text falls back to defaults; the three old per-mod files are
 * imported once and left on disk; the FPS colour pair reconciles both ways; a held drag costs
 * one write; and reset puts everything back.</p>
 */
public final class ConfigTest
{
    private static int checks;
    private static int failures;

    /** Expected shape of the table. Guards against a setting being added in one place only. */
    private static final int EXPECTED_SETTINGS = 27;

    private static final String[] EXPECTED_SECTIONS =
        {"fov", "bob", "nhk", "sprint", "animations", "fps", "freelook"};

    private static File dir;
    private static Minecraft mc;

    public static void main(String[] args) throws Exception
    {
        dir = scratch();
        mc = install(dir);

        tableIsWellFormed();
        saveIsIgnoredBeforeLoad();
        loadWritesEverySetting();
        valuesSurviveARoundTrip();
        unusableTextKeepsDefaults();
        legacyFilesAreImportedOnce();
        fpsColourPairReconciles();
        heldDragCostsOneWrite();
        resetPutsEverythingBack();
        fileNameIsTheOnlyOne();

        System.out.println();
        System.out.println(failures == 0 ? "ALL " + checks + " CHECKS PASSED" : failures + " of " + checks + " FAILED");
        System.exit(failures == 0 ? 0 : 1);
    }

    // --- tests --------------------------------------------------------------------

    /** No duplicate keys, no dangling master switches, sections contiguous, expected size. */
    private static void tableIsWellFormed()
    {
        List<Setting> settings = ClientConfig.settings();

        eq("setting count", EXPECTED_SETTINGS, settings.size());

        Set<String> seen = new HashSet<String>();
        String section = null;
        List<String> ordered = new ArrayList<String>();

        for (int i = 0; i < settings.size(); ++i)
        {
            Setting s = settings.get(i);

            ok("unique key " + s.qualifiedKey(), seen.add(s.qualifiedKey()));
            ok("non-empty label for " + s.qualifiedKey(), s.getLabel().length() > 0);

            if (s.getKind() == Setting.Kind.SLIDER)
            {
                ok("slider range for " + s.qualifiedKey(), s.getMax() > s.getMin());
            }
            else
            {
                ok("choices for " + s.qualifiedKey(), s.getChoices() != null && s.getChoices().length > 0);
            }

            if (!s.getSection().equals(section))
            {
                section = s.getSection();
                ordered.add(section);
            }
        }

        eq("section count", EXPECTED_SECTIONS.length, ordered.size());

        for (int i = 0; i < EXPECTED_SECTIONS.length; ++i)
        {
            eq("section " + i + " is contiguous", EXPECTED_SECTIONS[i], ordered.get(i));
        }

        // Every gate must name a real toggle, or the row would be permanently greyed.
        for (int i = 0; i < settings.size(); ++i)
        {
            Setting gated = settings.get(i);
            Setting master = find(settings, masterName(gated));

            if (master != null)
            {
                eq("master of " + gated.qualifiedKey() + " is a toggle", Setting.Kind.TOGGLE, master.getKind());
            }
        }

        // The rows the GUI greys out must be the ones that genuinely do nothing.
        Animations.resetToDefaults();
        FpsOverlay.resetToDefaults();
        FreeLook.resetToDefaults();

        ok("animations flags gated while master off", gated(settings, "animations", "blockHit"));
        ok("fps colour gated while autoColour on", gated(settings, "fps", "colour"));
        ok("fov is never gated", !gated(settings, "fov", "value"));

        Animations.setEnabled(true);
        ok("animations flags ungated when master on", !gated(settings, "animations", "blockHit"));
        Animations.resetToDefaults();
    }

    /** A write before load() must not create the file, or the legacy import would be skipped. */
    private static void saveIsIgnoredBeforeLoad()
    {
        clearLoaded();
        cfg().delete();

        ClientConfig.save();
        ClientConfig.saveVanilla();

        ok("no file written before load", !cfg().exists());
    }

    /** After load the file lists every section and every key the table knows about. */
    private static void loadWritesEverySetting()
    {
        cfg().delete();
        ClientConfig.load();

        ok("client.cfg created by load", cfg().exists());

        String text = read(cfg());

        for (int i = 0; i < EXPECTED_SECTIONS.length; ++i)
        {
            ok("header [" + EXPECTED_SECTIONS[i] + "]", text.contains("[" + EXPECTED_SECTIONS[i] + "]"));
        }

        List<Setting> settings = ClientConfig.settings();

        for (int i = 0; i < settings.size(); ++i)
        {
            Setting s = settings.get(i);
            ok("file has " + s.qualifiedKey(), text.contains("\n" + s.getKey() + "="));
        }

        eq("no stray files", 0, strayCfgs());
    }

    /** Everything set away from its default comes back after a save, a reset and a load. */
    private static void valuesSurviveARoundTrip()
    {
        ClientConfig.load();

        put("bob", "hand", "false");
        put("bob", "camera", "true");
        put("nhk", "enabled", "true");
        put("sprint", "enabled", "true");
        put("animations", "enabled", "true");
        put("animations", "rod", "true");
        put("animations", "smoothSneakSpeed", "12.5");
        put("fps", "enabled", "true");
        put("fps", "mode", "smooth");
        put("fps", "size", "2.5");
        put("fps", "posX", "123");
        put("fps", "alpha", "77");
        put("fps", "autoColour", "false");
        put("fps", "colour", "#123456");
        put("fps", "shadow", "false");
        put("freelook", "mode", "toggle");
        put("freelook", "view", "third");

        mc.gameSettings.setOptionFloatValue(GameSettings.Options.FOV, 103.0F);

        ClientConfig.save();

        // Back to defaults in memory only, then read the file again.
        Animations.resetToDefaults();
        FpsOverlay.resetToDefaults();
        FreeLook.resetToDefaults();
        mc.gameSettings.setOptionFloatValue(GameSettings.Options.FOV, 70.0F);
        mc.gameSettings.viewBobbing = true;
        mc.gameSettings.cameraBobbing = false;
        mc.gameSettings.noHurtCam = false;
        mc.gameSettings.alwaysSprint = false;

        ClientConfig.load();

        eq("bob.hand", "false", get("bob", "hand"));
        eq("bob.camera", "true", get("bob", "camera"));
        eq("nhk.enabled", "true", get("nhk", "enabled"));
        eq("sprint.enabled", "true", get("sprint", "enabled"));
        eq("animations.enabled", "true", get("animations", "enabled"));
        eq("animations.rod", "true", get("animations", "rod"));
        eq("animations.smoothSneakSpeed", "12.5", get("animations", "smoothSneakSpeed"));
        eq("fps.enabled", "true", get("fps", "enabled"));
        eq("fps.mode", "smooth", get("fps", "mode"));
        eq("fps.size", "2.5", get("fps", "size"));
        eq("fps.posX", "123", get("fps", "posX"));
        eq("fps.alpha", "77", get("fps", "alpha"));
        eq("fps.autoColour", "false", get("fps", "autoColour"));
        eq("fps.colour", "#123456", get("fps", "colour"));
        eq("fps.shadow", "false", get("fps", "shadow"));
        eq("freelook.mode", "toggle", get("freelook", "mode"));
        eq("freelook.view", "third", get("freelook", "view"));
        eq("fov.value", "103.0", get("fov", "value"));

        // The vanilla-backed values must reach GameSettings, not just the file.
        ok("noHurtCam applied", mc.gameSettings.noHurtCam);
        ok("alwaysSprint applied", mc.gameSettings.alwaysSprint);
        ok("viewBobbing applied", !mc.gameSettings.viewBobbing);
        ok("cameraBobbing applied", mc.gameSettings.cameraBobbing);
        eq("fov applied", 103.0F, mc.gameSettings.getOptionFloatValue(GameSettings.Options.FOV));
    }

    /** Bad booleans, out-of-range numbers and unknown words all fall back rather than throw. */
    private static void unusableTextKeepsDefaults()
    {
        write(cfg(), "# hand edited\n"
            + "[fov]\n"
            + "value=not-a-number\n"
            + "\n"
            + "[bob]\n"
            + "hand=yes\n"
            + "\n"
            + "[nhk]\n"
            + "enabled=1\n"
            + "\n"
            + "[sprint]\n"
            + "enabled=TRUE\n"
            + "\n"
            + "[animations]\n"
            + "enabled=true\n"
            + "smoothSneakSpeed=9999\n"
            + "notAKey=whatever\n"
            + "\n"
            + "[fps]\n"
            + "mode=fancy\n"
            + "size=-4\n"
            + "\n"
            + "[freelook]\n"
            + "mode=sideways\n"
            + "view=north\n");

        ClientConfig.load();

        eq("fov keeps default", "70.0", get("fov", "value"));
        eq("bob.hand keeps default", "true", get("bob", "hand"));
