        eq("sprint accepts TRUE", "true", get("sprint", "enabled"));
        eq("unknown mode ignored", "normal", get("fps", "mode"));
        eq("size clamped to min", "0.5", get("fps", "size"));
        eq("sneak speed clamped to max", "20.0", get("animations", "smoothSneakSpeed"));
        eq("freelook mode keeps default", "hold", get("freelook", "mode"));
        eq("freelook view keeps default", "both", get("freelook", "view"));

        // A missing section must not disturb the others.
        eq("absent section still defaults", "1.0", get("fps", "size"));
    }

    /** The three old files are folded in on the first run, then left alone. */
    private static void legacyFilesAreImportedOnce()
    {
        cfg().delete();
        new File(dir, "animations.cfg").delete();
        new File(dir, "fpsdisplay.cfg").delete();
        new File(dir, "freelook.cfg").delete();

        write(new File(dir, "animations.cfg"), "enabled=true\nrod=true\nsmoothSneakSpeed=9.0\n");
        write(new File(dir, "fpsdisplay.cfg"), "enabled=true\nmode=smooth\nposX=42\n");
        write(new File(dir, "freelook.cfg"), "mode=toggle\nview=first\n");

        ClientConfig.load();

        eq("animations imported", "true", get("animations", "enabled"));
        eq("animations.rod imported", "true", get("animations", "rod"));
        eq("smoothSneakSpeed imported", "9.0", get("animations", "smoothSneakSpeed"));
        eq("fps imported", "true", get("fps", "enabled"));
        eq("fps.posX imported", "42", get("fps", "posX"));
        eq("freelook.view imported", "first", get("freelook", "view"));
        ok("client.cfg written after import", cfg().exists());

        ok("animations.cfg kept", new File(dir, "animations.cfg").exists());
        ok("fpsdisplay.cfg kept", new File(dir, "fpsdisplay.cfg").exists());
        ok("freelook.cfg kept", new File(dir, "freelook.cfg").exists());

        // Second launch must not re-import over the newer file.
        put("animations", "rod", "false");
        ClientConfig.save();
        ClientConfig.load();

        eq("import does not run twice", "false", get("animations", "rod"));
    }

    /**
     * A fixed colour has to win over auto colouring whether or not the file mentions it, and must
     * not be pinned back when the file does mention it.
     */
    private static void fpsColourPairReconciles()
    {
        write(cfg(), "[fps]\nautoColour=true\ncolour=#00FF00\n");
        ClientConfig.load();
        eq("both keys: autoColour wins", "true", get("fps", "autoColour"));
        eq("both keys: colour read", "#00FF00", get("fps", "colour"));

        write(cfg(), "[fps]\ncolour=#0000FF\n");
        ClientConfig.load();
        eq("colour alone: autoColour yields", "false", get("fps", "autoColour"));
        eq("colour alone: colour read", "#0000FF", get("fps", "colour"));

        write(cfg(), "[fps]\nautoColour=false\ncolour=#FF0000\n");
        ClientConfig.load();
        eq("autoColour=false honoured", "false", get("fps", "autoColour"));

        // Picking a colour through the table must not switch auto colouring off by itself.
        put("fps", "autoColour", "true");
        eq("autoColour still on", "true", get("fps", "autoColour"));
        set("fps", "colour", "#FFFFFF");
        eq("table colour change leaves autoColour alone", "true", get("fps", "autoColour"));
    }

    /** A held drag must not touch the file until it is released. */
    private static void heldDragCostsOneWrite()
    {
        ClientConfig.load();
        put("fps", "posX", "10");
        ClientConfig.save();

        long before = cfg().lastModified();

        ClientConfig.beginBulkChange();
        set("fps", "posX", "20");
        set("fps", "posY", "30");

        eq("nothing written mid-drag", before, cfg().lastModified());

        ClientConfig.endBulkChange();
        ok("written on release", cfg().lastModified() != before || read(cfg()).contains("posX=20"));
        eq("value landed", "20", get("fps", "posX"));

        // A no-op drag should still leave a consistent file rather than dropping the write.
        ClientConfig.beginBulkChange();
        ClientConfig.endBulkChange();
        ok("file still readable", read(cfg()).contains("[fps]"));
    }

    /** Reset All returns every setting, including the vanilla-backed four, to its default. */
    private static void resetPutsEverythingBack()
    {
        put("bob", "hand", "false");
        put("bob", "camera", "true");
        put("nhk", "enabled", "true");
        put("sprint", "enabled", "true");
        put("animations", "enabled", "true");
        put("animations", "rod", "true");
        put("fps", "enabled", "true");
        put("fps", "mode", "smooth");
        put("fps", "colour", "#123456");
        put("freelook", "mode", "toggle");
        put("freelook", "view", "third");
        mc.gameSettings.setOptionFloatValue(GameSettings.Options.FOV, 111.0F);

        ClientConfig.resetAll();

        eq("reset fov", "70.0", get("fov", "value"));
        eq("reset bob.hand", "true", get("bob", "hand"));
        eq("reset bob.camera", "false", get("bob", "camera"));
        eq("reset nhk", "false", get("nhk", "enabled"));
        eq("reset sprint", "false", get("sprint", "enabled"));
        eq("reset animations.enabled", "false", get("animations", "enabled"));
        eq("reset animations.rod", "false", get("animations", "rod"));
        eq("reset fps.enabled", "false", get("fps", "enabled"));
        eq("reset fps.mode", "normal", get("fps", "mode"));
        eq("reset fps.colour", "#FFFFFF", get("fps", "colour"));
        eq("reset fps.autoColour", "true", get("fps", "autoColour"));
        eq("reset freelook.mode", "hold", get("freelook", "mode"));
        eq("reset freelook.view", "both", get("freelook", "view"));

        ok("reset wrote the file", read(cfg()).contains("enabled=false"));
        eq("reset applied to GameSettings", 70.0F, mc.gameSettings.getOptionFloatValue(GameSettings.Options.FOV));
        ok("reset noHurtCam", !mc.gameSettings.noHurtCam);
