    /** After a full reset only client.cfg remains; the legacy files are gone for good. */
    private static void fileNameIsTheOnlyOne()
    {
        new File(dir, "animations.cfg").delete();
        new File(dir, "fpsdisplay.cfg").delete();
        new File(dir, "freelook.cfg").delete();

        ClientConfig.resetAll();

        eq("no per-mod files left", 0, strayCfgs());
        eq("config file name", "client.cfg", cfg().getName());
        eq("config file path", new File(dir, "client.cfg").getAbsolutePath(), cfg().getAbsolutePath());
    }

    // --- helpers ------------------------------------------------------------------

    private static String masterName(Setting setting)
    {
        // The only gated rows are the animation flags, the FPS look rows and the colour, and all
        // of them name an existing master. A row with no gate returns its own key, which cannot
        // match a different row, so the lookup below safely ignores it.
        String gate = gateOf(setting);
        return gate;
    }

    private static String gateOf(Setting setting)
    {
        try
        {
            Field section = Setting.class.getDeclaredField("masterSection");
            Field key = Setting.class.getDeclaredField("masterKey");
            section.setAccessible(true);
            key.setAccessible(true);

            String s = (String)section.get(setting);
            String k = (String)key.get(setting);
            return s == null ? "\0none" : s + "." + k;
        }
        catch (Exception exception)
        {
            throw new RuntimeException(exception);
        }
    }

    private static Setting find(List<Setting> settings, String qualified)
    {
        for (int i = 0; i < settings.size(); ++i)
        {
            if (settings.get(i).qualifiedKey().equals(qualified))
            {
                return settings.get(i);
            }
        }

        return null;
    }

    private static boolean gated(List<Setting> settings, String section, String key)
    {
        return find(settings, section + "." + key).isGatedOff();
    }

    private static Setting setting(String section, String key)
    {
        Setting found = find(ClientConfig.settings(), section + "." + key);

        if (found == null)
        {
            throw new IllegalArgumentException("no such setting " + section + "." + key);
        }

        return found;
    }

    private static String get(String section, String key)
    {
        return setting(section, key).get();
    }

    private static void set(String section, String key, String value)
    {
        setting(section, key).set(value);
    }

    private static void put(String section, String key, String value)
    {
        setting(section, key).set(value);
    }

    private static int strayCfgs()
    {
        File[] files = dir.listFiles();
        int count = 0;

        if (files != null)
        {
            for (int i = 0; i < files.length; ++i)
            {
                String name = files[i].getName();

                if (name.endsWith(".cfg") && !name.equals(ClientConfig.FILE_NAME))
                {
                    count++;
                }
            }
        }

        return count;
    }

    private static File cfg()
    {
        return new File(dir, ClientConfig.FILE_NAME);
    }

    /** Puts the "already loaded" flag back to false, to test the write guard from scratch. */
    private static void clearLoaded()
    {
        try
        {
            Field loaded = ClientConfig.class.getDeclaredField("loaded");
            loaded.setAccessible(true);
            loaded.setBoolean(null, false);
        }
        catch (Exception exception)
        {
            throw new RuntimeException(exception);
        }
    }

    private static File scratch() throws Exception
    {
        File base = new File(System.getProperty("java.io.tmpdir"), "clientcfg-test");
        deleteTree(base);

        if (!base.mkdirs())
        {
            throw new IllegalStateException("could not create " + base);
        }

        return base;
    }

    private static void deleteTree(File file)
    {
        File[] children = file.listFiles();

        if (children != null)
        {
            for (int i = 0; i < children.length; ++i)
            {
                deleteTree(children[i]);
            }
        }

        file.delete();
    }

    /**
     * Installs a Minecraft with a real GameSettings and a scratch game directory.
     *
     * <p>Unsafe is the only way to get an instance without running the constructor, which would
     * need a window. mcDataDir is final but reflection can still set a non-static final field,
     * which is what lets the config file land somewhere known.</p>
     */
    private static Minecraft install(File dataDir) throws Exception
    {
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);

        Minecraft instance = (Minecraft)allocate.invoke(unsafe, Minecraft.class);

        Field dirField = Minecraft.class.getDeclaredField("mcDataDir");
        dirField.setAccessible(true);
        dirField.set(instance, dataDir);

        instance.gameSettings = new GameSettings();

        Field singleton = Minecraft.class.getDeclaredField("theMinecraft");
        singleton.setAccessible(true);
        singleton.set(null, instance);

        return instance;
    }

    private static String read(File file)
    {
        try
        {
            StringBuilder text = new StringBuilder();
            BufferedReaderHolder holder = new BufferedReaderHolder(file);
            String line;

            while ((line = holder.reader.readLine()) != null)
            {
                text.append(line).append('\n');
            }

            holder.close();
            return text.toString();
        }
        catch (Exception exception)
        {
            throw new RuntimeException(exception);
        }
    }

    private static void write(File file, String text)
    {
        PrintWriter writer = null;

        try
        {
            writer = new PrintWriter(new OutputStreamWriter(new FileOutputStream(file), "UTF-8"));
            writer.print(text);
        }
        catch (Exception exception)
        {
            throw new RuntimeException(exception);
        }
        finally
        {
            if (writer != null)
            {
                writer.close();
            }
        }
    }

    /** Keeps the reader type out of the signature of {@link #read}. */
    private static final class BufferedReaderHolder
    {
        final java.io.BufferedReader reader;

        BufferedReaderHolder(File file) throws Exception
        {
            this.reader = new java.io.BufferedReader(new InputStreamReader(new FileInputStream(file), "UTF-8"));
        }

        void close() throws Exception
        {
            this.reader.close();
        }
    }

    private static void ok(String what, boolean condition)
    {
        ++checks;

        if (!condition)
        {
            ++failures;
            System.out.println("FAIL  " + what);
        }
    }

    private static void eq(String what, Object expected, Object actual)
    {
        ++checks;

        if (expected == null ? actual != null : !expected.equals(actual))
        {
            ++failures;
            System.out.println("FAIL  " + what + ": expected <" + expected + "> but was <" + actual + ">");
        }
    }

    private ConfigTest() {}
}

