ew File(dir, \"freelook.cfg\"), \"mode=toggle\\nview=first\\n\");\n\n        ClientConfig.load();\n\n        eq(\"animations imported\", \"true\", get(\"animations\", \"enabled\"));\n        eq(\"animations.rod imported\", \"true\", get(\"animations\", \"rod\"));\n        eq(\"smoothSneakSpeed imported\", \"9.0\", get(\"animations\", \"smoothSneakSpeed\"));\n        eq(\"fps imported\", \"true\", get(\"fps\", \"enabled\"));\n        eq(\"fps.posX imported\", \"42\", get(\"fps\", \"posX\"));\n        eq(\"freelook.view imported\", \"first\", get(\"freelook\", \"view\"));\n        ok(\"client.cfg written after import\", cfg().exists());\n\n        ok(\"animations.cfg kept\", new File(dir, \"animations.cfg\").exists());\n        ok(\"fpsdisplay.cfg kept\", new File(dir, \"fpsdisplay.cfg\").exists());\n        ok(\"freelook.cfg kept\", new File(dir, \"freelook.cfg\").exists());\n\n        // Second launch must not re-import over the newer file.\n        put(\"animations\", \"rod\", \"false\");\n        ClientConfig.save();\n        ClientConfig.load();\n\n        eq(\"import does not run twice\", \"false\", get(\"animations\", \"rod\"));\n    }\n\n    /**\n     * A fixed colour has to win over auto colouring whether or not the file mentions it, and must\n     * not be pinned back when the file does mention it.\n     */\n    private static void fpsColourPairReconciles()\n    {\n        write(cfg(), \"[fps]\\nautoColour=true\\ncolour=#00FF00\\n\");\n        ClientConfig.load();\n        eq(\"both keys: autoColour wins\", \"true\", get(\"fps\", \"autoColour\"));\n        eq(\"both keys: colour read\", \"#00FF00\", get(\"fps\", \"colour\"));\n\n        write(cfg(), \"[fps]\\ncolour=#0000FF\\n\");\n        ClientConfig.load();\n        eq(\"colour alone: autoColour yields\", \"false\", get(\"fps\", \"autoColour\"));\n        eq(\"colour alone: colour read\", \"#0000FF\", get(\"fps\", \"colour\"));\n\n        write(cfg(), \"[fps]\\nautoColour=false\\ncolour=#FF0000\\n\");\n  