 eq(\"config file path\", new File(dir, \"client.cfg\").getAbsolutePath(), cfg().getAbsolutePath());\n    }\n\n    // --- helpers ------------------------------------------------------------------\n\n    private static String masterName(Setting setting)\n    {\n        // The only gated rows are the animation flags, the FPS look rows and the colour, and all\n        // of them name an existing master. A row with no gate returns its own key, which cannot\n        // match a different row, so the lookup below safely ignores it.\n        String gate = gateOf(setting);\n        return gate;\n    }\n\n    private static String gateOf(Setting setting)\n    {\n        try\n        {\n            Field section = Setting.class.getDeclaredField(\"masterSection\");\n            Field key = Setting.class.getDeclaredField(\"masterKey\");\n            section.setAccessible(true);\n            key.setAccessible(true);\n\n            String s = (String)section.get(setting);\n            String k = (String)key.get(setting);\n            return s == null ? \"\\0none\" : s + \".\" + k;\n        }\n        catch (Exception exception)\n        {\n            throw new RuntimeException(exception);\n        }\n    }\n\n    private static Setting find(List<Setting> settings, String qualified)\n    {\n        for (int i = 0; i < settings.size(); ++i)\n        {\n            if (settings.get(i).qualifiedKey().equals(qualified))\n            {\n                return settings.get(i);\n            }\n        }\n\n        return null;\n    }\n\n    private static boolean gated(List<Setting> settings, String section, String key)\n    {\n        return find(settings, section + \".\" + key).isGatedOff();\n    }\n\n    private static Setting setting(String section, String key)\n    {\n        Setting found = find(ClientConfig.settings(), section + \".\" + key);\n\n        if (found == null)\n        {\n            throw new IllegalArgumentException(\"no such setting \" + section + \".\" + key);\n  