    /**
     * The bind that opens the mod settings screen.
     *
     * <p>Left unbound on purpose: it has no obvious home key, and stealing one would surprise
     * people who expect it to do what it does in vanilla.</p>
     */
    private static void clientSettingsBind() throws Exception
    {
        GameSettings settings = new GameSettings();
        KeyBinding bind = settings.keyBindClientSettings;

        check("settings field is initialised", bind != null);

        if (bind == null)
        {
            report();
            return;
        }

        check("settings named by lang key", "key.clientSettings".equals(bind.getKeyDescription()));
        check("settings lang key resolves to text", langValue("key.clientSettings") != null);
        check("settings present in keyBindings", indexOf(settings, bind) >= 0);
        check("settings unbound by default", bind.getKeyCode() == KEY_UNBOUND);
        check("settings in the Misc category", "key.categories.misc".equals(bind.getKeyCategory()));
        check("settings not already bound elsewhere", collisions(settings, bind) == 0);

        report();
    }

