/**
 * Headless checks that the two binds this build adds are actually wired into vanilla's key bind
 * handling: free look, and the one that opens the mod settings screen.
 *
 * <p>{@code GuiKeyBindingList} groups binds by {@code KeyBinding.getKeybinds()} category and
 * iterates {@code gameSettings.keyBindings}, so being in that array is all it takes for a bind
 * to show up under Options &gt; Controls. This asserts that, plus that neither default collides
 * with anything vanilla already uses.</p>
 */
public final class KeyBindTest
{
    /** Vanilla key code for "no key", i.e. a bind with no default. */
    private static final int KEY_UNBOUND = 0;

    /** LWJGL key code for V, the default free look bind. */
    private static final int KEY_V = 47;

