200: 
201:     /**
202:      * Whether free look is permitted in the view the player is actually in right now. Treated as
203:      * permitted whenever the game is not running, so the state machine stays testable headless.
204:      */
205:     private static boolean allowsCurrentView()
206:     {
207:         Minecraft mc = Minecraft.getMinecraft();
208:         return mc == null || mc.gameSettings == null || allowsView(mc.gameSettings.thirdPersonView > 0);
209:     }
210: 
211:     /**
212:      * Drops the toggle and any banked offset when the current view forbids free look. Called both
213:      * when the restriction changes and on every mouse update, so pressing F5 into a disallowed
214:      * view hands the camera straight back to the body instead of leaving it stranded off it.
215:      */
216:     private static void dropIfDisallowed()
217:     {
218:         if (!allowsCurrentView())
219:         {
220:             latched = false;
221:             clearOffsets();
222:         }
223:     }
224: 
225:     // --- mouse handling ----------------------------------------------------------
226: 
227:     /**
228:      * Called from {@code EntityPlayerSP.setAngles} with the raw per-frame mouse deltas.
229:      *
230:      * @return true if the deltas were consumed and the body must not be turned
231:      */
232:     public static boolean onMouseLook(float yawDelta, float pitchDelta)
233:     {
234:         // A disallowed view wins over the bind. The deltas are handed to the body untouched and
235:         // the offset is dropped outright rather than eased, so F5 lands the camera exactly where
