268: 
269:         if (!enabled)
270:         {
271:             latched = false;
272:             active = false;
273:         }
274:         else
275:         {
276:             if (mode == Mode.TOGGLE && down && !keyWasDown)
277:             {
278:                 latched = !latched;
279:             }
280: 
281:             active = mode == Mode.HOLD ? down : latched;
282:         }
