/**
     * Turns the automatic third-person switch on or off.
     *
     * <p>Any camera move it was mid-way through is undone, so the setting can be flipped without
     * leaving the view somewhere free look would not have put it.</p>
     */
    public static void setAutoF5(boolean value)
    {
        if (autoF5 == value)
        {
            return;
        }

        autoF5 = value;

        if (!autoF5)
        {
            // It was mid-move; complete the return so the camera lands where it would have.
            moveCamera(0);
        }

        save();
    }

    /** True when auto-F5 is on and the view restriction leaves it room to act. */
    private static boolean autoF5Applies()
    {
        return autoF5 && view != View.FIRST;
    }

    /** Third person from behind, which is the view auto-F5 asks for. */
    private static final int THIRD_PERSON_BACK = 1;

    /** First person, which is where auto-F5 hands the camera back. */
    private static final int FIRST_PERSON = 0;

    /**
     * Moves the camera for an auto-F5 engage or release.
     *
     * <p>Only ever called on a change of {@link #active}, so it cannot fight a player who is
     * holding free look and cycling views themselves.</p>
     *
     * @param toThirdPerson true to engage, false to release
     */
    private static void moveCamera(boolean toThirdPerson)
    {
        GameSettings settings = gameSettings();

        if (settings == null)
        {
            // No game running, which is what the headless tests look like.
            return;
        }

        settings.thirdPersonView = toThirdPerson ? THIRD_PERSON_BACK : FIRST_PERSON;
    }

