/**
     * A Minecraft instance with nothing initialised. The view gate only ever reads
     * {@code gameSettings} off it, so a blank shell is enough, and Unsafe is the only way to get
     * one without running the real constructor.
     *
     * <p>The game directory is pointed at a scratch folder so the public setters, which write
     * {@value} client.cfg on every change, can be exercised for real. main restores the real
     * config file afterwards.</p>
     */
    private static Minecraft newFakeMinecraft() throws Exception
    {
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);

        Minecraft mc = (Minecraft)allocate.invoke(unsafe, Minecraft.class);

        // Final, but reflection can still write a non-static final field, which is what keeps the
        // config writes out of the real game directory.
        Field dirField = fieldOf(Minecraft.class, "mcDataDir");
        dirField.set(mc, scratchDir());

        mc.gameSettings = new GameSettings();

        // Left unbound on purpose: an unbound key keeps isKeyDown out of the picture.
        mc.gameSettings.keyBindFreeLook.setKeyCode(0);
        return mc;
    }

    /** A directory for config writes that can be thrown away afterwards. */
    private static File scratchDir() throws Exception
    {
        File dir = new File("freelook-scratch");

        if (!dir.exists() && !dir.mkdirs())
        {
            throw new IllegalStateException("could not create " + dir);
        }

        return dir;
    }

    /** Removes the scratch game directory, so nothing is left lying around. */
    private static void deleteScratch(File dir)
    {
        File[] children = dir.listFiles();

        if (children != null)
        {
            for (int i = 0; i < children.length; ++i)
            {
                children[i].delete();
            }
        }

        dir.delete();
    }

