package net.minecraft.client.commands;

import java.io.File;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import net.minecraft.client.Minecraft;

/**
 * ReachCircle: state, persistence, and the guards around rendering.
 *
 * <p>The GL drawing itself cannot be exercised without a display, so what is checked here is
 * everything that decides whether it draws at all, plus the parts of the config table that used to
 * be a trap: isMasterOn fell through to FreeLook for any section it did not know, so a new section
 * added without extending it would silently display and save the free look state instead of its
 * own.</p>
 */
public class ReachCircleTest
{
    private static int checks;
    private static int failures;

    public static void main(String[] args) throws Exception
    {
        File dir = scratch();
        Object savedSingleton = install(dir);
        File real = ReachCircle.getConfigFile();
        boolean hadReal = real.exists();
        String beforeReal = hadReal ? read(real) : null;

        try
        {
            defaults();
            stateAndPersistence(dir);
            renderGuards();
            tableRowFollowsItsOwnMod();
        }
        finally
        {
            restore(real, hadReal, beforeReal);
            clear(dir);
        }

        System.out.println(failures == 0
            ? "PASS  " + checks + " checks"
            : "FAIL  " + failures + " of " + checks + " checks");

        if (failures != 0)
        {
            System.exit(1);
        }
    }

    // --- scenarios ---------------------------------------------------------------

    private static void defaults() throws Exception
    {
        ReachCircle.resetToDefaults();
        check("off by default", !ReachCircle.isEnabled());
        check("radius is 3 blocks", ReachCircle.RADIUS == 3.0F);
    }

    private static void stateAndPersistence(File dir) throws Exception
    {
        File file = new File(dir, ClientConfig.FILE_NAME);

        ReachCircle.resetToDefaults();
        ReachCircle.setEnabled(true);
        check("enabled after setEnabled(true)", ReachCircle.isEnabled());
        check("config file written", file.exists());
        check("file records the section", read(file).contains("[reachcircle]"));
        check("file records the key", read(file).contains("enabled=true"));

        // A no-op must not rewrite the file, matching every other mod.
        long before = file.lastModified();
        ReachCircle.setEnabled(true);
        check("redundant set does not rewrite", file.lastModified() == before);

        // Round trip through a real load.
        ReachCircle.resetToDefaults();
        check("reset turns it off", !ReachCircle.isEnabled());
        ClientConfig.load();
        check("survives a reload", ReachCircle.isEnabled());

        ReachCircle.reset();
        check("public reset turns it off", !ReachCircle.isEnabled());
        ClientConfig.load();
        check("off survives a reload", !ReachCircle.isEnabled());

        // Nonsense on disk falls back to the default rather than sticking.
        write(file, "[reachcircle]\nenabled=banana\n");
        ClientConfig.load();
        check("unknown value falls back to the default", !ReachCircle.isEnabled());

        write(file, "[reachcircle]\nenabled=true\n");
        ClientConfig.load();
        check("bare section parses", ReachCircle.isEnabled());
    }

    /**
     * render() is called every frame from the renderer, including while the world is still being
     * built and after the player is gone, so it has to bail out rather than throw.
     */
    private static void renderGuards() throws Exception
    {
        ReachCircle.setEnabled(false);
        near("render while off does not touch GL", renderSafely(), "clean");

        ReachCircle.setEnabled(true);
        near("render with no player does not touch GL", renderSafely(), "clean");
        check("still enabled after a no-player render", ReachCircle.isEnabled());
    }

    /** Calls render() and reports whether it returned without throwing. */
    private static String renderSafely()
    {
        try
        {
            ReachCircle.render(1.0F);
            return "clean";
        }
        catch (Throwable thrown)
        {
            return thrown.getClass().getName();
        }
    }

    /**
     * The row the GUI renders has to report the reach circle's own state. This is the exact failure
     * a new section hits when isMasterOn and the masterToggle setter are not both extended.
     */
    private static void tableRowFollowsItsOwnMod() throws Exception
    {
        ReachCircle.resetToDefaults();
        FreeLook.setEnabled(false);
        check("row reads false when both mods are off", "false".equals(rowValue()));

        // Free look on, reach circle off: the row must not follow free look.
        FreeLook.setEnabled(true);
        check("row does not follow free look", "false".equals(rowValue()));

        FreeLook.setEnabled(false);
        ReachCircle.setEnabled(true);
        check("row follows the reach circle", "true".equals(rowValue()));

        // And the setter has to write the reach circle, not free look.
        applyRow("false");
        check("row setter turns the reach circle off", !ReachCircle.isEnabled());
        check("row setter leaves free look alone", !FreeLook.isEnabled());

        applyRow("true");
        check("row setter turns the reach circle on", ReachCircle.isEnabled());

        FreeLook.setEnabled(false);
        ReachCircle.reset();
    }

    // --- helpers -----------------------------------------------------------------

    private static String rowValue()
    {
        return ClientConfig.setting("reachcircle", "enabled").get();
    }

    private static void applyRow(String value)
    {
        ClientConfig.setting("reachcircle", "enabled").set(value);
    }

    private static File scratch() throws Exception
    {
        File dir = new File("reachcircle-scratch");

        if (!dir.exists() && !dir.mkdirs())
        {
            throw new IllegalStateException("could not create " + dir);
        }

        return dir;
    }

    private static Object install(File dir) throws Exception
    {
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);

        Minecraft mc = (Minecraft)allocate.invoke(unsafe, Minecraft.class);

        // Final, but reflection can still write a non-static final field. This is what keeps the
        // config writes in the scratch directory.
        Field dirField = Minecraft.class.getDeclaredField("mcDataDir");
        dirField.setAccessible(true);
        dirField.set(mc, dir);

        // No player and no world, which is the state render() has to survive.
        mc.gameSettings = new net.minecraft.client.settings.GameSettings();

        Field singleton = Minecraft.class.getDeclaredField("theMinecraft");
        singleton.setAccessible(true);
        Object before = singleton.get(null);
        singleton.set(null, mc);
        return before;
    }

    private static void write(File file, String contents) throws Exception
    {
        java.io.PrintWriter writer = new java.io.PrintWriter(file, "UTF-8");
        writer.print(contents);
        writer.close();
    }

    private static String read(File file) throws Exception
    {
        if (!file.exists())
        {
            return "";
        }

        java.io.BufferedReader reader = new java.io.BufferedReader(
            new java.io.InputStreamReader(new java.io.FileInputStream(file), "UTF-8"));
        StringBuilder builder = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null)
        {
            builder.append(line).append('\n');
        }

        reader.close();
        return builder.toString();
    }

    private static void restore(File file, boolean hadFile, String contents) throws Exception
    {
        if (hadFile)
        {
            write(file, contents);
        }
        else if (file.exists())
        {
            file.delete();
        }
    }

    private static void clear(File dir)
    {
        File[] children = dir.listFiles();

        if (children != null)
        {
            for (int i = 0; i < children.length; ++i)
            {
                children[i].delete();
            }
        }

        dir.delete();
    }

    private static void check(String what, boolean ok)
    {
        ++checks;

        if (!ok)
        {
            ++failures;
            System.out.println("  FAIL  " + what);
        }
    }

    private static void near(String what, String actual, String expected)
    {
        ++checks;

        if (!expected.equals(actual))
        {
            ++failures;
            System.out.println("  FAIL  " + what + " (expected " + expected + ", got " + actual + ")");
        }
    }
}

