package net.minecraft.client.commands;

import java.io.File;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Locale;
import net.minecraft.client.Minecraft;
import net.minecraft.client.entity.EntityPlayerSP;

/**
 * CoordsHud: state, persistence, and the text it produces.
 *
 * <p>The formatting checks matter more than they look. String.format takes its decimal separator
 * from the default locale, so a build that forgets Locale.ROOT renders every value with commas on a
 * machine set to a European language, which turns three numbers into what looks like one field.
 * That failure is invisible to a developer on an en-US machine, so it is pinned here by forcing a
 * comma locale and asserting the output does not move.</p>
 */
public class CoordsHudTest
{
    private static int checks;
    private static int failures;

    public static void main(String[] args) throws Exception
    {
        File dir = scratch();
        Object savedSingleton = install(dir);
        File real = CoordsHud.getConfigFile();
        boolean hadReal = real.exists();
        String beforeReal = hadReal ? read(real) : null;
        Locale savedLocale = Locale.getDefault();

        try
        {
            defaults();
            numberFormatting(savedLocale);
            wrapYaw();
            textOutput();
            stateAndPersistence(dir);
            renderGuards();
            tableRows();
        }
        finally
        {
            Locale.setDefault(savedLocale);
            restoreSingleton(savedSingleton);
            restore(real, hadReal, beforeReal);
            clear(dir);
        }

        System.out.println(failures == 0
            ? "PASS  " + checks + " checks"
            : "FAIL  " + failures + " of " + checks + " checks");

        if (failures != 0)
        {
            System.exit(1);
        }
    }

    // --- scenarios ---------------------------------------------------------------

    private static void defaults() throws Exception
    {
        CoordsHud.resetToDefaults();
        check("off by default", !CoordsHud.isEnabled());
        check("size defaults to 1", CoordsHud.getSize() == 1.0F);
        check("posX defaults to 4", CoordsHud.getPosX() == 4);
        check("posY sits below the fps readout", CoordsHud.getPosY() == 14);
        check("ten decimals", CoordsHud.DECIMALS == 10);
    }

    private static void numberFormatting(Locale savedLocale) throws Exception
    {
        eq("one", CoordsHud.number(1.0D), "1.0000000000");
        eq("negative", CoordsHud.number(-0.5D), "-0.5000000000");
        eq("zero", CoordsHud.number(0.0D), "0.0000000000");
        eq("small", CoordsHud.number(0.0000000001D), "0.0000000001");

        // The whole point: the separator must not follow the machine's locale.
        for (String tag : new String[] {"de-DE", "fr-FR", "ru-RU", "vi-VN"})
        {
            Locale.setDefault(Locale.forLanguageTag(tag));
            eq("dot separator under " + tag, CoordsHud.number(1.5D), "1.5000000000");
            eq("thousands grouping off under " + tag, CoordsHud.number(1234.5D), "1234.5000000000");
        }

        Locale.setDefault(Locale.US);
        eq("back to en-US", CoordsHud.number(1.5D), "1.5000000000");

        eq("NaN", CoordsHud.number(Double.NaN), "NaN");
        eq("positive infinity", CoordsHud.number(Double.POSITIVE_INFINITY), "Inf");
        eq("negative infinity", CoordsHud.number(Double.NEGATIVE_INFINITY), "-Inf");
    }

    private static void wrapYaw() throws Exception
    {
        near("zero wraps to zero", CoordsHud.wrapYaw(0.0F), 0.0F);
        near("already in range", CoordsHud.wrapYaw(90.5F), 90.5F);
        near("half turn folds to the negative side", CoordsHud.wrapYaw(180.0F), -180.0F);
        near("negative half turn stays", CoordsHud.wrapYaw(-180.0F), -180.0F);
        near("three quarters", CoordsHud.wrapYaw(270.0F), -90.0F);
        near("full turn", CoordsHud.wrapYaw(360.0F), 0.0F);
        near("two turns", CoordsHud.wrapYaw(720.0F), 0.0F);
        near("long drift folds once", CoordsHud.wrapYaw(3600.0F + 45.5F), 45.5F);
    }

    private static void textOutput() throws Exception
    {
        EntityPlayerSP player = newPlayer();
        player.posX = 1.5D;
        player.posY = -2.25D;
        player.posZ = 3.125D;
        player.rotationYaw = 450.5F;
        player.rotationPitch = -12.5F;

        // Every literal is exactly representable in binary, so this compares formatting rather
        // than the rounding of the input.
        eq("readout layout", CoordsHud.build(player),
            "XYZ: 1.5000000000 / -2.2500000000 / 3.1250000000"
            + "\nYaw: 90.5000000000  Pitch: -12.5000000000");

        // A double past float precision keeps its digits: posY is a double on purpose.
        player.posX = 0.1D;
        check("position keeps double precision", CoordsHud.build(player).contains("XYZ: 0.1000000000"));

        // Yaw is a float, so beyond about seven significant digits it is showing the float's own
        // granularity. Documented in the class javadoc; pinned here so the behaviour is visible.
        player.rotationYaw = 0.1F;
        check("yaw is float limited", CoordsHud.build(player).contains("Yaw: 0.1000000000"));
    }

    private static void stateAndPersistence(File dir) throws Exception
    {
        File file = new File(dir, ClientConfig.FILE_NAME);

        ClientConfig.load();

        CoordsHud.resetToDefaults();
        CoordsHud.setEnabled(true);
        CoordsHud.setSize(2.5F);
        CoordsHud.setPos(-40, 90);

        check("enabled", CoordsHud.isEnabled());
        check("size applied", CoordsHud.getSize() == 2.5F);
        check("pos applied", CoordsHud.getPosX() == -40 && CoordsHud.getPosY() == 90);

        String written = read(file);
        check("section written", written.contains("[coords]"));
        check("enabled written", written.contains("enabled=true"));
        check("size written", written.contains("size=2.5"));
        check("posX written", written.contains("posX=-40"));
        check("posY written", written.contains("posY=90"));

        CoordsHud.resetToDefaults();
        ClientConfig.load();
        check("enabled survives a reload", CoordsHud.isEnabled());
        check("size survives a reload", CoordsHud.getSize() == 2.5F);
        check("pos survives a reload", CoordsHud.getPosX() == -40 && CoordsHud.getPosY() == 90);

        // Clamping, which is what keeps a stray config value from producing a broken HUD.
        CoordsHud.setSize(99.0F);
        check("size clamps to the max", CoordsHud.getSize() == CoordsHud.getMaxSize());
        CoordsHud.setSize(0.01F);
        check("size clamps to the min", CoordsHud.getSize() == CoordsHud.getMinSize());
        CoordsHud.setSize(Float.NaN);
        check("NaN size falls back to 1", CoordsHud.getSize() == 1.0F);

        CoordsHud.reset();
        check("reset turns it off", !CoordsHud.isEnabled());
        check("reset restores the size", CoordsHud.getSize() == 1.0F);
        check("reset restores the position", CoordsHud.getPosX() == 4 && CoordsHud.getPosY() == 14);

        // Unknown values on disk fall back to defaults rather than sticking.
        write(file, "[coords]\nenabled=true\nsize=banana\nposX=nonsense\n");
        ClientConfig.load();
        check("unknown size falls back", CoordsHud.getSize() == 1.0F);
        check("unknown posX falls back", CoordsHud.getPosX() == 4);
        check("unknown value does not poison the rest of the section", CoordsHud.isEnabled());
    }

    private static void renderGuards() throws Exception
    {
        CoordsHud.setEnabled(false);
        near("render while off does not touch GL", renderSafely(), "clean");

        CoordsHud.setEnabled(true);
        near("render with no player does not touch GL", renderSafely(), "clean");
        check("still enabled after a no-player render", CoordsHud.isEnabled());
    }

    /** Calls render() and reports whether it returned without throwing. */
    private static String renderSafely()
    {
        try
        {
            CoordsHud.render(Minecraft.getMinecraft(), null, 1.0F);
            return "clean";
        }
        catch (Throwable thrown)
        {
            return thrown.getClass().getName();
        }
    }

    /**
     * Same trap as the other master switches: isMasterOn fell through to FreeLook for a section
     * it did not know, so the row would display and save the wrong mod's state.
     */
    private static void tableRows() throws Exception
    {
        ClientConfig.load();
        CoordsHud.resetToDefaults();
        FreeLook.setEnabled(false);
        check("row reads false when both are off", "false".equals(row("enabled").get()));

        FreeLook.setEnabled(true);
        check("row does not follow free look", "false".equals(row("enabled").get()));

        FreeLook.setEnabled(false);
        CoordsHud.setEnabled(true);
        check("row follows the HUD", "true".equals(row("enabled").get()));

        row("enabled").set("false");
        check("row setter turns the HUD off", !CoordsHud.isEnabled());
        check("row setter leaves free look alone", !FreeLook.isEnabled());

        // The three sub-settings must grey out with the master, or the GUI lets you edit a HUD
        // that is switched off.
        check("size is gated on the master", !row("size").isGatedOff());
        CoordsHud.setEnabled(true);
        check("size is live while on", !row("size").isGatedOff());
        check("posX is live while on", !row("posX").isGatedOff());
        check("posY is live while on", !row("posY").isGatedOff());

        // And they round trip through their own setters.
        row("size").set("1.5");
        check("row setter writes the size", CoordsHud.getSize() == 1.5F);
        row("posX").set("-12");
        check("row setter writes posX", CoordsHud.getPosX() == -12);

        FreeLook.setEnabled(false);
        CoordsHud.reset();
    }

    // --- helpers -----------------------------------------------------------------

    private static ClientConfig.Setting row(String key)
    {
        for (ClientConfig.Setting setting : ClientConfig.settings())
        {
            if ("coords".equals(setting.getSection()) && key.equals(setting.getKey()))
            {
                return setting;
            }
        }

        throw new IllegalArgumentException("no coords." + key + " row in the settings table");
    }

    /** An entity with nothing initialised; only the public transform fields are ever read. */
    private static EntityPlayerSP newPlayer() throws Exception
    {
        return (EntityPlayerSP)allocate(EntityPlayerSP.class);
    }

    private static Object allocate(Class<?> type) throws Exception
    {
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);
        return allocate.invoke(unsafe, type);
    }

    private static File scratch() throws Exception
    {
        File dir = new File("coords-scratch");

        if (!dir.exists() && !dir.mkdirs())
        {
            throw new IllegalStateException("could not create " + dir);
        }

        return dir;
    }

    private static Object install(File dir) throws Exception
    {
        Minecraft mc = (Minecraft)allocate(Minecraft.class);

        // Final, but reflection can still write a non-static final field. This is what keeps the
        // config writes in the scratch directory.
        Field dirField = Minecraft.class.getDeclaredField("mcDataDir");
        dirField.setAccessible(true);
        dirField.set(mc, dir);

        // No player and no world, which is the state render() has to survive.
        mc.gameSettings = new net.minecraft.client.settings.GameSettings();

        Field singleton = Minecraft.class.getDeclaredField("theMinecraft");
        singleton.setAccessible(true);
        Object before = singleton.get(null);
        singleton.set(null, mc);
        return before;
    }

    private static void restoreSingleton(Object previous) throws Exception
    {
        Field singleton = Minecraft.class.getDeclaredField("theMinecraft");
        singleton.setAccessible(true);
        singleton.set(null, previous);
    }

    private static void write(File file, String contents) throws Exception
    {
        java.io.PrintWriter writer = new java.io.PrintWriter(file, "UTF-8");
        writer.print(contents);
        writer.close();
    }

    private static String read(File file) throws Exception
    {
        if (!file.exists())
        {
            return "";
        }

        java.io.BufferedReader reader = new java.io.BufferedReader(
            new java.io.InputStreamReader(new java.io.FileInputStream(file), "UTF-8"));
        StringBuilder builder = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null)
        {
            builder.append(line).append('\n');
        }

        reader.close();
        return builder.toString();
    }

    private static void restore(File file, boolean hadFile, String contents) throws Exception
    {
        if (hadFile)
        {
            write(file, contents);
        }
        else if (file.exists())
        {
            file.delete();
        }
    }

    private static void clear(File dir)
    {
        File[] children = dir.listFiles();

        if (children != null)
        {
            for (int i = 0; i < children.length; ++i)
            {
                children[i].delete();
            }
        }

        dir.delete();
    }

    private static void check(String what, boolean ok)
    {
        ++checks;

        if (!ok)
        {
            ++failures;
            System.out.println("  FAIL  " + what);
        }
    }

    private static void eq(String what, String actual, String expected)
    {
        ++checks;

        if (!expected.equals(actual))
        {
            ++failures;
            System.out.println("  FAIL  " + what + "\n          expected [" + expected + "]\n          actual   [" + actual + "]");
        }
    }

    private static void near(String what, float actual, float expected)
    {
        ++checks;

        if (actual != expected)
        {
            ++failures;
            System.out.println("  FAIL  " + what + " (expected " + expected + ", got " + actual + ")");
        }
    }

    private static void near(String what, String actual, String expected)
    {
        ++checks;

        if (!expected.equals(actual))
        {
            ++failures;
            System.out.println("  FAIL  " + what + " (expected " + expected + ", got " + actual + ")");
        }
    }
}

