19:             Arrays.<ClientCommand>asList(new FovCommand(), new BobCommand(), new SprintCommand(), new FpsCommand(),
20:                 new NhkCommand(), new AnimationsCommand(), new FreeLookCommand(), new ReachCircleCommand(), new CoordsCommand(), new ConfigCommand()));
