26:      *
27:      * @return true if a command handled it and the message must not be sent to the server
28:      */
29:     public static boolean handle(Minecraft mc, String message)
30:     {
31:         if (mc == null || mc.thePlayer == null || mc.ingameGUI == null)
32:         {
33:             return false;
34:         }
35: 
36:         if (message == null || message.length() < 2 || message.charAt(0) != '/')
37:         {
38:             return false;
39:         }
40: 
41:         // "//foo" is the vanilla way to send a literal slash, not a command.
42:         if (message.charAt(1) == '/')
43:         {
44:             return false;
45:         }
46: 
47:         String[] parts = message.substring(1).trim().split("\\s+");
48: 
49:         if (parts.length == 0 || parts[0].isEmpty())
50:         {
51:             return false;
52:         }
53: 
54:         for (ClientCommand command : COMMANDS)
55:         {
56:             if (matches(command, parts[0]))
57:             {
58:                 return command.execute(mc, Arrays.copyOfRange(parts, 1, parts.length));
59:             }
60:         }
61: 
62:         return false;
63:     }
64: 
