/**
 * Headless checks for {@link LookVector} and the commit it drives, {@link FreeLook#commitTo}.
 *
 * <p>The property that matters is that committing does not move the view. Every consumer of the
 * look vector adds the free look offset on top of an interpolation of the body's current and
 * previous rotation, so the harness recomputes that interpolation before and after a commit and
 * requires the two to agree to within a whole number of turns. A missing shift on any one of the
 * six fields shows up as a visible snap, which is the bug this is here to catch.</p>
 *
 * <p>Statics are snapshotted and restored around every scenario, since zeroing a field the test is
 * not exercising would destroy its initialiser for the scenarios that follow.</p>
 */
public final class LookVectorTest
{
    private static int checks;
    private static int failures;

    /** Interpolation factors the camera and the look vector are checked at. */
    private static final float[] TICKS = {0.0F, 0.25F, 0.5F, 0.75F, 1.0F};

    public static void main(String[] args) throws Exception
    {
        File file = ClientConfig.getConfigFile();
        boolean hadFile = file.exists();
        String before = hadFile ? read(file) : null;

        try
        {
            viewDoesNotMove();
            offsetCleared();
            lastEngagedRecorded();
            holdModeFallback();
            lastClearedByDisabling();
            lastClearedByReset();
            lastClearedByViewChange();
            pitchClampedNotOvershot();
            nothingToCommit();
            nullPlayer();
            modAvailability();
            configRoundTrip();
        }
        finally
        {
            restore(file, hadFile, before);
        }

        System.out.println(failures == 0
            ? "PASS  " + checks + " checks"
            : "FAIL  " + failures + " of " + checks + " checks");

        if (failures != 0)
        {
            System.exit(1);
        }
    }

    // --- scenarios ---------------------------------------------------------------

    /**
     * The whole point of the commit: the view the player is looking along is unchanged, and the
     * body has simply arrived at it. Recomputed from the same formulas the camera and
     * {@code getLook} use.
     */
    private static void viewDoesNotMove() throws Exception
    {
        State saved = State.capture();

        try
        {
            EntityPlayerSP player = newPlayer();
            player.rotationYaw = 41.0F;
            player.prevRotationYaw = 30.0F;
            player.rotationPitch = 12.0F;
            player.prevRotationPitch = 4.0F;
            player.rotationYawHead = 55.0F;
            player.prevRotationYawHead = 44.0F;

            begin();
            FreeLook.step(100.0F, -60.0F, true);

            float offYaw = FreeLook.getYaw();
            float offPitch = FreeLook.getPitch();

            check("commit: engaged offset is banked", offYaw != 0.0F || offPitch != 0.0F);

            // What the game would have shown this frame, before the commit.
            float[] before = effective(player, offYaw, offPitch);

            check("commit: reports success", FreeLook.commitTo(player));

            float[] after = effective(player, 0.0F, 0.0F);

            String[] names = {"camera yaw", "camera pitch", "look yaw", "look pitch"};

            for (int i = 0; i < TICKS.length; ++i)
            {
                for (int n = 0; n < names.length; ++n)
                {
                    near("commit: " + names[n] + " unchanged at t=" + TICKS[i],
                        wrap(after[n][i] - before[n][i]), 0.0F, 0.0001F);
                }
            }

            // And the body really did move, otherwise the test above would pass trivially.
            check("commit: body yaw moved", Math.abs(player.rotationYaw - wrap(41.0F + offYaw)) < 0.0001F);
            check("commit: body pitch moved", Math.abs(player.rotationPitch - (12.0F + offPitch)) < 0.0001F);
            check("commit: head yaw moved with the body",
                Math.abs(player.rotationYawHead - wrap(55.0F + offYaw)) < 0.0001F);
        }
        finally
        {
            saved.restore();
        }
    }

    /** Committing consumes the offset, so it cannot be applied twice. */
    private static void offsetCleared() throws Exception
    {
        State saved = State.capture();

        try
        {
            EntityPlayerSP player = newPlayer();
            begin();
            FreeLook.step(100.0F, 100.0F, true);
            FreeLook.commitTo(player);

            near("commit: live yaw consumed", FreeLook.getYaw(), 0.0F, 0.0F);
            near("commit: live pitch consumed", FreeLook.getPitch(), 0.0F, 0.0F);
            check("commit: nothing left pending", !FreeLook.hasOffset());
            near("commit: pending yaw reads zero", FreeLook.getPendingYaw(), 0.0F, 0.0F);
            near("commit: pending pitch reads zero", FreeLook.getPendingPitch(), 0.0F, 0.0F);
            check("commit: no longer active", !FreeLook.isActive());
        }
        finally
        {
            saved.restore();
        }
    }

    /** Every engaged frame records where the camera was pointing. */
    private static void lastEngagedRecorded() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.step(100.0F, 40.0F, true);
            FreeLook.step(50.0F, 20.0F, true);

            near("last: tracks the live offset while engaged",
                field("lastYaw").getFloat(null), FreeLook.getYaw(), 0.0F);
            near("last: pitch too",
                field("lastPitch").getFloat(null), FreeLook.getPitch(), 0.0F);
        }
        finally
        {
            saved.restore();
        }
    }

    /**
     * Hold mode eases the live offset away as soon as the key comes up, with a 90ms time
     * constant, so a chat command can never beat it. The last engaged offset is what the commit
     * falls back on.
     */
    private static void holdModeFallback() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.step(100.0F, 100.0F, true);
            float engagedYaw = FreeLook.getYaw();
            float engagedPitch = FreeLook.getPitch();

            // Release, then let the easing run past the epsilon so the live offset is gone.
            FreeLook.step(0.0F, 0.0F, false);
            field("yaw").set(null, 0.0F);
            field("pitch").set(null, 0.0F);

            check("fallback: live offset gone after easing",
                FreeLook.getYaw() == 0.0F && FreeLook.getPitch() == 0.0F);
            check("fallback: still something to apply", FreeLook.hasOffset());
            near("fallback: falls back to the engaged yaw", FreeLook.getPendingYaw(), engagedYaw, 0.0F);
            near("fallback: falls back to the engaged pitch", FreeLook.getPendingPitch(), engagedPitch, 0.0F);

            EntityPlayerSP player = newPlayer();
            player.rotationYaw = 0.0F;
            player.prevRotationYaw = 0.0F;
            player.rotationPitch = 0.0F;
            player.prevRotationPitch = 0.0F;
            player.rotationYawHead = 0.0F;
            player.prevRotationYawHead = 0.0F;

            float[] before = effective(player, engagedYaw, engagedPitch);
            check("fallback: commit succeeds on the remembered offset", FreeLook.commitTo(player));
            float[] after = effective(player, 0.0F, 0.0F);

            for (int i = 0; i < TICKS.length; ++i)
            {
                near("fallback: camera yaw unchanged at t=" + TICKS[i],
                    wrap(after[0][i] - before[0][i]), 0.0F, 0.0001F);
                near("fallback: camera pitch unchanged at t=" + TICKS[i],
                    wrap(after[1][i] - before[1][i]), 0.0F, 0.0001F);
            }
        }
        finally
        {
            saved.restore();
        }
    }

    /** Disabling free look means the player is no longer pointing that way, so it is forgotten. */
    private static void lastClearedByDisabling() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.step(100.0F, 100.0F, true);
            check("disable: pending before", FreeLook.hasOffset());
            FreeLook.setEnabled(false);
            check("disable: pending dropped", !FreeLook.hasOffset());
        }
        finally
        {
            saved.restore();
        }
    }

    /** So does a reset, which also hands the camera back. */
    private static void lastClearedByReset() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            FreeLook.step(100.0F, 100.0F, true);
            FreeLook.resetToDefaults();
            check("reset: pending dropped", !FreeLook.hasOffset());
        }
        finally
        {
            saved.restore();
        }
    }

    /**
     * And so does switching to a view free look may not use, since the player left that view
     * with the camera still pointing somewhere the body was not.
     */
    private static void lastClearedByViewChange() throws Exception
    {
        State saved = State.capture();
        Field singleton = fieldOf(Minecraft.class, "theMinecraft");
        Object before = singleton.get(null);

        try
        {
            Minecraft mc = newFakeMinecraft();
            singleton.set(null, mc);
            mc.gameSettings.thirdPersonView = 1;

            begin();
            FreeLook.step(100.0F, 100.0F, true);
            check("view: pending before", FreeLook.hasOffset());

            // Moving the body into first person is what actually trips the drop.
            FreeLook.setView(FreeLook.View.FIRST);
            check("view: pending dropped when the offset is", !FreeLook.hasOffset());
        }
        finally
        {
            singleton.set(null, before);
            saved.restore();
        }
    }

    /**
     * A pitch offset can push the body past straight up or down, which Minecraft does not allow.
     * Only the part that fits is committed: shifting the two pitch fields by different amounts
     * would be the one way to make the view jump, so whatever does not fit is dropped instead.
     */
    private static void pitchClampedNotOvershot() throws Exception
    {
        State saved = State.capture();

        try
        {
            EntityPlayerSP player = newPlayer();
            player.rotationYaw = 0.0F;
            player.prevRotationYaw = 0.0F;
            player.rotationYawHead = 0.0F;
            player.prevRotationYawHead = 0.0F;
            player.rotationPitch = 80.0F;
            player.prevRotationPitch = 80.0F;

            begin();
            // +50 degrees of pitch offset on a body already at 80: only 10 of it can be used.
            FreeLook.step(0.0F, -333.3F, true);

            float offPitch = FreeLook.getPitch();
            check("clamp: offset really does overflow", offPitch > 10.0F);

            float[] before = effective(player, 0.0F, offPitch);
            FreeLook.commitTo(player);
            float[] after = effective(player, 0.0F, 0.0F);

            near("clamp: body stops at straight down", player.rotationPitch, 90.0F, 0.0001F);

            for (int i = 0; i < TICKS.length; ++i)
            {
                near("clamp: camera pitch unchanged at t=" + TICKS[i],
                    wrap(after[1][i] - before[1][i]), 0.0F, 0.0001F);
            }

            check("clamp: the leftover offset is dropped, not banked", !FreeLook.hasOffset());
        }
        finally
        {
            saved.restore();
        }
    }

    /** With nothing banked the commit refuses, and must not touch the body on the way out. */
    private static void nothingToCommit() throws Exception
    {
        State saved = State.capture();

        try
        {
            EntityPlayerSP player = newPlayer();
            player.rotationYaw = 17.0F;
            player.prevRotationYaw = 16.0F;
            player.rotationPitch = 3.0F;
            player.prevRotationPitch = 2.0F;
            player.rotationYawHead = 19.0F;
            player.prevRotationYawHead = 18.0F;

            begin();
            check("empty: no offset", !FreeLook.hasOffset());
            check("empty: commit refuses", !FreeLook.commitTo(player));
            check("empty: body untouched yaw", player.rotationYaw == 17.0F && player.prevRotationYaw == 16.0F);
            check("empty: body untouched pitch", player.rotationPitch == 3.0F && player.prevRotationPitch == 2.0F);
            check("empty: body untouched head",
                player.rotationYawHead == 19.0F && player.prevRotationYawHead == 18.0F);
        }
        finally
        {
            saved.restore();
        }
    }

    private static void nullPlayer() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            check("null: refuses a null body", !FreeLook.commitTo(null));
        }
        finally
        {
            saved.restore();
        }
    }

    /** Every refusal has to be distinguishable, so the command can say what to do about it. */
    private static void modAvailability() throws Exception
    {
        State saved = State.capture();
        Field singleton = fieldOf(Minecraft.class, "theMinecraft");
        Object before = singleton.get(null);

        try
        {
            Minecraft mc = newFakeMinecraft();
            singleton.set(null, mc);

            begin();
            LookVector.resetToDefaults();
            mc.thePlayer = null;

            check("mod: on by default", LookVector.isEnabled());
            check("mod: no player is reported as such",
                LookVector.apply(mc) == LookVector.Availability.NO_PLAYER);
            check("mod: nothing banked is reported as such",
                LookVector.apply(null) == LookVector.Availability.NO_PLAYER);

            EntityPlayerSP player = newPlayer();
            mc.thePlayer = player;

            check("mod: nothing banked", LookVector.apply(mc) == LookVector.Availability.NOTHING_BANKED);

            FreeLook.setEnabled(false);
            FreeLook.step(100.0F, 100.0F, true);
            check("mod: free look off is reported as such",
                LookVector.apply(mc) == LookVector.Availability.FREE_LOOK_OFF);
            FreeLook.setEnabled(true);

            LookVector.setEnabled(false);
            check("mod: disabled is reported as such",
                LookVector.apply(mc) == LookVector.Availability.DISABLED);
            LookVector.setEnabled(true);

            check("mod: ready", LookVector.apply(mc) == LookVector.OK);
            check("mod: committing turns the body", player.rotationYaw != 0.0F);
            check("mod: nothing left afterwards",
                LookVector.apply(mc) == LookVector.Availability.NOTHING_BANKED);
        }
        finally
        {
            singleton.set(null, before);
            saved.restore();
        }
    }

    /** The switch has to survive a restart, and default to on. */
    private static void configRoundTrip() throws Exception
    {
        State saved = State.capture();

        try
        {
            begin();
            LookVector.resetToDefaults();
            check("config: written as on by default",
                read(ClientConfig.getConfigFile()).contains("enabled=true"));

            LookVector.setEnabled(false);
            check("config: writes off", read(ClientConfig.getConfigFile()).contains("enabled=false"));

            ClientConfig.load();
            check("config: off survives a reload", !LookVector.isEnabled());

            ClientConfig.resetAll();
            check("config: reset all restores the default", LookVector.isEnabled());
        }
        finally
        {
            saved.restore();
        }
    }

    // --- helpers -----------------------------------------------------------------

    /**
     * The four rotation bases the game reads, each sampled at every interpolation factor.
     *
     * <p>Index 0 and 1 are the camera's yaw and pitch, which are built from
     * {@code rotationYaw} and {@code rotationPitch}. Index 2 and 3 are the look vector's, which
     * {@code EntityLivingBase.getLook} builds from {@code rotationYawHead} and
     * {@code rotationPitch} instead - which is exactly why the commit has to move head yaw too.</p>
     */
    private static float[][] effective(EntityPlayerSP player, float offYaw, float offPitch)
    {
        return new float[][] {
            base(player.prevRotationYaw, player.rotationYaw, offYaw),
            base(player.prevRotationPitch, player.rotationPitch, offPitch),
            base(player.prevRotationYawHead, player.rotationYawHead, offYaw),
            base(player.prevRotationPitch, player.rotationPitch, offPitch)
        };
    }

    private static float[] base(float prev, float current, float offset)
    {
        float[] out = new float[TICKS.length];

        for (int i = 0; i < TICKS.length; ++i)
        {
            out[i] = prev + (current - prev) * TICKS[i] + offset;
        }

        return out;
    }

    /** Keeps a whole number of turns from reading as a difference, exactly as the game's own yaw maths does. */
    private static float wrap(float value)
    {
        value %= 360.0F;

        if (value >= 180.0F)
        {
            value -= 360.0F;
        }
        else if (value < -180.0F)
        {
            value += 360.0F;
        }

        return value;
    }

    private static void begin() throws Exception
    {
        Field mode = field("mode");
        Field view = field("view");

        mode.set(null, FreeLook.Mode.HOLD);
        view.set(null, FreeLook.View.BOTH);
        field("enabled").set(null, Boolean.TRUE);
        field("yaw").set(null, 0.0F);
        field("pitch").set(null, 0.0F);
        field("lastYaw").set(null, 0.0F);
        field("lastPitch").set(null, 0.0F);
        field("active").set(null, Boolean.FALSE);
        field("latched").set(null, Boolean.FALSE);
        field("keyWasDown").set(null, Boolean.FALSE);
        field("lastMs").set(null, 0L);
        field("autoF5").set(null, Boolean.FALSE);
        field("autoF5Held").set(null, Boolean.FALSE);
    }

    /** Restores the private statics, so scenarios cannot leak into each other. */
    private static final class State
    {
        private final Object[] values = new Object[FIELDS.length + 2];
        private final Field mode;
        private final Field view;

        private State() throws Exception
        {
            this.mode = field("mode");
            this.view = field("view");
        }

        static State capture() throws Exception
        {
            State state = new State();

            for (int i = 0; i < FIELDS.length; ++i)
            {
                state.values[i] = field(FIELDS[i]).get(null);
            }

            state.values[FIELDS.length] = state.mode.get(null);
            state.values[FIELDS.length + 1] = state.view.get(null);
            return state;
        }

        void restore() throws Exception
        {
            for (int i = 0; i < FIELDS.length; ++i)
            {
                field(FIELDS[i]).set(null, this.values[i]);
            }

            this.mode.set(null, this.values[FIELDS.length]);
            this.view.set(null, this.values[FIELDS.length + 1]);
        }
    }

    private static final String[] FIELDS = {"enabled", "yaw", "pitch", "lastYaw", "lastPitch", "active",
        "latched", "keyWasDown", "lastMs", "autoF5", "autoF5Held"};

    private static Field field(String name) throws Exception
    {
        return fieldOf(FreeLook.class, name);
    }

    private static Field fieldOf(Class<?> owner, String name) throws Exception
    {
        Field f = owner.getDeclaredField(name);
        f.setAccessible(true);
        return f;
    }

    /** A player shell holding nothing but rotation fields, none of which are initialised. */
    private static EntityPlayerSP newPlayer() throws Exception
    {
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);

        return (EntityPlayerSP)allocate.invoke(unsafe, EntityPlayerSP.class);
    }

    private static Minecraft newFakeMinecraft() throws Exception
    {
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);

        return (Minecraft)allocate.invoke(unsafe, Minecraft.class);
    }

    // --- plumbing ----------------------------------------------------------------

    private static String read(File file) throws Exception
    {
        if (!file.exists())
        {
            return "";
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), "UTF-8"));
        StringBuilder text = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null)
        {
            text.append(line).append('\n');
        }

        reader.close();
        return text.toString();
    }

    private static void restore(File file, boolean hadFile, String before) throws Exception
    {
        if (hadFile)
        {
            PrintWriter writer = new PrintWriter(file, "UTF-8");
            writer.print(before);
            writer.close();
        }
        else if (file.exists())
        {
            file.delete();
        }
    }

    private static void check(String what, boolean ok)
    {
        ++checks;

        if (!ok)
        {
            ++failures;
            System.out.println("  FAIL  " + what);
        }
    }

    private static void near(String what, float actual, float expected, float tolerance)
    {
        ++checks;

        if (Float.isNaN(actual) || Math.abs(actual - expected) > tolerance)
        {
            ++failures;
            System.out.println("  FAIL  " + what + " (expected " + expected + ", got " + actual + ")");
        }
    }

    private LookVectorTest() {}
}

