     * A pitch offset can push the body past straight up or down, which Minecraft does not allow.
     * Only the part that fits is committed: shifting the two pitch fields by different amounts
     * would be the one way to make the view jump, so whatever does not fit is dropped instead.
     */
    private static void pitchClampedNotOvershot() throws Exception
    {
        State saved = State.capture();

        try
        {
            EntityPlayerSP player = newPlayer();
            player.rotationYaw = 0.0F;
            player.prevRotationYaw = 0.0F;
            player.rotationYawHead = 0.0F;
            player.prevRotationYawHead = 0.0F;
            player.rotationPitch = 80.0F;
            player.prevRotationPitch = 80.0F;

            begin();
            // +50 degrees of pitch offset on a body already at 80: only 10 of it can be used.
            FreeLook.step(0.0F, -333.3F, true);

            float offPitch = FreeLook.getPitch();
            check("clamp: offset really does overflow", offPitch > 10.0F);

            float[][] before = effective(player, 0.0F, offPitch);
            FreeLook.commitTo(player);
            float[][] after = effective(player, 0.0F, 0.0F);

            near("clamp: body stops at straight down", player.rotationPitch, 90.0F, 0.0001F);

            for (int i = 0; i < TICKS.length; ++i)
            {
                near("clamp: camera pitch unchanged at t=" + TICKS[i],
                    wrap(after[1][i] - before[1][i]), 0.0F, 0.0001F);
            }

            check("clamp: the leftover offset is dropped, not banked", !FreeLook.hasOffset());
        }
        finally
        {
            saved.restore();
        }
    }

