package net.minecraft.client.commands;

import java.util.Arrays;
import java.util.List;
import net.minecraft.client.Minecraft;
import net.minecraft.util.ChatComponentText;
import net.minecraft.util.EnumChatFormatting;

/**
 * /tickspeed [n] [on|off] [reset]
 *
 * <p>Raises the client's own tick rate, so keys, the mouse and the GUI are polled more often and
 * register sooner.</p>
 *
 * <p>The world deliberately does not come along. Everything to do with physics, movement packets,
 * sound timing and particle lifetimes is held to the 20 per second the server runs at, so the
 * client cannot outrun it and get pulled back. That is what this does instead of the obvious
 * version, which is just to raise the game's tick rate and let the player move at double speed
 * into a wall.</p>
 *
 * <p>Because the world still ticks at 20, the gain is input latency and how often anything
 * reacting to input gets a chance to run - not a faster game. Frame rate drops as the rate rises,
 * so the useful ceiling is whatever the machine can frame.</p>
 *
 * <p>Settings are stored in {@value ClientConfig#FILE_NAME} in the game directory and rewritten on
 * every change.</p>
 */
public class TickSpeedCommand implements ClientCommand
{
    public String getName()
    {
        return "tickspeed";
    }

    public List<String> getAliases()
    {
        return Arrays.asList("tickrate", "tps");
    }

    public String getUsage()
    {
        return "/tickspeed | /tickspeed <"
            + (int)TickSpeed.MIN_TICKS + "-" + (int)TickSpeed.MAX_TICKS + "> | /tickspeed on|off | /tickspeed reset";
    }

    public boolean execute(Minecraft mc, String[] args)
    {
        if (args.length == 0)
        {
            status(mc);
            return true;
        }

        String sub = args[0].toLowerCase();

        if (sub.equals("help"))
        {
            reply(mc, getUsage(), EnumChatFormatting.AQUA);
            return true;
        }

        if (sub.equals("reset"))
        {
            if (args.length > 1)
            {
                reply(mc, "Usage: /tickspeed reset", EnumChatFormatting.RED);
                return true;
            }

            TickSpeed.reset();
            reply(mc, "Tick speed reset to defaults. " + TickSpeed.getConfigFile().getName() + " rewritten.",
                EnumChatFormatting.GREEN);
            return true;
        }

        if (sub.equals("on") || sub.equals("off"))
        {
            if (args.length > 1)
            {
                reply(mc, "Usage: /tickspeed on|off", EnumChatFormatting.RED);
                return true;
            }

            TickSpeed.setEnabled(sub.equals("on"));
            reply(mc, "Tick speed " + (TickSpeed.isEnabled() ? "enabled" : "disabled, back to the game's own 20.")
                + TickSpeed.unreachable(mc.getFPS()),
                TickSpeed.isEnabled() ? EnumChatFormatting.GREEN : EnumChatFormatting.YELLOW);
            return true;
        }

        Float value = parseRate(sub);

        if (value == null)
        {
            reply(mc, "Unknown option \"" + args[0] + "\". Usage: " + getUsage(), EnumChatFormatting.RED);
            return true;
        }

        // Setting a rate implies wanting it, the same way other mods treat a subcommand that only
        // makes sense when the mod is on.
        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(value);

        float got = TickSpeed.getTicks();

        reply(mc, "Tick rate " + TickSpeed.trim(got)
            + (TickSpeed.trim(got).equals(sub) ? "" : " (clamped from " + sub + ")")
            + ". World stays at 20."
            + TickSpeed.unreachable(mc.getFPS()),
            got > TickSpeed.BASE_TICKS ? EnumChatFormatting.GREEN : EnumChatFormatting.AQUA);
        return true;
    }

    /**
     * Reads a tick rate, rejecting anything that is not a number so a typo lands on the usage
     * line rather than being quietly clamped to a limit.
     */
    private static Float parseRate(String text)
    {
        try
        {
            float value = Float.parseFloat(text);
            return Float.isNaN(value) ? null : Float.valueOf(value);
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }

    private void status(Minecraft mc)
    {
        boolean on = TickSpeed.isEnabled();
        float rate = TickSpeed.getTicks();

        reply(mc, "Tick speed " + (on ? "on at " + TickSpeed.trim(rate) : "off, the game's own 20")
            + "  (" + TickSpeed.getConfigFile().getName() + ")",
            on ? EnumChatFormatting.GREEN : EnumChatFormatting.YELLOW);

        if (on)
        {
            int fps = mc.getFPS();
            reply(mc, "  " + fps + " fps, so the loop can reach " + TickSpeed.trim(TickSpeed.reachable(fps))
                + " ticks per second at most.", EnumChatFormatting.GRAY);
        }

        reply(mc, "  Physics, movement packets, sound and particles stay at 20 either way.", EnumChatFormatting.GRAY);
    }

    private void reply(Minecraft mc, String text, EnumChatFormatting colour)
    {
        mc.ingameGUI.getChatGUI().printChatMessage(new ChatComponentText(colour + text));
    }
}

package net.minecraft.client.commands;

import java.util.Arrays;
import java.util.List;
import net.minecraft.client.Minecraft;
import net.minecraft.util.ChatComponentText;
import net.minecraft.util.EnumChatFormatting;

/**
 * /jumpdelay [n] [on|off] [reset]
 *
 * <p>Puts a gap between jumps while the jump key is held, so holding it hops at a set rate instead
 * of every time the player touches ground. Zero is what this build has always done.</p>
 *
 * <p>This is the gap vanilla already had and then threw away. {@code EntityLivingBase} keeps a
 * {@code jumpTicks} field that is decremented a tick at a time and gates the jump on it reaching
 * zero, but vanilla zeroes it the moment it jumps, so the gate never bites. This reinstates it
 * behind a setting. One difference from vanilla: the gap runs down whatever the key is doing, so
 * letting go mid-gap and pressing again does not hand back a free instant jump.</p>
 *
 * <p>In ticks, so a raised tick speed shortens it in real time. The countdown is in world ticks,
 * and the world is held to 20 by {@link TickSpeed}, so the two settings cannot disagree.</p>
 *
 * <p>Settings are stored in {@value ClientConfig#FILE_NAME} in the game directory and rewritten on
 * every change.</p>
 */
public class JumpDelayCommand implements ClientCommand
{
    public String getName()
    {
        return "jumpdelay";
    }

    public List<String> getAliases()
    {
        return Arrays.asList("hopdelay", "jdelay");
    }

    public String getUsage()
    {
        return "/jumpdelay | /jumpdelay <" + JumpDelay.MIN_DELAY + "-" + JumpDelay.MAX_DELAY
            + "> | /jumpdelay on|off | /jumpdelay reset";
    }

    public boolean execute(Minecraft mc, String[] args)
    {
        if (args.length == 0)
        {
            status(mc);
            return true;
        }

        String sub = args[0].toLowerCase();

        if (sub.equals("help"))
        {
            reply(mc, getUsage(), EnumChatFormatting.AQUA);
            return true;
        }

        if (sub.equals("reset"))
        {
            if (args.length > 1)
            {
                reply(mc, "Usage: /jumpdelay reset", EnumChatFormatting.RED);
                return true;
            }

            JumpDelay.reset();
            reply(mc, "Jump delay reset to defaults. " + JumpDelay.getConfigFile().getName() + " rewritten.",
                EnumChatFormatting.GREEN);
            return true;
        }

        if (sub.equals("on") || sub.equals("off"))
        {
            if (args.length > 1)
            {
                reply(mc, "Usage: /jumpdelay on|off", EnumChatFormatting.RED);
                return true;
            }

            JumpDelay.setEnabled(sub.equals("on"));
            reply(mc, "Jump delay " + (JumpDelay.isEnabled() ? "enabled" : "disabled")
                + ". Hold jump and you hop every " + JumpDelay.getDelay() + " ticks.",
                JumpDelay.isEnabled() ? EnumChatFormatting.GREEN : EnumChatFormatting.YELLOW);
            return true;
        }

        Integer value = parseDelay(sub);

        if (value == null)
        {
            reply(mc, "Unknown option \"" + args[0] + "\". Usage: " + getUsage(), EnumChatFormatting.RED);
            return true;
        }

        JumpDelay.setEnabled(true);
        JumpDelay.setDelay(value);

        int got = JumpDelay.getDelay();

        reply(mc, got == 0
                ? "No jump delay. Holding jump hops the moment you land, as before."
                : "Jump delay " + got + " tick" + (got == 1 ? "" : "s") + " ("
                    + (got * 50) + " ms). Hold jump and you hop that often."
                    + (got != value.intValue() ? " (clamped from " + value + ")" : ""),
            got == 0 ? EnumChatFormatting.YELLOW : EnumChatFormatting.GREEN);
        return true;
    }

    /**
     * Reads a tick count, rejecting anything that is not a number so a typo lands on the usage
     * line rather than being quietly clamped to zero.
     */
    private static Integer parseDelay(String text)
    {
        try
        {
            return Integer.valueOf(Integer.parseInt(text));
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }

    private void status(Minecraft mc)
    {
        boolean on = JumpDelay.isEnabled();
        int delay = JumpDelay.getDelay();

        reply(mc, "Jump delay " + (on ? "on at " + delay + " tick" + (delay == 1 ? "" : "s")
                : "off") + "  (" + JumpDelay.getConfigFile().getName() + ")",
            on ? EnumChatFormatting.GREEN : EnumChatFormatting.YELLOW);

        if (on && delay == 0)
        {
            reply(mc, "  Zero ticks, so this is doing nothing. Set one with /jumpdelay 10 for vanilla's half second.",
                EnumChatFormatting.GRAY);
        }
        else if (on)
        {
            reply(mc, "  " + (delay * 50) + " ms between jumps.", EnumChatFormatting.GRAY);
        }

        int left = JumpDelay.getCooldown();

        if (left > 0)
        {
            reply(mc, "  Waiting " + left + " tick" + (left == 1 ? "" : "s") + " before the next jump can start.",
                EnumChatFormatting.AQUA);
        }
    }

    private void reply(Minecraft mc, String text, EnumChatFormatting colour)
    {
        mc.ingameGUI.getChatGUI().printChatMessage(new ChatComponentText(colour + text));
    }
}

