package net.minecraft.client.commands;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import net.minecraft.client.Minecraft;
import net.minecraft.util.Timer;

/**
 * Headless checks for {@link TickSpeed} and {@link JumpDelay}.
 *
 * <p>Both mods exist to keep one promise while changing something else, and both promises are
 * about rates rather than values, so neither can be checked by looking at a field.
 *
 * <p>{@link TickSpeed} promises the world still runs at 20 Hz. That is checked by running tens of
 * thousands of input ticks through the gate at a spread of rates and counting what came out, so
 * an accumulator that drifts, or a whole-number divisor that lands on 21, is caught rather than
 * admired.</p>
 *
 * <p>{@link JumpDelay} promises a gap of exactly the configured number of ticks. Also a rate, so
 * also measured by simulation: jump, then run ticks until the next one comes through, and count
 * the distance. That is where an off-by-one hides, and it hid one.</p>
 *
 * <p>Statics are snapshotted and restored around every scenario, since zeroing a field the test is
 * not exercising would destroy its initialiser for the scenarios that follow.</p>
 */
public final class TickJumpTest
{
    private static int checks;
    private static int failures;

    /**
     * Input ticks simulated when checking the world rate.
     *
     * <p>Large enough that a credit lost or double-counted on any single tick shows up: at 30
     * ticks a second the gate runs once every 1.5 ticks, so a mistake of one tick in a thousand
     * is two ticks of drift over this many.</p>
     */
    private static final int LONG_RUN = 60000;

    /** Rates the world rate is checked at, chosen to hit every awkward ratio. */
    private static final float[] RATES = {20.0F, 20.5F, 21.0F, 25.0F, 30.0F, 33.3F, 40.0F,
        50.0F, 60.0F, 77.0F, 100.0F, 137.5F, 200.0F};

    public static void main(String[] args) throws Exception
    {
        File file = ClientConfig.getConfigFile();
        boolean hadFile = file.exists();
        String before = hadFile ? read(file) : null;

        try
        {
            worldRateHeldAtTwenty();
            accumulatorDoesNotDrift();
            vanillaShortCircuits();
            belowBaseIsSlowMotion();
            disabledIsVanilla();
            timerPointsAtTheRate();
            rateClamped();
            creditResetOnChange();
            reachableCeiling();
            gapIsExactlyTheDelay();
            delaySurvivesKeyUp();
            gapClearedByZeroAndByDisable();
            packetAgreesWithGate();
            defaults();
            configRoundTrip();
        }
        finally
        {
            restore(file, hadFile, before);
            deleteScratch(scratchDir());
        }

        System.out.println(failures == 0
            ? "PASS  " + checks + " checks"
            : "FAIL  " + failures + " of " + checks + " checks");

        if (failures != 0)
        {
            System.exit(1);
        }
    }

    // --- TickSpeed ---------------------------------------------------------------

    /**
     * The whole point of the mod: however fast input ticks go, the world ticks at 20 a second.
     *
     * <p>The expected count is the closest integer to {@code ticks * 20 / rate}, which is the
     * best a per-tick boolean can do. What matters is that the error never reaches even half a
     * tick per second, and that it does not grow with the length of the run.</p>
     */
    private static void worldRateHeldAtTwenty()
    {
        for (float rate : RATES)
        {
            State saved = State.capture();
            TickSpeed.setEnabled(true);
            TickSpeed.setTicks(rate);

            int world = 0;

            for (int i = 0; i < LONG_RUN; ++i)
            {
                if (TickSpeed.isWorldTick())
                {
                    ++world;
                }
            }

            double expected = (double)LONG_RUN * (double)TickSpeed.BASE_TICKS / (double)rate;
            double actualPerSecond = world * (double)rate / (double)LONG_RUN;

            near("world holds 20 Hz at " + rate + " ticks", actualPerSecond, TickSpeed.BASE_TICKS, 0.01D);
            check("world count at " + rate + " is within half a tick of ideal",
                Math.abs(world - expected) <= 0.5D);

            State.restore(saved);
        }
    }

    /**
     * The accumulator must not drift over a long run.
     *
     * <p>Checked at the two rates most likely to expose it: one that never fires the gate, where
     * credit has to accumulate over many ticks before it reaches one, and a high one where it
     * fires nearly every tick. A double that lost a sliver per tick would show here and nowhere
     * else.</p>
     */
    private static void accumulatorDoesNotDrift()
    {
        float[] rates = {37.0F, 200.0F};

        for (float rate : rates)
        {
            State saved = State.capture();
            TickSpeed.setEnabled(true);
            TickSpeed.setTicks(rate);

            int world = 0;
            int runs = 0;
            int longestGap = 0;
            int currentGap = 0;

            for (int i = 0; i < LONG_RUN; ++i)
            {
                if (TickSpeed.isWorldTick())
                {
                    ++world;
                    ++runs;

                    if (currentGap > longestGap)
                    {
                        longestGap = currentGap;
                    }

                    currentGap = 0;
                }
                else
                {
                    ++currentGap;
                }
            }

            double expected = (double)LONG_RUN * (double)TickSpeed.BASE_TICKS / (double)rate;

            near("no drift at " + rate + " ticks over " + LONG_RUN, world, expected, 1.0D);
            check("gate fires at least once at " + rate, runs > 0);
            check("gap between world ticks at " + rate + " is bounded",
                longestGap <= (int)Math.ceil(rate / (double)TickSpeed.BASE_TICKS) + 1);

            State.restore(saved);
        }
    }

    /**
     * At or below the vanilla rate the gate must be a plain pass-through.
     *
     * <p>This is the case that keeps a normal game byte-identical to vanilla, so it must not
     * consult or move the accumulator at all. Poking the gate afterwards and requiring the next
     * full second's worth to come through immediately is what would catch an accumulator left in
     * a state that owes the world a tick.</p>
     */
    private static void vanillaShortCircuits()
    {
        float[] rates = {TickSpeed.BASE_TICKS, 10.0F, 5.0F};

        for (float rate : rates)
        {
            State saved = State.capture();

            // Left owing several ticks by a fast run first, so any read of the accumulator shows.
            TickSpeed.setEnabled(true);
            TickSpeed.setTicks(200.0F);

            for (int i = 0; i < 7; ++i)
            {
                TickSpeed.isWorldTick();
            }

            TickSpeed.setTicks(rate);

            int passed = 0;

            for (int i = 0; i < 100; ++i)
            {
                if (TickSpeed.isWorldTick())
                {
                    ++passed;
                }
            }

            check("every tick is a world tick at " + rate + " ticks", passed == 100);
            near("clock is left alone at " + rate + " ticks", nearClock(), 0.0D, 0.0D);

            State.restore(saved);
        }
    }

    /**
     * Below the base rate the world runs at the input rate, which is slow motion.
     *
     * <p>Deliberate rather than an oversight: holding the world at 20 while input ticks slower
     * would leave the world ahead of the clock, and slow motion is the obvious thing a lower rate
     * is for.</p>
     */
    private static void belowBaseIsSlowMotion()
    {
        State saved = State.capture();
        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(10.0F);

        int world = 0;

        for (int i = 0; i < 100; ++i)
        {
            if (TickSpeed.isWorldTick())
            {
                ++world;
            }
        }

        check("every tick is a world tick below the base rate", world == 100);
        State.restore(saved);
    }

    /** Off is vanilla, whichever rate happens to be stored. */
    private static void disabledIsVanilla()
    {
        State saved = State.capture();
        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(200.0F);
        TickSpeed.setEnabled(false);

        int world = 0;

        for (int i = 0; i < 100; ++i)
        {
            if (TickSpeed.isWorldTick())
            {
                ++world;
            }
        }

        check("disabled lets every tick through", world == 100);

        Timer timer = new Timer(TickSpeed.BASE_TICKS);
        TickSpeed.applyTo(timer);
        near("disabled points the timer back at 20", timer.ticksPerSecond, TickSpeed.BASE_TICKS, 0.0D);

        check("a null timer is ignored", applyToNullIsQuiet());
        State.restore(saved);
    }

    /** The rate the mod asks the game loop for, for a few settings. */
    private static void timerPointsAtTheRate()
    {
        State saved = State.capture();

        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(100.0F);

        Timer timer = new Timer(TickSpeed.BASE_TICKS);
        TickSpeed.applyTo(timer);
        near("enabled points the timer at the rate", timer.ticksPerSecond, 100.0F, 0.0001F);

        // 20 is a valid choice that means "vanilla", and has to come out as 20 rather than being
        // quietly switched off, or the config would disagree with what the game is doing.
        TickSpeed.setTicks(20.0F);
        TickSpeed.applyTo(timer);
        near("a rate of 20 stays on", timer.ticksPerSecond, 20.0F, 0.0001F);

        State.restore(saved);
    }

    /** Out of range values are pulled to a bound rather than rejected or left broken. */
    private static void rateClamped()
    {
        State saved = State.capture();

        TickSpeed.setEnabled(true);

        TickSpeed.setTicks(100000.0F);
        near("a huge rate is clamped to the max", TickSpeed.getTicks(), TickSpeed.MAX_TICKS, 0.0001F);

        TickSpeed.setTicks(-40.0F);
        near("a negative rate is clamped to the min", TickSpeed.getTicks(), TickSpeed.MIN_TICKS, 0.0001F);

        TickSpeed.setTicks(0.0F);
        near("zero is clamped to the min", TickSpeed.getTicks(), TickSpeed.MIN_TICKS, 0.0001F);

        // NaN would poison every comparison below it, taking the gate with it.
        TickSpeed.setTicks(Float.NaN);
        near("NaN falls back to the base rate", TickSpeed.getTicks(), TickSpeed.BASE_TICKS, 0.0001F);

        TickSpeed.setTicks(60.0F);
        near("a good value is kept", TickSpeed.getTicks(), 60.0F, 0.0001F);

        State.restore(saved);
    }

    /**
     * Changing the rate starts a fresh average.
     *
     * <p>Without this, credit owed at the old rate is carried into the new one. Dropping from a
     * fast rate to 20 mid-run would then release a burst of world ticks, and the first second
     * after any change would not be 20 Hz.</p>
     */
    private static void creditResetOnChange()
    {
        State saved = State.capture();
        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(200.0F);

        // Run a few ticks to leave credit outstanding: at 200 the gate fires on most ticks but
        // still owes a fraction most of the time.
        for (int i = 0; i < 3; ++i)
        {
            TickSpeed.isWorldTick();
        }

        TickSpeed.setTicks(20.0F);

        int world = 0;

        for (int i = 0; i < 100; ++i)
        {
            if (TickSpeed.isWorldTick())
            {
                ++world;
            }
        }

        check("every tick follows the rate change", world == 100);

        // And the same when going the other way, where credit would otherwise carry as debt.
        TickSpeed.setTicks(20.0F);
        TickSpeed.isWorldTick();
        TickSpeed.setTicks(200.0F);

        int high = 0;

        for (int i = 0; i < 1000; ++i)
        {
            if (TickSpeed.isWorldTick())
            {
                ++high;
            }
        }

        near("1000 ticks at 200 gives 100 world ticks", high, 100.0D, 1.0D);
        State.restore(saved);
    }

    /**
     * The ceiling the game loop actually imposes.
     *
     * <p>{@code Timer} clamps elapsed ticks to ten a frame, so a rate above ten times the frame
     * rate cannot be reached however willing the machine is. The command reports this, so it had
     * better be right, and in particular must never promise more than the offered maximum.</p>
     */
    private static void reachableCeiling()
    {
        near("no frame rate means no ceiling beyond the max",
            TickSpeed.reachable(0.0F), TickSpeed.MAX_TICKS, 0.0001F);

        near("a negative frame rate is treated as unknown",
            TickSpeed.reachable(-5.0F), TickSpeed.MAX_TICKS, 0.0001F);

        near("60 fps reaches 600", TickSpeed.reachable(60.0F), 600.0F, 0.0001F);
        near("the ceiling never exceeds the max", TickSpeed.reachable(1000.0F), TickSpeed.MAX_TICKS, 0.0001F);
        near("a fractional frame rate rounds down", TickSpeed.reachable(15.9F), 150.0F, 0.0001F);

        State saved = State.capture();

        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(60.0F);
        check("a reachable rate warns about nothing", TickSpeed.unreachable(60.0F).isEmpty());

        TickSpeed.setTicks(200.0F);
        check("an unreachable rate explains itself", !TickSpeed.unreachable(15.0F).isEmpty());
        check("the explanation names the per frame cap",
            TickSpeed.unreachable(15.0F).contains(String.valueOf(TickSpeed.MAX_TICKS_PER_FRAME)));

        State.restore(saved);
    }

    // --- JumpDelay ---------------------------------------------------------------

    /**
     * A gap of N means the next jump is N ticks after this one, for every N on offer.
     *
     * <p>Simulated the way the hooks actually run: step the countdown, and if the key is down and
     * the step allowed it, jump. That is the real order, and it is why the countdown has to be
     * armed a tick short - arming the full delay gives a gap of N + 1, which is the mistake this
     * check exists to pin down.</p>
     */
    private static void gapIsExactlyTheDelay()
    {
        for (int delay = JumpDelay.MIN_DELAY; delay <= JumpDelay.MAX_DELAY; ++delay)
        {
            State saved = State.capture();
            JumpDelay.setEnabled(true);
            JumpDelay.setDelay(delay);

            int[] jumps = holdJumpForTicks(delay == 0 ? 4 : delay * 3 + 4);

            check("a delay of " + delay + " lets a first jump through", jumps[0] == 0);

            for (int i = 1; i < jumps.length; ++i)
            {
                check("a delay of " + delay + " gives a gap of " + delay + ", got " + (jumps[i] - jumps[i - 1]),
                    jumps[i] - jumps[i - 1] == delay);
            }

            State.restore(saved);
        }
    }

    /**
     * Letting go of the key and pressing again must not hand back a free instant jump.
     *
     * <p>The countdown runs whether the key is down or not, so a player who taps rather than
     * holds is subject to the same delay. This is the one deliberate departure from vanilla,
     * which zeroes its unused field the moment the key comes up, and it is the reason the
     * countdown is stepped ahead of the key rather than inside the test.</p>
     */
    private static void delaySurvivesKeyUp()
    {
        for (int delay : {1, 5, 10, 20})
        {
            State saved = State.capture();
            JumpDelay.setEnabled(true);
            JumpDelay.setDelay(delay);

            // Jump on tick 0, release for two ticks, then hold again and see when it comes.
            JumpDelay.step();
            JumpDelay.onJumped();

            int release = 2;
            int next = -1;

            for (int tick = 1; tick < 200 && next < 0; ++tick)
            {
                boolean held = tick > release;
                boolean allowed = JumpDelay.step();

                if (held && allowed)
                {
                    next = tick;
                }
            }

            check("a gap of " + delay + " survives the key being released, came at " + next,
                next == delay);

            State.restore(saved);
        }
    }

    /** Setting the delay back to zero, or switching the mod off, must not leave a jump blocked. */
    private static void gapClearedByZeroAndByDisable()
    {
        State saved = State.capture();

        JumpDelay.setEnabled(true);
        JumpDelay.setDelay(20);
        JumpDelay.step();
        JumpDelay.onJumped();
        check("a gap is pending", JumpDelay.getCooldown() > 0);

        JumpDelay.setDelay(0);
        check("setting the delay to zero clears the pending gap", JumpDelay.getCooldown() == 0);
        check("a jump goes straight through after zeroing", JumpDelay.step() && JumpDelay.allowsJump());

        JumpDelay.setDelay(20);
        JumpDelay.step();
        JumpDelay.onJumped();
        check("a gap is pending again", JumpDelay.getCooldown() > 0);

        JumpDelay.setEnabled(false);
        check("switching the mod off clears the pending gap", JumpDelay.getCooldown() == 0);
        check("a jump goes straight through once off", JumpDelay.step());

        // Off must not silently re-arm on a jump either.
        JumpDelay.onJumped();
        check("an off mod never arms a gap", JumpDelay.getCooldown() == 0);
        check("and still reports the jump as allowed", JumpDelay.allowsJump());

        State.restore(saved);
    }

    /**
     * The riding packet and the local gate must answer the same thing on the same tick.
     *
     * <p>The packet is sent from a different method to the one that steps the countdown, so it
     * reads the state without touching it. If stepping happened in both, the countdown would run
     * twice a tick and the gap would come out at half the configured length; if the packet peeked
     * wrongly, the server would be told to jump on a tick the client deliberately did not, and
     * horse and rider would separate.</p>
     */
    private static void packetAgreesWithGate()
    {
        State saved = State.capture();

        for (int delay : {0, 1, 4, 20})
        {
            JumpDelay.setEnabled(true);
            JumpDelay.setDelay(delay);
            JumpDelay.step();
            JumpDelay.onJumped();

            int disagreements = 0;

            for (int tick = 0; tick < delay * 3 + 6; ++tick)
            {
                boolean allowed = JumpDelay.step();

                if (allowed != JumpDelay.allowsJump())
                {
                    ++disagreements;
                }

                if (allowed)
                {
                    JumpDelay.onJumped();
                }
            }

            check("the packet agrees with the gate every tick at a delay of " + delay, disagreements == 0);
        }

        State.restore(saved);
    }

    // --- persistence -------------------------------------------------------------

    /** Defaults, as the config's reset paths rely on them. */
    private static void defaults()
    {
        State saved = State.capture();

        TickSpeed.resetToDefaults();
        check("tick speed defaults to off", !TickSpeed.isEnabled());
        near("tick speed defaults to the base rate", TickSpeed.getTicks(), TickSpeed.BASE_TICKS, 0.0001F);

        JumpDelay.resetToDefaults();
        check("jump delay defaults to on, inert at zero", JumpDelay.isEnabled());
        check("jump delay defaults to no gap", JumpDelay.getDelay() == JumpDelay.MIN_DELAY);
        check("and no gap is pending", JumpDelay.getCooldown() == 0);

        State.restore(saved);
    }

    /** The settings survive a write and a read, in both directions. */
    private static void configRoundTrip() throws Exception
    {
        State saved = State.capture();

        // save() is a no-op until load() has run, so the read has to be primed first.
        ClientConfig.load();

        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(137.5F);
        JumpDelay.setEnabled(false);
        JumpDelay.setDelay(7);

        TickSpeed.resetToDefaults();
        JumpDelay.resetToDefaults();

        check("tick speed came back on", TickSpeed.isEnabled());
        near("the tick rate came back", TickSpeed.getTicks(), 137.5F, 0.0001F);
        check("jump delay came back off", !JumpDelay.isEnabled());
        check("the gap came back", JumpDelay.getDelay() == 7);

        TickSpeed.reset();
        JumpDelay.reset();

        State.restore(saved);
    }

    // --- simulation --------------------------------------------------------------

    /**
     * Runs ticks with the jump key held down, and returns the tick of each jump.
     *
     * @param ticks how many ticks to simulate
     */
    private static int[] holdJumpForTicks(int ticks)
    {
        int[] found = new int[ticks];
        int count = 0;

        for (int tick = 0; tick < ticks && count < found.length; ++tick)
        {
            if (JumpDelay.step())
            {
                found[count++] = tick;
                JumpDelay.onJumped();
            }
        }

        int[] jumps = new int[count];
        System.arraycopy(found, 0, jumps, 0, count);
        return jumps;
    }

    /** Whether the mod can be pointed at nothing without throwing. */
    private static boolean applyToNullIsQuiet()
    {
        try
        {
            TickSpeed.applyTo(null);
            return true;
        }
        catch (RuntimeException e)
        {
            return false;
        }
    }

    // --- plumbing ----------------------------------------------------------------

    /**
     * Reads the accumulator directly.
     *
     * <p>Used to require that the vanilla path leaves it completely alone, which no public method
     * can show: at 20 a second the gate always returns true either way.</p>
     */
    private static double nearClock() throws Exception
    {
        Field field = Field.class.getDeclaredField("");
        return credit();
    }

    private static double credit() throws Exception
    {
        Field field = TickSpeed.class.getDeclaredField("credit");
        field.setAccessible(true);
        return field.getDouble(null);
    }

    private static File scratchDir() throws Exception
    {
        File dir = new File("tickjump-scratch");

        if (!dir.exists() && !dir.mkdirs())
        {
            throw new IllegalStateException("could not make " + dir);
        }

        return dir;
    }

    private static void deleteScratch(File dir)
    {
        File[] children = dir.listFiles();

        if (children != null)
        {
            for (File child : children)
            {
                child.delete();
            }
        }

        dir.delete();
    }

    private static String read(File file) throws Exception
    {
        if (!file.exists())
        {
            return "";
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), "UTF-8"));
        StringBuilder text = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null)
        {
            text.append(line).append('\n');
        }

        reader.close();
        return text.toString();
    }

    private static void restore(File file, boolean hadFile, String before) throws Exception
    {
        if (hadFile)
        {
            PrintWriter writer = new PrintWriter(file, "UTF-8");
            writer.print(before);
            writer.close();
        }
        else if (file.exists())
        {
            file.delete();
        }
    }

    private static void check(String what, boolean ok)
    {
        ++checks;

        if (!ok)
        {
            ++failures;
            System.out.println("  FAIL  " + what);
        }
    }

    private static void near(String what, double actual, double expected, double tolerance)
    {
        ++checks;

        if (Double.isNaN(actual) || Math.abs(actual - expected) > tolerance)
        {
            ++failures;
            System.out.println("  FAIL  " + what + " (expected " + expected + ", got " + actual + ")");
        }
    }

    private TickJumpTest() {}

    /** The statics both mods keep between calls, saved whole and put back. */
    private static final class State
    {
        private final boolean tickEnabled;
        private final float ticks;
        private final double credit;
        private final boolean jumpEnabled;
        private final int delay;
        private final int cooldown;

        private State(boolean tickEnabled, float ticks, double credit,
            boolean jumpEnabled, int delay, int cooldown)
        {
            this.tickEnabled = tickEnabled;
            this.ticks = ticks;
            this.credit = credit;
            this.jumpEnabled = jumpEnabled;
            this.delay = delay;
            this.cooldown = cooldown;
        }

        static State capture() throws Exception
        {
            return new State(TickSpeed.isEnabled(), TickSpeed.getTicks(), credit(),
                JumpDelay.isEnabled(), JumpDelay.getDelay(), JumpDelay.getCooldown());
        }

        void restore(State saved) throws Exception
        {
            // Straight field writes, so a restore cannot itself call save() and rewrite the config
            // file the run is trying to leave alone.
            write(TickSpeed.class, "enabled", Boolean.valueOf(saved.tickEnabled));
            write(TickSpeed.class, "ticks", Float.valueOf(saved.ticks));
            write(TickSpeed.class, "credit", Double.valueOf(saved.credit));
            write(JumpDelay.class, "enabled", Boolean.valueOf(saved.jumpEnabled));
            write(JumpDelay.class, "delay", Integer.valueOf(saved.delay));
            write(JumpDelay.class, "cooldown", Integer.valueOf(saved.cooldown));
        }
    }

    private static void write(Class<?> owner, String name, Object value) throws Exception
    {
        Field field = owner.getDeclaredField(name);
        field.setAccessible(true);
        field.set(null, value);
    }

    /**
     * Unused, but present so the harness compiles against the same imports the other harnesses
     * use if a future check needs them.
     */
    private static Minecraft newFakeMinecraft() throws Exception
    {
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);

        Minecraft mc = (Minecraft)allocate.invoke(unsafe, Minecraft.class);
        Field dir = Minecraft.class.getDeclaredField("mcDataDir");
        dir.setAccessible(true);
        dir.set(mc, scratchDir());
        return mc;
    }
}

