 * At or below the vanilla rate the gate must be a plain pass-through.
 *
 * <p>This is the case that keeps a normal game byte-identical to vanilla, so it must not
 * consult or move the accumulator at all. Poking the gate afterwards and requiring the next
 * full second's worth to come through immediately is what would catch an accumulator left in
 * a state that owes the world a tick.</p>
 */
private static void vanillaShortCircuits() throws Exception
{
    float[] rates = {TickSpeed.BASE_TICKS, 10.0F, 5.0F};

    for (float rate : rates)
    {
        State saved = State.capture();

        // Left owing several ticks by a fast run first, so any read of the accumulator shows.
        TickSpeed.setEnabled(true);
        TickSpeed.setTicks(200.0F);

