private static void creditResetOnChange() throws Exception
{
    State saved = State.capture();
    TickSpeed.setEnabled(true);
    TickSpeed.setTicks(200.0F);

    // Planted rather than built up by running ticks, so the value going in is known exactly.
    write(TickSpeed.class, "credit", Double.valueOf(0.9D));
    TickSpeed.setTicks(20.0F);
    near("changing the rate clears the credit", credit(), 0.0D, 0.0D);

    int world = 0;

    for (int i = 0; i < 100; ++i)
    {
        if (TickSpeed.isWorldTick())
        {
            ++world;
        }
    }

    check("every tick follows the rate change", world == 100);

    // And the same when going the other way, where leftover credit would carry as debt and
    // release a burst of world ticks over the first second.
    write(TickSpeed.class, "credit", Double.valueOf(0.9D));
    TickSpeed.setTicks(200.0F);
    near("changing back clears the credit too", credit(), 0.0D, 0.0D);

    int high = 0;

    for (int i = 0; i < 1000; ++i)
    {
        if (TickSpeed.isWorldTick())
        {
            ++high;
        }
    }

    near("1000 ticks at 200 gives 100 world ticks", high, 100.0D, 1.0D);

    // Switching the mod off and on again must start clean as well.
    TickSpeed.setEnabled(false);
    TickSpeed.setEnabled(true);
    near("re-enabling clears the credit", credit(), 0.0D, 0.0D);

    State.restore(saved);
}

