/**
 * A timer with only its rate field usable.
 *
 * <p>Allocated rather than constructed, because {@code Timer}'s constructor calls
 * {@code Minecraft.getSystemTime()}, which triggers the LWJGL native load and cannot run
 * headless. The rate is seeded with a sentinel so a check can tell "written by the mod" from
 * "never touched".</p>
 */
private static Timer bareTimer() throws Exception
{
    Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
    Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
    theUnsafe.setAccessible(true);
    Object unsafe = theUnsafe.get(null);
    Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);

    Timer timer = (Timer)allocate.invoke(unsafe, Timer.class);
    timer.ticksPerSecond = SENTINEL_RATE;
    return timer;
}

