private static void gapIsExactlyTheDelay() throws Exception
{
    for (int delay = JumpDelay.MIN_DELAY; delay <= JumpDelay.MAX_DELAY; ++delay)
    {
        State saved = State.capture();
        JumpDelay.setEnabled(true);
        JumpDelay.setDelay(delay);

        int[] jumps = holdJumpForTicks(delay == 0 ? 4 : delay * 3 + 4);

        check("a delay of " + delay + " lets a first jump through", jumps[0] == 0);

        // Zero is the odd one out: no tick is blocked, so a jump is offered on every tick,
        // and a gap of one is as tight as it gets. You still cannot jump twice in one tick,
        // and in practice the time to fall back to the ground is the real limit.
        int expectedGap = Math.max(1, delay);

        for (int i = 1; i < jumps.length; ++i)
        {
            check("a delay of " + delay + " gives a gap of " + expectedGap + ", got " + (jumps[i] - jumps[i - 1]),
                jumps[i] - jumps[i - 1] == expectedGap);
        }

        State.restore(saved);
    }
}

