/** The statics both mods keep between calls, saved whole and put back. */
private static final class State
{
    private final boolean tickEnabled;
    private final float ticks;
    private final double credit;
    private final boolean jumpEnabled;
    private final int delay;
    private final int cooldown;
    private final boolean allowed;

    private State(boolean tickEnabled, float ticks, double credit,
        boolean jumpEnabled, int delay, int cooldown, boolean allowed)
    {
        this.tickEnabled = tickEnabled;
        this.ticks = ticks;
        this.credit = credit;
        this.jumpEnabled = jumpEnabled;
        this.delay = delay;
        this.cooldown = cooldown;
        this.allowed = allowed;
    }

    static State capture() throws Exception
    {
        return new State(TickSpeed.isEnabled(), TickSpeed.getTicks(), credit(),
            JumpDelay.isEnabled(), JumpDelay.getDelay(), JumpDelay.getCooldown(),
            (Boolean)field(JumpDelay.class, "allowed").get(null));
    }

    static void restore(State saved) throws Exception
    {
        // Straight field writes, so a restore cannot itself call save() and rewrite the config
        // file the run is trying to leave alone.
        write(TickSpeed.class, "enabled", Boolean.valueOf(saved.tickEnabled));
        write(TickSpeed.class, "ticks", Float.valueOf(saved.ticks));
        write(TickSpeed.class, "credit", Double.valueOf(saved.credit));
        write(JumpDelay.class, "enabled", Boolean.valueOf(saved.jumpEnabled));
        write(JumpDelay.class, "delay", Integer.valueOf(saved.delay));
        write(JumpDelay.class, "cooldown", Integer.valueOf(saved.cooldown));
        write(JumpDelay.class, "allowed", Boolean.valueOf(saved.allowed));
    }
}

private static Field field(Class<?> owner, String name) throws Exception
{
    Field field = owner.getDeclaredField(name);
    field.setAccessible(true);
    return field;
}

