package net.minecraft.client.commands;

public final class ThrProbe
{
    // Same accumulator, threshold 1.0 vs 0.9 vs 0.5. The step 20/rate is only ever taken when
    // rate > 20, so it is always below 1.
    public static void main(String[] args)
    {
        float[] rates = {20.02F, 21.0F, 23.53F, 25.0F, 30.0F, 33.33F, 60.0F, 137.5F, 200.0F};
        double[] thresholds = {1.0D, 0.9D, 0.5D};

        for (float rate : rates)
        {
            StringBuilder line = new StringBuilder("rate " + rate + ": ");

            for (double t : thresholds)
            {
                line.append("t=" + t + " -> " + worldPerSecond(rate, t) + "   ");
            }

            System.out.println(line);
        }
    }

    private static double worldPerSecond(float rate, double threshold)
    {
        double credit = 0.0D;
        int world = 0;
        int n = 2000000;

        for (int i = 0; i < n; ++i)
        {
            credit += 20.0D / (double)rate;

            if (credit >= threshold)
            {
                credit -= 1.0D;
                ++world;
            }
        }

        return (double)world * (double)rate / (double)n;
    }
}
