// --- wiring ------------------------------------------------------------------

/**
 * The gates in {@code Minecraft}, checked against the source rather than by running it.
 *
 * <p>{@code runTick} needs a display and a world, so the split cannot be exercised headless,
 * which leaves the one thing most likely to rot unverified: a new line added to the world
 * section, or someone tidying one guard back to {@code !isGamePaused}, and the client quietly
 * runs its physics, sound or particles at the raised rate again. Reading the file catches that
 * at build time.</p>
 */
private static void gatesWiredUp() throws Exception
{
    File minecraft = source("net", "minecraft", "client", "Minecraft.java");

    if (!minecraft.exists())
    {
        check("Minecraft.java was found to check the tick speed gates", false);
        return;
    }

    String source = read(minecraft);

    // The rate has to be applied before the timer turns it into a tick count.
    check("the rate is applied to the timer", source.contains("TickSpeed.applyTo(this.timer)"));
    check("the rate is applied before the timer is updated",
        source.indexOf("TickSpeed.applyTo(this.timer)") < source.indexOf("this.timer.updateTimer()"));

    check("the world gate is a single named flag", source.contains("boolean worldTick ="));

    // Pause first, so a paused game neither eats the schedule nor builds up a backlog.
    int gate = source.indexOf("boolean worldTick = !this.isGamePaused && TickSpeed.isWorldTick()");
    check("the world gate tests the pause before taking a tick", gate >= 0);

    // Every world, sound and particle section in runTick has to be behind the flag. Counted
    // rather than named, so a guard that is silently reverted shows up as a shortfall.
    int guards = count(source, "if (worldTick)");
    check("all seven world sections are gated, found " + guards, guards == 7);

    // And nothing in that section may still be gated on the pause alone.
    int runTick = source.indexOf("public void runTick()");
    String body = runTick < 0 ? "" : source.substring(runTick);

    check("no world section is left on the pause test alone",
        body.indexOf("if (!this.isGamePaused)") < 0);

    File player = source("net", "minecraft", "client", "entity", "EntityPlayerSP.java");

    if (!player.exists())
    {
        check("EntityPlayerSP.java was found to check the jump hooks", false);
        return;
    }

    String playerSource = read(player);

    check("the jump countdown is stepped once a tick",
        playerSource.contains("boolean jumpAllowed = JumpDelay.step()"));
    check("the jump input is gated on it",
        playerSource.contains("this.isJumping = this.movementInput.jump"));
    check("the countdown is stepped before the key is read",
        playerSource.indexOf("JumpDelay.step()") < playerSource.indexOf("this.isJumping = this.movementInput.jump"));
    check("swimming is left out of the gate",
        playerSource.contains("this.isInWater() || this.isInLava()"));
    check("the gap is armed off the jump itself",
        playerSource.contains("JumpDelay.onJumped()"));
    check("the riding packet is gated on the same decision",
        playerSource.contains("this.movementInput.jump && JumpDelay.allowsJump()"));
}

/** A source file under the project's main source directory. */
private static File source(String... parts) throws Exception
{
    File dir = new File("src/main/java");

    for (String part : parts)
    {
        dir = new File(dir, part);
    }

    return dir;
}

private static int count(String haystack, String needle)
{
    int found = 0;
    int at = 0;

    while ((at = haystack.indexOf(needle, at)) >= 0)
    {
        ++found;
        at += needle.length();
    }

    return found;
}

