       State saved = State.capture();\n\n        TickSpeed.setEnabled(true);\n        TickSpeed.setTicks(60.0F);\n        check(\"a reachable rate warns about nothing\", TickSpeed.unreachable(60.0F).isEmpty());\n\n        TickSpeed.setTicks(200.0F);\n        check(\"an unreachable rate explains itself\", !TickSpeed.unreachable(15.0F).isEmpty());\n        check(\"the explanation names the per frame cap\",\n            TickSpeed.unreachable(15.0F).contains(String.valueOf(TickSpeed.MAX_TICKS_PER_FRAME)));\n\n        State.restore(saved);\n    }\n\n    // --- JumpDelay ---------------------------------------------------------------\n\n    /**\n     * A gap of N means the next jump is N ticks after this one, for every N on offer.\n     *\n     * <p>Simulated the way the hooks actually run: step the countdown, and if the key is down and\n     * the step allowed it, jump. That is the real order, and it is why the countdown has to be\n     * armed a tick short - arming the full delay gives a gap of N + 1, which is the mistake this\n     * check exists to pin down.</p>\n     */\n    private static void gapIsExactlyTheDelay()\n    {\n        for (int delay = JumpDelay.MIN_DELAY; delay <= JumpDelay.MAX_DELAY; ++delay)\n        {\n            State saved = State.capture();\n            JumpDelay.setEnabled(true);\n            JumpDelay.setDelay(delay);\n\n            int[] jumps = holdJumpForTicks(delay == 0 ? 4 : delay * 3 + 4);\n\n            check(\"a delay of \" + delay + \" lets a first jump through\", jumps[0] == 0);\n\n            for (int i = 1; i < jumps.length; ++i)\n            {\n                check(\"a delay of \" + delay + \" gives a gap of \" + delay + \", got \" + (jumps[i] - jumps[i - 1]),\n                    jumps[i] - jumps[i - 1] == delay);\n            }\n\n            State.restore(saved);\n        }\n    }\n\n    /**\n     * Letting go of the key and pressing again must not hand back a free instant jump.\n     *\n     * <p>The countdown runs whether th