// Drives the jar filename, which the launcher matches to the version folder by name.
// Keep this, the deployed folder, and the launcher version json's id in step.
rootProject.name = 'IsThatAppleClient-1.8.9'

group = 'net.example'
// The Minecraft version, without the client name. settings.gradle's rootProject.name already
// ends in the version, and Gradle appends this one, so setting both to the full name would
// produce a doubled suffix.
version = ''
